  ('PJ1-2026B-2S-W29-S1','pj',1,2026,29,1,30,'1.8.4',array[34,35]::int[],'441e9927a160371c1e0c3e636f7d6772d14bd1d84400b7ffb1d5fc3d493a1129','8bb170de8a40dba6fe060906a3fb756b2257bc9b6bc4bfeb2a7318113b6e3e55','715d2dd93e616381f7de4fb5e317e008bae7007088b12831c3d9d17a2be5d6d7','ACCEPTED_FROM_DOWNLOADED_CATATAN',false,'{"id": "PJ1-2026B-2S-W29-S1", "subject": "Pendidikan Jasmani", "year": 1, "week": 29, "session": 1, "revision": "PJ1-30MIN-REVIEW-R1", "date": "", "teaching_time": "", "minutes": 30, "sessions_per_week": 2, "weekly_minutes": 60, "title": "Guling Tenggiling", "source_title": "Guling Tenggiling", "unit": "Unit 4: Tunas Gimnas", "source_row_id": "PJ1-RPT2026-T10-R2", "source_row_literal": ["29\n\nKump A: 16.08.2026-20.08.2026\n\nKump B: 17.08.2026-21.08.2026", "4: TUNAS GIMNAS \n\nGULING TENGGILING", "1.8 Melakukan kemahiran putaran.\n2.7 Menggunakan pengetahuan prinsip mekanik bagi kemahiran imbangan dan putaran.\n\n5.1 Mematuhi dan mengamalkan elemen pengurusan dan keselamatan.", "1.8.4 Melakukan guling depan posisi tuck.\n \n2.7.2 Mengenal pasti perubahan kedudukan badan semasa melakukan guling balak, guling sisi, dan guling depan.\n\n5.1.3 Mematuhi arahan guru semasa melakukan aktiviti Pendidikan Jasmani.", "AKTIVITI PAK-21Bus Stop (Hentian Bas)\nLearning Experiences (Pengalaman Peribadi)\nBBB/BBM\nBT m/s 34-35, tikar, tilam."], "rpt_original_page_literal": "34-35", "source_pages": [34, 35], "source_pdf_pages": [42, 43], "rpt_book_pages": "34, 35", "main_standard_key": "1.8.4", "sk_code": "1.8", "sk_text": "Melakukan kemahiran putaran.", "sp_code": "1.8.4", "sp_text": "Melakukan guling depan posisi tuck.", "complementary_standards": [{"standard_key": "2.7.2", "sp_code": "2.7.2", "sp_text": "Mengenal pasti perubahan kedudukan badan semasa melakukan guling balak, guling sisi dan guling depan.", "sk_code": "2.7", "sk_text": "Mengaplikasi konsep pergerakan dan prinsip mekanik bagi kemahiran putaran.", "domain": "kognitif", "source_label": ""}, {"standard_key": "5.1.3", "sp_code": "5.1.3", "sp_text": "Mematuhi arahan guru semasa melakukan aktiviti Pendidikan Jasmani.", "sk_code": "5.1", "sk_text": "Mematuhi dan mengamalkan elemen pengurusan dan keselamatan.", "domain": "afektif", "source_label": ""}], "source_task": "Membulatkan badan dan mencuba guling depan dengan bantuan guru", "authoring_focus": "Membulatkan badan dan mencuba guling depan dengan bantuan guru", "source_hold": "Teks RPT, DSKP dan buku dibaca. Semakan imej guling BT35 dan kod DSKP hlm70 terhalang ralat402; OCR dan teks salinan menyokong kod berulang, bukan kelulusan visual. Guru perlu menilai postur, alat dan kesediaan setiap murid.", "practical_required": true, "warmup_required": true, "cooldown_required": true, "facility_replacement": false, "facility_replacement_note": "", "source_subset_focus": true, "source_subset_note": "Fokus dan bantuan mengikut sesi; jangan menyamakan ansur maju, pemerhatian atau bantuan dengan semua lakuan sumber yang lengkap.", "adaptation_note": "Tilam sesuai dan guru mahir disahkan guru. Satu lorong guling diawasi terus; murid bukan penyokong tubuh rakan. Posisi tuck dan ayunan ialah ansur maju, bukan bukti guling penuh. Permukaan rata dipilih; tiada cerun buatan daripada meja. Pengetahuan 2.7.2 merangkumi guling balak, sisi dan depan melalui tunjuk cara guru; amali fokus guling depan.", "privacy_adaptation": false, "privacy_note": "", "held_standards": [], "source_code_conflict": false, "source_code_note": "", "unperformed_literal_elements": [], "source_mapping_review": "20 RPH, dua sesi30minit seminggu dibenarkan guru. S1/S2 ialah cadangan pecahan RPT mingguan, bukan nombor sesi yang tercetak dalam RPT.", "routine_book_pages": [46, 47], "active": false, "production_write_performed": false, "presentation_review": "PENDING_TEACHER_REVIEW", "safety": ["Guru memeriksa pakaian, tali kasut, keadaan murid, permukaan tempat aktiviti dan alatan sebelum bermula.", "Murid berhenti dan memberitahu guru jika sakit, pening atau sukar bernafas. Rehat dan minum dibenarkan mengikut keperluan.", "Guru memastikan semua murid berada dalam pandangannya. Murid tidak menolak, menarik atau menghalang laluan rakan.", "Guling hanya dengan guru mahir di sisi dan tilam sesuai. Murid lain tidak menjadi penyokong tubuh.", "Tiada tolak kepala, tarik leher, lompatan masuk ke guling atau guling berulang laju. Jangan bina cerun daripada meja, kerusi atau tilam bertindan.", "Jika sakit leher, sakit belakang atau pening, hentikan semua percubaan termasuk ansur maju dan beri perhatian mengikut tatacara sekolah. Murid yang sihat tetapi takut atau belum bersedia boleh memilih posisi tuck duduk sahaja jika selesa; catat guling penuh belum dibuat.", "Murid menunggu di luar lorong dan keluar di sisi selepas stabil. Hentikan aktiviti lain jika guru perlu memberi tumpuan penuh."], "weather_plan": "Jika hujan, kilat, panas melampau atau lantai licin, guru menggunakan ruang berbumbung yang selamat. Jika ruang tidak sesuai, aktiviti berisiko ditangguhkan dan perkara yang belum dilaksanakan dicatat.", "reflection": "Murid yang telah diperhatikan: ____ daripada ____. Kemahiran yang dikuasai: __________. Murid yang masih memerlukan bimbingan atau belum mendapat giliran: __________.", "activity_name": "Posisi tuck dan percubaan guling depan", "objective": "Murid dapat melakukan guling depan posisi tuck dengan bantuan guru mengikut kesediaan.", "success_criteria": ["Mencuba satu guling depan dengan badan membulat dan tamat stabil jika telah bersedia; bantuan dicatat.", "Membezakan bentuk atau arah guling balak, guling sisi dan guling depan."], "prior_knowledge": "Murid pernah membuat bentuk badan mudah. Guru menyemak kesediaan, bukan menganggap semua sudah menguasai.", "equipment": [{"item": "Tilam gimnastik rata dan stabil", "quantity": "Satu lorong tilam bersambung tanpa ruang terbuka; satu tilam latihan bentuk di sisi.", "use": "Seorang murid berguling di hadapan guru. Tilam sisi hanya untuk posisi tuck duduk, bukan guling tanpa pengawasan."}, {"item": "Kon", "quantity": "Empat kon di luar tepi tilam.", "use": "Menandakan tempat menunggu dan laluan keluar, bukan halangan di atas tilam."}, {"item": "Air minuman sendiri dan jam guru", "quantity": "Mengikut murid; satu jam guru.", "use": "Rehat, minum dan pengurusan giliran."}], "preparation": ["Guru mahir memeriksa tilam tidak licin, renggang atau bertindih. Hanya permukaan rata digunakan.", "Tetapkan satu lorong aktif di hadapan guru dan laluan keluar di sisi. Seorang sahaja berguling pada satu masa.", "Semak murid boleh membulatkan badan dan mengikut arahan. Murid belum bersedia berlatih posisi tuck duduk sahaja."], "organisation": ["Murid berpasangan untuk melihat dan memberi respons lisan sahaja. Guru memanggil seorang ke lorong.", "Murid menunggu duduk di luar lorong. Posisi tuck duduk boleh dicuba di tilam sisi apabila guru dapat mengawasi.", "Utamakan giliran yang selamat. Baki murid dijadualkan kemudian; tiada paksaan guling penuh."], "movement_cues": ["Mula mencangkung stabil. Tangan terbuka di tilam selebar bahu dan jari menghala ke hadapan.", "Bulatkan badan dan rapatkan dagu ke dada dengan selesa. Guru mahir membimbing pemindahan berat melalui tangan ke bahu dan belakang atas, bukan ke ubun-ubun atau leher.", "Guling perlahan dalam bentuk tuck. Tamat mencangkung atau duduk stabil mengikut kesediaan; jangan paksa berdiri tanpa bantuan.", "Guling balak menggunakan bentuk lurus mendatar, guling sisi membulat ke sisi, manakala guling depan membulat ke hadapan. Guru menunjukkan ketiga-tiganya untuk perbandingan pengetahuan."], "timing_note": "Persediaan, pemanasan, latihan, pertukaran, rehat dan penyejukan termasuk dalam 30 minit; bukan perlumbaan bilangan guling.", "values": "Kerjasama, disiplin dan menjaga keselamatan rakan.", "classroom_example": {"teacher_says": "Bulatkan badan. Tunggu arahan saya sebelum berguling.", "pupils_do": "Murid menunjukkan tuck dan masuk lorong apabila dipanggil.", "teacher_checks": "Guru menyemak tangan, dagu dan bahu; berhenti jika berat bertumpu pada kepala."}, "bbm": ["Tilam gimnastik rata dan stabil — Satu lorong tilam bersambung tanpa ruang terbuka; satu tilam latihan bentuk di sisi.", "Kon — Empat kon di luar tepi tilam.", "Air minuman sendiri dan jam guru — Mengikut murid; satu jam guru.", "Buku teks dan senarai semak pemerhatian guru."], "pak21": "Murid berlatih berpasangan atau dalam kumpulan kecil. Setiap murid mendapat giliran sendiri. Rakan memberi teguran ringkas secara sopan tanpa mengambil alih tugasan.", "phases": [{"name": "Persediaan murid dan alatan", "minutes": 2, "teacher": ["Guru memeriksa pakaian, tali kasut, keadaan murid dan alatan.", "Guru menerangkan tempat mula, laluan aktiviti dan arahan berhenti."], "pupils": ["Murid memberitahu guru jika tidak sihat.", "Murid mengambil tempat yang ditetapkan dan mendengar arahan."], "check": "Semua murid tahu tempat menunggu dan boleh berhenti apabila diarahkan.", "resources": ["Tilam gimnastik rata dan stabil", "Kon", "Air minuman sendiri dan jam guru"]}, {"name": "Pemanasan badan", "minutes": 4, "teacher": ["Guru memimpin berjalan setempat dan langkah ke sisi selama dua minit.", "Guru membimbing gerakan ringan bahu, tangan, buku lali dan lutut selama dua minit."], "pupils": ["Murid bergerak dalam ruang sendiri tanpa bersentuh.", "Murid bernafas seperti biasa dan berehat jika perlu."], "check": "Murid bersedia untuk aktiviti tanpa terlalu penat.", "resources": ["Ruang lapang", "Kon penanda"]}, {"name": "Tunjuk bentuk dan arah", "minutes": 4, "teacher": ["Guru menunjukkan guling balak, sisi dan depan secara ringkas pada tilam.", "Guru menunjukkan posisi tuck serta tangan dan dagu sebelum guling depan."], "pupils": ["Murid melihat bentuk dan arah guru.", "Murid menyebut balak lurus, sisi ke sisi dan depan ke hadapan."], "check": "Tiga jenis dikenal pasti; menonton bukan bukti amali.", "resources": ["Tilam"]}, {"name": "Bulatkan badan dan cuba", "minutes": 9, "teacher": ["Guru membimbing tuck duduk dan ayunan kecil tanpa tekanan pada leher.", "Guru memanggil seorang murid, menyemak kesediaan dan membimbing guling depan jika sesuai.", "Guru memberi arahan pendek dan mengawal giliran; bantuan fizikal hanya oleh guru mahir."], "pupils": ["Murid membulatkan badan ketika gilirannya.", "Murid yang bersedia mencuba guling depan dengan bantuan guru dan tamat stabil.", "Murid belum bersedia kekal pada posisi awal tanpa dipaksa."], "check": "Catat ansur maju dan percubaan penuh secara berasingan.", "resources": ["Lorong tilam", "Kon"]}, {"name": "Ulang satu langkah yang perlu", "minutes": 7, "teacher": ["Guru memberi satu pembetulan, seperti merapatkan dagu atau meletakkan tangan.", "Guru memberi giliran lanjut serta rehat/minum mengikut keperluan."], "pupils": ["Murid mencuba semula langkah yang dibenarkan.", "Murid keluar di sisi selepas stabil dan memberi giliran rakan.", "Murid menyebut satu perbezaan balak, sisi dan depan sambil menunggu."], "check": "Ulangan meningkatkan kawalan, bukan kelajuan.", "resources": ["Tilam", "Air sendiri"]}, {"name": "Penyejukan badan dan penutup", "minutes": 4, "teacher": ["Guru memimpin berjalan perlahan selama satu minit dan regangan lembut tangan serta kaki selama dua minit.", "Guru memberi masa minum dan menanyakan satu perkara yang dipelajari."], "pupils": ["Murid meregang mengikut keselesaan tanpa sentapan.", "Murid memberitahu guru jika masih tidak selesa dan membantu mengemas alatan ringan selepas arahan."], "check": "Tiada latihan kuat selepas penyejukan. Guru mencatat perkara yang perlu disusuli.", "resources": ["Air minuman", "Ruang rehat"]}], "differentiation": {"support": {"label": "Peneroka", "support_description": "Guru membimbing satu langkah pada satu masa.", "task": "Membulatkan badan dan mencuba guling apabila bersedia.", "materials": ["Tilam", "Kon"], "teacher": ["Guru menunjukkan tuck duduk satu langkah pada satu masa.", "Guru berada dekat semasa percubaan; hentikan jika murid belum bersedia."], "pupil_steps": ["Duduk dan bulatkan badan dengan dagu dirapatkan selesa.", "Tunjukkan tangan pada tilam dan cuba guling depan hanya dengan izin guru.", "Tamat stabil atau kembali ke latihan posisi jika belum bersedia.", "Bezakan balak, sisi dan depan melalui pilihan kata guru."], "product": "Posisi atau percubaan guling sebenar serta respons tiga jenis.", "criterion": "Guru mencatat tahap sebenar; tuck duduk tidak dikira guling penuh.", "next_step": "Ulang posisi awal dalam giliran berikutnya.", "example": {"teacher": "Balak lurus atau membulat?", "pupil": "Balak lurus; depan membulat."}}, "core": {"label": "Pembina", "support_description": "Murid berlatih berpasangan dan melakukan sendiri.", "task": "Mencuba guling depan dengan urutan tangan, tuck dan tamat.", "materials": ["Tilam rata"], "teacher": ["Guru menyemak posisi awal sebelum memberi arahan mula.", "Beri satu petunjuk semasa murid memerlukan bantuan."], "pupil_steps": ["Mencangkung dan letakkan tangan di tilam.", "Bulatkan badan dan guling ke hadapan dengan pengawasan guru.", "Tamat stabil dan keluar melalui sisi.", "Sebut perbezaan arah balak, sisi dan depan selepas demonstrasi."], "product": "Satu percubaan individu dan penerangan ringkas.", "criterion": "Sokongan tidak tertumpu pada kepala; bantuan direkod dengan jujur.", "next_step": "Perkemas satu langkah tanpa menambah laju.", "example": {"teacher": "Bilakah kamu mula?", "pupil": "Selepas guru memberi arahan."}}, "challenge": {"label": "Pencabar", "support_description": "Murid memperkemas satu perkara dalam kemahiran yang sama.", "task": "Memperkemas bentuk tuck dalam satu guling yang selamat.", "materials": ["Tilam rata"], "teacher": ["Guru memilih satu aspek yang sudah hampir betul.", "Jangan menambah guling bersambung atau lompatan."], "pupil_steps": ["Semak tangan dan dagu pada posisi awal.", "Lakukan satu guling depan yang guru benarkan.", "Kekalkan bentuk membulat dan berhenti stabil.", "Terangkan beza balak lurus, sisi ke sisi dan depan ke hadapan."], "product": "Percubaan terkawal dengan satu pembetulan sendiri.", "criterion": "Kawalan bertambah tanpa kelajuan atau risiko tambahan.", "next_step": "Ulang hanya jika guru menilai selamat.", "example": {"teacher": "Bagaimana hendak mudah berguling?", "pupil": "Bulatkan badan dan ikut arahan guru."}}}, "differentiation_delivery": {"common_task": "Murid dapat melakukan guling depan posisi tuck dengan bantuan guru mengikut kesediaan.", "placement": "Bimbingan ini diberikan dalam waktu latihan dan aplikasi. Murid tidak perlu menjalani tiga kumpulan bantuan sebagai aktiviti tambahan.", "teacher_rounds": ["Bimbing Peneroka dekat guru.", "Semak permulaan Pembina.", "Perkemas bentuk Pencabar tanpa cabaran baharu."], "individual_check": "Mencuba satu guling depan dengan badan membulat dan tamat stabil jika telah bersedia; bantuan dicatat.", "flexible_help": "Bantuan diteruskan selagi diperlukan. Murid tidak dipaksa menambah kelajuan, jarak, beban atau ulangan untuk menunjukkan kemajuan."}, "pbd": {"method": "Pemerhatian dekat guru mahir.", "evidence": "Percubaan guling depan posisi tuck murid sendiri.", "criterion": "Badan membulat, sokongan selamat dan tamat stabil. Posisi tuck sahaja ialah ansur maju, bukan guling penuh.", "recording": "Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP.", "sample_checklist": ["Posisi awal: ____", "Guling sebenar / ansur maju sahaja: ____", "Bantuan / belum mendapat giliran: ____"]}, "pbd_complementary": {"2.7.2": {"method": "Soal jawab selepas demonstrasi guru.", "evidence": "Respons individu tentang bentuk atau arah balak, sisi dan depan.", "criterion": "Murid mengenal perbezaan ketiga-tiga jenis dengan bantuan jika perlu.", "recording": "Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP.", "sample_checklist": ["Balak: ____", "Sisi: ____", "Depan: ____", "Bantuan: ____"]}, "5.1.3": {"method": "Pemerhatian sepanjang giliran.", "evidence": "Murid masuk selepas dipanggil, berhenti dan keluar melalui sisi.", "criterion": "Mematuhi arahan tanpa pasangan menyokong tubuh.", "recording": "Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP.", "sample_checklist": ["Tunggu arahan: ____", "Berhenti dan keluar: ____", "Bimbingan diperlukan: ____"]}}, "intervention": ["Kekalkan tuck duduk bagi murid belum bersedia.", "Beri giliran susulan; jangan menganggap menonton sebagai guling sendiri."], "book_pages_text": "34, 35", "sp_focus": "", "sp_display": "1.8.4", "complementary": [{"standard_key": "2.7.2", "sp_code": "2.7.2", "sp_text": "Mengenal pasti perubahan kedudukan badan semasa melakukan guling balak, guling sisi dan guling depan.", "sk_code": "2.7", "sk_text": "Mengaplikasi konsep pergerakan dan prinsip mekanik bagi kemahiran putaran.", "domain": "kognitif", "source_label": ""}, {"standard_key": "5.1.3", "sp_code": "5.1.3", "sp_text": "Mematuhi arahan guru semasa melakukan aktiviti Pendidikan Jasmani.", "sk_code": "5.1", "sk_text": "Mematuhi dan mengamalkan elemen pengurusan dan keselamatan.", "domain": "afektif", "source_label": ""}], "draft_sha256": "ca27218447136d46212dbbf19391f6744ccbde2eeb796ff4dfe75111a95f6490"}'::jsonb,'[{"kind": "title", "text": "Minggu 29 Sesi 1 — Posisi tuck dan percubaan guling depan"}, {"kind": "subtitle", "text": "Pendidikan Jasmani Tahun 1 | Dua sesi seminggu | 30 minit setiap sesi | R1"}, {"kind": "p", "text": "ID: PJ1-2026B-2S-W29-S1"}, {"kind": "h2", "text": "A. Maklumat pengajaran"}, {"kind": "p", "text": "Guru: ____________________ | Kelas: __________ | Tarikh: __________ | Waktu: __________"}, {"kind": "p", "text": "Unit 4: Tunas Gimnas"}, {"kind": "p", "text": "Tajuk buku teks: Guling Tenggiling"}, {"kind": "p", "text": "Aktiviti guru: Posisi tuck dan percubaan guling depan"}, {"kind": "p", "text": "Rujukan buku teks PJPK Tahun 1, bahagian PJ: muka surat 34, 35."}, {"kind": "p", "text": "Persediaan, pemanasan, latihan, pertukaran, rehat dan penyejukan termasuk dalam 30 minit; bukan perlumbaan bilangan guling."}, {"kind": "h2", "text": "B. Standard dan hasil pembelajaran"}, {"kind": "p", "text": "SK utama 1.8: Melakukan kemahiran putaran."}, {"kind": "p", "text": "SP utama 1.8.4: Melakukan guling depan posisi tuck."}, {"kind": "p", "text": "SK sokongan 2.7: Mengaplikasi konsep pergerakan dan prinsip mekanik bagi kemahiran putaran."}, {"kind": "p", "text": "SP sokongan 2.7.2: Mengenal pasti perubahan kedudukan badan semasa melakukan guling balak, guling sisi dan guling depan."}, {"kind": "p", "text": "SK sokongan 5.1: Mematuhi dan mengamalkan elemen pengurusan dan keselamatan."}, {"kind": "p", "text": "SP sokongan 5.1.3: Mematuhi arahan guru semasa melakukan aktiviti Pendidikan Jasmani."}, {"kind": "p", "text": "Fokus dan bantuan mengikut sesi; jangan menyamakan ansur maju, pemerhatian atau bantuan dengan semua lakuan sumber yang lengkap."}, {"kind": "label", "text": "Objektif"}, {"kind": "p", "text": "Murid dapat melakukan guling depan posisi tuck dengan bantuan guru mengikut kesediaan."}, {"kind": "label", "text": "Kriteria kejayaan"}, {"kind": "p", "text": "1. Mencuba satu guling depan dengan badan membulat dan tamat stabil jika telah bersedia; bantuan dicatat."}, {"kind": "p", "text": "2. Membezakan bentuk atau arah guling balak, guling sisi dan guling depan."}, {"kind": "p", "text": "Pengetahuan sedia ada: Murid pernah membuat bentuk badan mudah. Guru menyemak kesediaan, bukan menganggap semua sudah menguasai."}, {"kind": "h2", "text": "C. Alatan, persediaan dan keselamatan"}, {"kind": "label", "text": "Tilam gimnastik rata dan stabil"}, {"kind": "p", "text": "Keperluan: Satu lorong tilam bersambung tanpa ruang terbuka; satu tilam latihan bentuk di sisi."}, {"kind": "p", "text": "Kegunaan: Seorang murid berguling di hadapan guru. Tilam sisi hanya untuk posisi tuck duduk, bukan guling tanpa pengawasan."}, {"kind": "label", "text": "Kon"}, {"kind": "p", "text": "Keperluan: Empat kon di luar tepi tilam."}, {"kind": "p", "text": "Kegunaan: Menandakan tempat menunggu dan laluan keluar, bukan halangan di atas tilam."}, {"kind": "label", "text": "Air minuman sendiri dan jam guru"}, {"kind": "p", "text": "Keperluan: Mengikut murid; satu jam guru."}, {"kind": "p", "text": "Kegunaan: Rehat, minum dan pengurusan giliran."}, {"kind": "label", "text": "Persediaan guru"}, {"kind": "p", "text": "1. Guru mahir memeriksa tilam tidak licin, renggang atau bertindih. Hanya permukaan rata digunakan."}, {"kind": "p", "text": "2. Tetapkan satu lorong aktif di hadapan guru dan laluan keluar di sisi. Seorang sahaja berguling pada satu masa."}, {"kind": "p", "text": "3. Semak murid boleh membulatkan badan dan mengikut arahan. Murid belum bersedia berlatih posisi tuck duduk sahaja."}, {"kind": "label", "text": "Susunan dan giliran murid"}, {"kind": "p", "text": "1. Murid berpasangan untuk melihat dan memberi respons lisan sahaja. Guru memanggil seorang ke lorong."}, {"kind": "p", "text": "2. Murid menunggu duduk di luar lorong. Posisi tuck duduk boleh dicuba di tilam sisi apabila guru dapat mengawasi."}, {"kind": "p", "text": "3. Utamakan giliran yang selamat. Baki murid dijadualkan kemudian; tiada paksaan guling penuh."}, {"kind": "label", "text": "Petunjuk pergerakan"}, {"kind": "p", "text": "1. Mula mencangkung stabil. Tangan terbuka di tilam selebar bahu dan jari menghala ke hadapan."}, {"kind": "p", "text": "2. Bulatkan badan dan rapatkan dagu ke dada dengan selesa. Guru mahir membimbing pemindahan berat melalui tangan ke bahu dan belakang atas, bukan ke ubun-ubun atau leher."}, {"kind": "p", "text": "3. Guling perlahan dalam bentuk tuck. Tamat mencangkung atau duduk stabil mengikut kesediaan; jangan paksa berdiri tanpa bantuan."}, {"kind": "p", "text": "4. Guling balak menggunakan bentuk lurus mendatar, guling sisi membulat ke sisi, manakala guling depan membulat ke hadapan. Guru menunjukkan ketiga-tiganya untuk perbandingan pengetahuan."}, {"kind": "label", "text": "BBM"}, {"kind": "p", "text": "1. Tilam gimnastik rata dan stabil — Satu lorong tilam bersambung tanpa ruang terbuka; satu tilam latihan bentuk di sisi."}, {"kind": "p", "text": "2. Kon — Empat kon di luar tepi tilam."}, {"kind": "p", "text": "3. Air minuman sendiri dan jam guru — Mengikut murid; satu jam guru."}, {"kind": "p", "text": "4. Buku teks dan senarai semak pemerhatian guru."}, {"kind": "p", "text": "PAK-21: Murid berlatih berpasangan atau dalam kumpulan kecil. Setiap murid mendapat giliran sendiri. Rakan memberi teguran ringkas secara sopan tanpa mengambil alih tugasan."}, {"kind": "p", "text": "Nilai: Kerjasama, disiplin dan menjaga keselamatan rakan."}, {"kind": "label", "text": "Keselamatan"}, {"kind": "p", "text": "1. Guru memeriksa pakaian, tali kasut, keadaan murid, permukaan tempat aktiviti dan alatan sebelum bermula."}, {"kind": "p", "text": "2. Murid berhenti dan memberitahu guru jika sakit, pening atau sukar bernafas. Rehat dan minum dibenarkan mengikut keperluan."}, {"kind": "p", "text": "3. Guru memastikan semua murid berada dalam pandangannya. Murid tidak menolak, menarik atau menghalang laluan rakan."}, {"kind": "p", "text": "4. Guling hanya dengan guru mahir di sisi dan tilam sesuai. Murid lain tidak menjadi penyokong tubuh."}, {"kind": "p", "text": "5. Tiada tolak kepala, tarik leher, lompatan masuk ke guling atau guling berulang laju. Jangan bina cerun daripada meja, kerusi atau tilam bertindan."}, {"kind": "p", "text": "6. Jika sakit leher, sakit belakang atau pening, hentikan semua percubaan termasuk ansur maju dan beri perhatian mengikut tatacara sekolah. Murid yang sihat tetapi takut atau belum bersedia boleh memilih posisi tuck duduk sahaja jika selesa; catat guling penuh belum dibuat."}, {"kind": "p", "text": "7. Murid menunggu di luar lorong dan keluar di sisi selepas stabil. Hentikan aktiviti lain jika guru perlu memberi tumpuan penuh."}, {"kind": "p", "text": "Jika cuaca atau ruang tidak sesuai: Jika hujan, kilat, panas melampau atau lantai licin, guru menggunakan ruang berbumbung yang selamat. Jika ruang tidak sesuai, aktiviti berisiko ditangguhkan dan perkara yang belum dilaksanakan dicatat."}, {"kind": "h2", "text": "D. Langkah PdP"}, {"kind": "h3", "text": "Langkah 1: Persediaan murid dan alatan — 2 minit"}, {"kind": "p", "text": "Minit 0 hingga 2."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru memeriksa pakaian, tali kasut, keadaan murid dan alatan."}, {"kind": "p", "text": "2. Guru menerangkan tempat mula, laluan aktiviti dan arahan berhenti."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid memberitahu guru jika tidak sihat."}, {"kind": "p", "text": "2. Murid mengambil tempat yang ditetapkan dan mendengar arahan."}, {"kind": "p", "text": "Semakan: Semua murid tahu tempat menunggu dan boleh berhenti apabila diarahkan."}, {"kind": "p", "text": "Alatan: Tilam gimnastik rata dan stabil Kon Air minuman sendiri dan jam guru"}, {"kind": "h3", "text": "Langkah 2: Pemanasan badan — 4 minit"}, {"kind": "p", "text": "Minit 2 hingga 6."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru memimpin berjalan setempat dan langkah ke sisi selama dua minit."}, {"kind": "p", "text": "2. Guru membimbing gerakan ringan bahu, tangan, buku lali dan lutut selama dua minit."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid bergerak dalam ruang sendiri tanpa bersentuh."}, {"kind": "p", "text": "2. Murid bernafas seperti biasa dan berehat jika perlu."}, {"kind": "p", "text": "Semakan: Murid bersedia untuk aktiviti tanpa terlalu penat."}, {"kind": "p", "text": "Alatan: Ruang lapang Kon penanda"}, {"kind": "h3", "text": "Langkah 3: Tunjuk bentuk dan arah — 4 minit"}, {"kind": "p", "text": "Minit 6 hingga 10."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru menunjukkan guling balak, sisi dan depan secara ringkas pada tilam."}, {"kind": "p", "text": "2. Guru menunjukkan posisi tuck serta tangan dan dagu sebelum guling depan."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid melihat bentuk dan arah guru."}, {"kind": "p", "text": "2. Murid menyebut balak lurus, sisi ke sisi dan depan ke hadapan."}, {"kind": "p", "text": "Semakan: Tiga jenis dikenal pasti; menonton bukan bukti amali."}, {"kind": "p", "text": "Alatan: Tilam"}, {"kind": "h3", "text": "Langkah 4: Bulatkan badan dan cuba — 9 minit"}, {"kind": "p", "text": "Minit 10 hingga 19."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru membimbing tuck duduk dan ayunan kecil tanpa tekanan pada leher."}, {"kind": "p", "text": "2. Guru memanggil seorang murid, menyemak kesediaan dan membimbing guling depan jika sesuai."}, {"kind": "p", "text": "3. Guru memberi arahan pendek dan mengawal giliran; bantuan fizikal hanya oleh guru mahir."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid membulatkan badan ketika gilirannya."}, {"kind": "p", "text": "2. Murid yang bersedia mencuba guling depan dengan bantuan guru dan tamat stabil."}, {"kind": "p", "text": "3. Murid belum bersedia kekal pada posisi awal tanpa dipaksa."}, {"kind": "p", "text": "Semakan: Catat ansur maju dan percubaan penuh secara berasingan."}, {"kind": "p", "text": "Alatan: Lorong tilam Kon"}, {"kind": "h3", "text": "Langkah 5: Ulang satu langkah yang perlu — 7 minit"}, {"kind": "p", "text": "Minit 19 hingga 26."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru memberi satu pembetulan, seperti merapatkan dagu atau meletakkan tangan."}, {"kind": "p", "text": "2. Guru memberi giliran lanjut serta rehat/minum mengikut keperluan."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid mencuba semula langkah yang dibenarkan."}, {"kind": "p", "text": "2. Murid keluar di sisi selepas stabil dan memberi giliran rakan."}, {"kind": "p", "text": "3. Murid menyebut satu perbezaan balak, sisi dan depan sambil menunggu."}, {"kind": "p", "text": "Semakan: Ulangan meningkatkan kawalan, bukan kelajuan."}, {"kind": "p", "text": "Alatan: Tilam Air sendiri"}, {"kind": "h3", "text": "Langkah 6: Penyejukan badan dan penutup — 4 minit"}, {"kind": "p", "text": "Minit 26 hingga 30."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru memimpin berjalan perlahan selama satu minit dan regangan lembut tangan serta kaki selama dua minit."}, {"kind": "p", "text": "2. Guru memberi masa minum dan menanyakan satu perkara yang dipelajari."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid meregang mengikut keselesaan tanpa sentapan."}, {"kind": "p", "text": "2. Murid memberitahu guru jika masih tidak selesa dan membantu mengemas alatan ringan selepas arahan."}, {"kind": "p", "text": "Semakan: Tiada latihan kuat selepas penyejukan. Guru mencatat perkara yang perlu disusuli."}, {"kind": "p", "text": "Alatan: Air minuman Ruang rehat"}, {"kind": "p", "text": "Jumlah masa: 30 minit."}, {"kind": "label", "text": "Contoh arahan kelas"}, {"kind": "p", "text": "Guru: Bulatkan badan. Tunggu arahan saya sebelum berguling."}, {"kind": "p", "text": "Murid: Murid menunjukkan tuck dan masuk lorong apabila dipanggil."}, {"kind": "p", "text": "Semakan guru: Guru menyemak tangan, dagu dan bahu; berhenti jika berat bertumpu pada kepala."}, {"kind": "h2", "text": "E. PdP terbeza", "anchor": "pdp-PJ1-2026B-2S-W29-S1"}, {"kind": "p", "text": "Tugasan bersama: Murid dapat melakukan guling depan posisi tuck dengan bantuan guru mengikut kesediaan."}, {"kind": "p", "text": "Bimbingan ini diberikan dalam waktu latihan dan aplikasi. Murid tidak perlu menjalani tiga kumpulan bantuan sebagai aktiviti tambahan."}, {"kind": "label", "text": "Bimbingan guru"}, {"kind": "p", "text": "1. Bimbing Peneroka dekat guru."}, {"kind": "p", "text": "2. Semak permulaan Pembina."}, {"kind": "p", "text": "3. Perkemas bentuk Pencabar tanpa cabaran baharu."}, {"kind": "p", "text": "Semakan individu: Mencuba satu guling depan dengan badan membulat dan tamat stabil jika telah bersedia; bantuan dicatat."}, {"kind": "p", "text": "Bantuan diteruskan selagi diperlukan. Murid tidak dipaksa menambah kelajuan, jarak, beban atau ulangan untuk menunjukkan kemajuan."}, {"kind": "h3", "text": "Peneroka"}, {"kind": "p", "text": "Guru membimbing satu langkah pada satu masa."}, {"kind": "p", "text": "Tugasan: Membulatkan badan dan mencuba guling apabila bersedia."}, {"kind": "label", "text": "Alatan"}, {"kind": "p", "text": "1. Tilam"}, {"kind": "p", "text": "2. Kon"}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru menunjukkan tuck duduk satu langkah pada satu masa."}, {"kind": "p", "text": "2. Guru berada dekat semasa percubaan; hentikan jika murid belum bersedia."}, {"kind": "label", "text": "Langkah murid"}, {"kind": "p", "text": "1. Duduk dan bulatkan badan dengan dagu dirapatkan selesa."}, {"kind": "p", "text": "2. Tunjukkan tangan pada tilam dan cuba guling depan hanya dengan izin guru."}, {"kind": "p", "text": "3. Tamat stabil atau kembali ke latihan posisi jika belum bersedia."}, {"kind": "p", "text": "4. Bezakan balak, sisi dan depan melalui pilihan kata guru."}, {"kind": "p", "text": "Contoh guru: Balak lurus atau membulat?"}, {"kind": "p", "text": "Contoh respons murid: Balak lurus; depan membulat."}, {"kind": "p", "text": "Hasil individu: Posisi atau percubaan guling sebenar serta respons tiga jenis."}, {"kind": "p", "text": "Kriteria: Guru mencatat tahap sebenar; tuck duduk tidak dikira guling penuh."}, {"kind": "p", "text": "Susulan: Ulang posisi awal dalam giliran berikutnya."}, {"kind": "h3", "text": "Pembina"}, {"kind": "p", "text": "Murid berlatih berpasangan dan melakukan sendiri."}, {"kind": "p", "text": "Tugasan: Mencuba guling depan dengan urutan tangan, tuck dan tamat."}, {"kind": "label", "text": "Alatan"}, {"kind": "p", "text": "1. Tilam rata"}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru menyemak posisi awal sebelum memberi arahan mula."}, {"kind": "p", "text": "2. Beri satu petunjuk semasa murid memerlukan bantuan."}, {"kind": "label", "text": "Langkah murid"}, {"kind": "p", "text": "1. Mencangkung dan letakkan tangan di tilam."}, {"kind": "p", "text": "2. Bulatkan badan dan guling ke hadapan dengan pengawasan guru."}, {"kind": "p", "text": "3. Tamat stabil dan keluar melalui sisi."}, {"kind": "p", "text": "4. Sebut perbezaan arah balak, sisi dan depan selepas demonstrasi."}, {"kind": "p", "text": "Contoh guru: Bilakah kamu mula?"}, {"kind": "p", "text": "Contoh respons murid: Selepas guru memberi arahan."}, {"kind": "p", "text": "Hasil individu: Satu percubaan individu dan penerangan ringkas."}, {"kind": "p", "text": "Kriteria: Sokongan tidak tertumpu pada kepala; bantuan direkod dengan jujur."}, {"kind": "p", "text": "Susulan: Perkemas satu langkah tanpa menambah laju."}, {"kind": "h3", "text": "Pencabar"}, {"kind": "p", "text": "Murid memperkemas satu perkara dalam kemahiran yang sama."}, {"kind": "p", "text": "Tugasan: Memperkemas bentuk tuck dalam satu guling yang selamat."}, {"kind": "label", "text": "Alatan"}, {"kind": "p", "text": "1. Tilam rata"}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru memilih satu aspek yang sudah hampir betul."}, {"kind": "p", "text": "2. Jangan menambah guling bersambung atau lompatan."}, {"kind": "label", "text": "Langkah murid"}, {"kind": "p", "text": "1. Semak tangan dan dagu pada posisi awal."}, {"kind": "p", "text": "2. Lakukan satu guling depan yang guru benarkan."}, {"kind": "p", "text": "3. Kekalkan bentuk membulat dan berhenti stabil."}, {"kind": "p", "text": "4. Terangkan beza balak lurus, sisi ke sisi dan depan ke hadapan."}, {"kind": "p", "text": "Contoh guru: Bagaimana hendak mudah berguling?"}, {"kind": "p", "text": "Contoh respons murid: Bulatkan badan dan ikut arahan guru."}, {"kind": "p", "text": "Hasil individu: Percubaan terkawal dengan satu pembetulan sendiri."}, {"kind": "p", "text": "Kriteria: Kawalan bertambah tanpa kelajuan atau risiko tambahan."}, {"kind": "p", "text": "Susulan: Ulang hanya jika guru menilai selamat."}, {"kind": "h2", "text": "F. Pentaksiran Bilik Darjah"}, {"kind": "h3", "text": "PBD utama — SP 1.8.4"}, {"kind": "p", "text": "Kaedah: Pemerhatian dekat guru mahir."}, {"kind": "p", "text": "Bukti: Percubaan guling depan posisi tuck murid sendiri."}, {"kind": "p", "text": "Kriteria: Badan membulat, sokongan selamat dan tamat stabil. Posisi tuck sahaja ialah ansur maju, bukan guling penuh."}, {"kind": "p", "text": "Rekod: Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP."}, {"kind": "label", "text": "Senarai semak"}, {"kind": "p", "text": "1. Posisi awal: ____"}, {"kind": "p", "text": "2. Guling sebenar / ansur maju sahaja: ____"}, {"kind": "p", "text": "3. Bantuan / belum mendapat giliran: ____"}, {"kind": "h3", "text": "PBD sokongan — SP 2.7.2"}, {"kind": "p", "text": "Kaedah: Soal jawab selepas demonstrasi guru."}, {"kind": "p", "text": "Bukti: Respons individu tentang bentuk atau arah balak, sisi dan depan."}, {"kind": "p", "text": "Kriteria: Murid mengenal perbezaan ketiga-tiga jenis dengan bantuan jika perlu."}, {"kind": "p", "text": "Rekod: Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP."}, {"kind": "label", "text": "Senarai semak"}, {"kind": "p", "text": "1. Balak: ____"}, {"kind": "p", "text": "2. Sisi: ____"}, {"kind": "p", "text": "3. Depan: ____"}, {"kind": "p", "text": "4. Bantuan: ____"}, {"kind": "h3", "text": "PBD sokongan — SP 5.1.3"}, {"kind": "p", "text": "Kaedah: Pemerhatian sepanjang giliran."}, {"kind": "p", "text": "Bukti: Murid masuk selepas dipanggil, berhenti dan keluar melalui sisi."}, {"kind": "p", "text": "Kriteria: Mematuhi arahan tanpa pasangan menyokong tubuh."}, {"kind": "p", "text": "Rekod: Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP."}, {"kind": "label", "text": "Senarai semak"}, {"kind": "p", "text": "1. Tunggu arahan: ____"}, {"kind": "p", "text": "2. Berhenti dan keluar: ____"}, {"kind": "p", "text": "3. Bimbingan diperlukan: ____"}, {"kind": "h2", "text": "G. Refleksi dan intervensi"}, {"kind": "p", "text": "Murid yang telah diperhatikan: ____ daripada ____. Kemahiran yang dikuasai: __________. Murid yang masih memerlukan bimbingan atau belum mendapat giliran: __________."}, {"kind": "label", "text": "Intervensi"}, {"kind": "p", "text": "1. Kekalkan tuck duduk bagi murid belum bersedia."}, {"kind": "p", "text": "2. Beri giliran susulan; jangan menganggap menonton sebagai guling sendiri."}]'::jsonb,'{"source_hold": "", "adaptation_note": "Tilam sesuai dan guru mahir disahkan guru. Satu lorong guling diawasi terus; murid bukan penyokong tubuh rakan. Posisi tuck dan ayunan ialah ansur maju, bukan bukti guling penuh. Permukaan rata dipilih; tiada cerun buatan daripada meja. Pengetahuan 2.7.2 merangkumi guling balak, sisi dan depan melalui tunjuk cara guru; amali fokus guling depan.", "source_images_verified": true, "audio_verified": false, "ba_verified": false, "classroom_trial_performed": false}'::jsonb),
  ('PJ1-2026B-2S-W29-S2','pj',1,2026,29,2,30,'1.8.4',array[34,35]::int[],'033f1bb350dca066ca34cbb83ee3a0a898305548a970f7a05f03a6dc896e2d5b','b5f400f03b9ab3f2b0991efabcada5789677273c9cc3ef85278e0288a634e498','715d2dd93e616381f7de4fb5e317e008bae7007088b12831c3d9d17a2be5d6d7','ACCEPTED_FROM_DOWNLOADED_CATATAN',false,'{"id": "PJ1-2026B-2S-W29-S2", "subject": "Pendidikan Jasmani", "year": 1, "week": 29, "session": 2, "revision": "PJ1-30MIN-REVIEW-R1", "date": "", "teaching_time": "", "minutes": 30, "sessions_per_week": 2, "weekly_minutes": 60, "title": "Guling Tenggiling", "source_title": "Guling Tenggiling", "unit": "Unit 4: Tunas Gimnas", "source_row_id": "PJ1-RPT2026-T10-R2", "source_row_literal": ["29\n\nKump A: 16.08.2026-20.08.2026\n\nKump B: 17.08.2026-21.08.2026", "4: TUNAS GIMNAS \n\nGULING TENGGILING", "1.8 Melakukan kemahiran putaran.\n2.7 Menggunakan pengetahuan prinsip mekanik bagi kemahiran imbangan dan putaran.\n\n5.1 Mematuhi dan mengamalkan elemen pengurusan dan keselamatan.", "1.8.4 Melakukan guling depan posisi tuck.\n \n2.7.2 Mengenal pasti perubahan kedudukan badan semasa melakukan guling balak, guling sisi, dan guling depan.\n\n5.1.3 Mematuhi arahan guru semasa melakukan aktiviti Pendidikan Jasmani.", "AKTIVITI PAK-21Bus Stop (Hentian Bas)\nLearning Experiences (Pengalaman Peribadi)\nBBB/BBM\nBT m/s 34-35, tikar, tilam."], "rpt_original_page_literal": "34-35", "source_pages": [34, 35], "source_pdf_pages": [42, 43], "rpt_book_pages": "34, 35", "main_standard_key": "1.8.4", "sk_code": "1.8", "sk_text": "Melakukan kemahiran putaran.", "sp_code": "1.8.4", "sp_text": "Melakukan guling depan posisi tuck.", "complementary_standards": [{"standard_key": "2.7.2", "sp_code": "2.7.2", "sp_text": "Mengenal pasti perubahan kedudukan badan semasa melakukan guling balak, guling sisi dan guling depan.", "sk_code": "2.7", "sk_text": "Mengaplikasi konsep pergerakan dan prinsip mekanik bagi kemahiran putaran.", "domain": "kognitif", "source_label": ""}, {"standard_key": "5.1.3", "sp_code": "5.1.3", "sp_text": "Mematuhi arahan guru semasa melakukan aktiviti Pendidikan Jasmani.", "sk_code": "5.1", "sk_text": "Mematuhi dan mengamalkan elemen pengurusan dan keselamatan.", "domain": "afektif", "source_label": ""}], "source_task": "Guling depan dan berhenti dengan terkawal", "authoring_focus": "Guling depan dan berhenti dengan terkawal", "source_hold": "Teks RPT, DSKP dan buku dibaca. Semakan imej guling BT35 dan kod DSKP hlm70 terhalang ralat402; OCR dan teks salinan menyokong kod berulang, bukan kelulusan visual. Guru perlu menilai postur, alat dan kesediaan setiap murid.", "practical_required": true, "warmup_required": true, "cooldown_required": true, "facility_replacement": false, "facility_replacement_note": "", "source_subset_focus": true, "source_subset_note": "Fokus dan bantuan mengikut sesi; jangan menyamakan ansur maju, pemerhatian atau bantuan dengan semua lakuan sumber yang lengkap.", "adaptation_note": "Tilam sesuai dan guru mahir disahkan guru. Satu lorong guling diawasi terus; murid bukan penyokong tubuh rakan. Posisi tuck dan ayunan ialah ansur maju, bukan bukti guling penuh. Permukaan rata dipilih; tiada cerun buatan daripada meja. Pengetahuan 2.7.2 merangkumi guling balak, sisi dan depan melalui tunjuk cara guru; amali fokus guling depan.", "privacy_adaptation": false, "privacy_note": "", "held_standards": [], "source_code_conflict": false, "source_code_note": "", "unperformed_literal_elements": [], "source_mapping_review": "20 RPH, dua sesi30minit seminggu dibenarkan guru. S1/S2 ialah cadangan pecahan RPT mingguan, bukan nombor sesi yang tercetak dalam RPT.", "routine_book_pages": [46, 47], "active": false, "production_write_performed": false, "presentation_review": "PENDING_TEACHER_REVIEW", "safety": ["Guru memeriksa pakaian, tali kasut, keadaan murid, permukaan tempat aktiviti dan alatan sebelum bermula.", "Murid berhenti dan memberitahu guru jika sakit, pening atau sukar bernafas. Rehat dan minum dibenarkan mengikut keperluan.", "Guru memastikan semua murid berada dalam pandangannya. Murid tidak menolak, menarik atau menghalang laluan rakan.", "Guling hanya dengan guru mahir di sisi dan tilam sesuai. Murid lain tidak menjadi penyokong tubuh.", "Tiada tolak kepala, tarik leher, lompatan masuk ke guling atau guling berulang laju. Jangan bina cerun daripada meja, kerusi atau tilam bertindan.", "Jika sakit leher, sakit belakang atau pening, hentikan semua percubaan termasuk ansur maju dan beri perhatian mengikut tatacara sekolah. Murid yang sihat tetapi takut atau belum bersedia boleh memilih posisi tuck duduk sahaja jika selesa; catat guling penuh belum dibuat.", "Murid menunggu di luar lorong dan keluar di sisi selepas stabil. Hentikan aktiviti lain jika guru perlu memberi tumpuan penuh."], "weather_plan": "Jika hujan, kilat, panas melampau atau lantai licin, guru menggunakan ruang berbumbung yang selamat. Jika ruang tidak sesuai, aktiviti berisiko ditangguhkan dan perkara yang belum dilaksanakan dicatat.", "reflection": "Murid yang telah diperhatikan: ____ daripada ____. Kemahiran yang dikuasai: __________. Murid yang masih memerlukan bimbingan atau belum mendapat giliran: __________.", "activity_name": "Guling depan, berhenti dan keluar dengan selamat", "objective": "Murid dapat melakukan guling depan posisi tuck dengan permulaan dan penamat yang terkawal.", "success_criteria": ["Melakukan satu percubaan guling depan yang selamat apabila bersedia, kemudian berhenti stabil; bantuan direkod.", "Menyatakan perubahan bentuk atau arah bagi guling balak, sisi dan depan."], "prior_knowledge": "Murid pernah mencuba tuck atau guling dengan guru. Kesediaan disemak semula bagi setiap murid.", "equipment": [{"item": "Tilam gimnastik rata dan stabil", "quantity": "Satu lorong tilam bersambung tanpa ruang terbuka; satu tilam latihan bentuk di sisi.", "use": "Seorang murid berguling di hadapan guru. Tilam sisi hanya untuk posisi tuck duduk, bukan guling tanpa pengawasan."}, {"item": "Kon", "quantity": "Empat kon di luar tepi tilam.", "use": "Menandakan tempat menunggu dan laluan keluar, bukan halangan di atas tilam."}, {"item": "Air minuman sendiri dan jam guru", "quantity": "Mengikut murid; satu jam guru.", "use": "Rehat, minum dan pengurusan giliran."}], "preparation": ["Periksa lorong tilam rata, rapat dan tidak bergerak. Jangan sediakan cerun atau rintangan tambahan.", "Letak empat kon di luar lorong bagi tempat menunggu dan keluar. Seorang sahaja melakukan guling di hadapan guru mahir.", "Semak rekod sesi lalu untuk memilih satu petunjuk bantuan setiap murid. Giliran belum diperoleh diberi keutamaan."], "organisation": ["Guru memanggil seorang murid ke pangkal tilam. Pasangan menunggu di tepi untuk melihat, bukan menyokong badan.", "Murid tamat dengan duduk atau mencangkung stabil sebelum berdiri dan berjalan keluar di sisi. Murid berikutnya menunggu arahan guru.", "Murid yang belum bersedia kekal pada tuck duduk. Tiada latihan guling bebas ketika guru membantu orang lain."], "movement_cues": ["Mula mencangkung stabil. Tangan terbuka di tilam selebar bahu dan jari menghala ke hadapan.", "Bulatkan badan dan rapatkan dagu ke dada dengan selesa. Guru mahir membimbing pemindahan berat melalui tangan ke bahu dan belakang atas, bukan ke ubun-ubun atau leher.", "Guling perlahan dalam bentuk tuck. Tamat mencangkung atau duduk stabil mengikut kesediaan; jangan paksa berdiri tanpa bantuan.", "Guling balak menggunakan bentuk lurus mendatar, guling sisi membulat ke sisi, manakala guling depan membulat ke hadapan. Guru menunjukkan ketiga-tiganya untuk perbandingan pengetahuan."], "timing_note": "Latihan menekankan mula dan tamat yang selamat, bukan jumlah guling. Semua giliran, rehat/minum dan penyejukan termasuk dalam 30 minit.", "values": "Kerjasama, disiplin dan menjaga keselamatan rakan.", "classroom_example": {"teacher_says": "Selepas guling, berhenti dahulu. Bila sudah stabil, keluar di tepi tilam.", "pupils_do": "Murid tamat stabil sebelum berjalan ke tempat menunggu.", "teacher_checks": "Guru semak murid tidak terus berdiri tergesa-gesa atau melintasi lorong."}, "bbm": ["Tilam gimnastik rata dan stabil — Satu lorong tilam bersambung tanpa ruang terbuka; satu tilam latihan bentuk di sisi.", "Kon — Empat kon di luar tepi tilam.", "Air minuman sendiri dan jam guru — Mengikut murid; satu jam guru.", "Buku teks dan senarai semak pemerhatian guru."], "pak21": "Murid memerhati pasangan dan memberi satu pesanan lisan seperti tunggu arahan. Hanya guru mahir memberi bantuan tubuh; murid tidak menarik, menolak atau menyokong rakan.", "phases": [{"name": "Persediaan murid dan alatan", "minutes": 2, "teacher": ["Guru memeriksa pakaian, tali kasut, keadaan murid dan alatan.", "Guru menerangkan tempat mula, laluan aktiviti dan arahan berhenti."], "pupils": ["Murid memberitahu guru jika tidak sihat.", "Murid mengambil tempat yang ditetapkan dan mendengar arahan."], "check": "Semua murid tahu tempat menunggu dan boleh berhenti apabila diarahkan.", "resources": ["Tilam gimnastik rata dan stabil", "Kon", "Air minuman sendiri dan jam guru"]}, {"name": "Pemanasan badan", "minutes": 4, "teacher": ["Guru memimpin berjalan setempat dan langkah ke sisi selama dua minit.", "Guru membimbing gerakan ringan bahu, tangan, buku lali dan lutut selama dua minit."], "pupils": ["Murid bergerak dalam ruang sendiri tanpa bersentuh.", "Murid bernafas seperti biasa dan berehat jika perlu."], "check": "Murid bersedia untuk aktiviti tanpa terlalu penat.", "resources": ["Ruang lapang", "Kon penanda"]}, {"name": "Perhatikan mula dan tamat", "minutes": 4, "teacher": ["Guru menunjukkan guling balak, sisi dan depan secara ringkas serta meminta murid menyebut perbezaannya.", "Guru menunjukkan satu guling depan dengan mula mencangkung, tangan stabil dan tamat duduk atau mencangkung."], "pupils": ["Murid membandingkan bentuk serta arah ketiga-tiga guling.", "Murid melihat cara berhenti dan keluar tanpa menghalang lorong."], "check": "Murid mengenal bentuk, arah dan giliran selamat.", "resources": ["Tilam"]}, {"name": "Giliran guling terkawal", "minutes": 9, "teacher": ["Guru memanggil murid yang belum mendapat giliran atau memerlukan bimbingan.", "Guru menilai tuck dan tapak tangan sebelum membenarkan satu guling. Jika belum selamat, kembali kepada posisi awal.", "Guru memastikan murid tamat stabil sebelum memberi arahan keluar."], "pupils": ["Murid menunggu dipanggil dan membuat posisi awal.", "Murid mencuba satu guling dengan bantuan guru jika perlu.", "Murid berhenti, berdiri apabila stabil dan keluar melalui sisi."], "check": "Rekod satu percubaan yang benar-benar dilihat; jangan tandakan semua murid daripada contoh seorang.", "resources": ["Lorong tilam", "Kon"]}, {"name": "Baiki satu perkara", "minutes": 7, "teacher": ["Guru menyebut satu pembetulan khusus, seperti tangan lebih stabil atau tunggu sebelum berdiri.", "Guru memberi masa rehat/minum dan giliran pendek mengikut kesediaan; hentikan jika pening atau sakit."], "pupils": ["Murid mencuba semula satu bahagian yang dibenarkan, bukan guling berantai.", "Murid yang menunggu menyebut perbezaan balak, sisi dan depan kepada guru apabila ditanya.", "Murid meninggalkan lorong dengan tenang selepas tamat."], "check": "Pembetulan mesti selamat; kurang bantuan bukan syarat wajib kejayaan.", "resources": ["Tilam", "Air sendiri"]}, {"name": "Penyejukan badan dan penutup", "minutes": 4, "teacher": ["Guru memimpin berjalan perlahan selama satu minit dan regangan lembut tangan serta kaki selama dua minit.", "Guru memberi masa minum dan menanyakan satu perkara yang dipelajari."], "pupils": ["Murid meregang mengikut keselesaan tanpa sentapan.", "Murid memberitahu guru jika masih tidak selesa dan membantu mengemas alatan ringan selepas arahan."], "check": "Tiada latihan kuat selepas penyejukan. Guru mencatat perkara yang perlu disusuli.", "resources": ["Air minuman", "Ruang rehat"]}], "differentiation": {"support": {"label": "Peneroka", "support_description": "Guru membimbing satu langkah pada satu masa.", "task": "Mengulang posisi awal dan tamat; guling hanya dengan bimbingan dekat apabila bersedia.", "materials": ["Tilam rata"], "teacher": ["Guru menunjukkan tangan dan tuck secara berasingan.", "Guru membantu sendiri dan mencatat ansur maju jika guling belum dibuat."], "pupil_steps": ["Tunjukkan tuck duduk dan tangan di tilam.", "Cuba guling depan jika guru menilai selamat.", "Tamat duduk stabil sebelum keluar di sisi.", "Sebut perbezaan balak, sisi dan depan menggunakan kata bantu."], "product": "Tahap percubaan sebenar, bantuan dan penerangan tiga jenis.", "criterion": "Posisi tuck sahaja bukan bukti guling penuh; penamat dibuat selamat.", "next_step": "Ulang langkah yang belum bersedia pada giliran susulan.", "example": {"teacher": "Apa dibuat sebelum berdiri?", "pupil": "Berhenti dan pastikan badan stabil."}}, "core": {"label": "Pembina", "support_description": "Murid berlatih berpasangan dan melakukan sendiri.", "task": "Melakukan satu guling dengan mula dan tamat yang terkawal.", "materials": ["Tilam", "Kon di luar laluan"], "teacher": ["Semak posisi awal sebelum arahan mula.", "Beri satu teguran ringkas selepas tamat."], "pupil_steps": ["Mencangkung dan letakkan tangan dengan stabil.", "Guling depan dalam bentuk tuck dengan pengawasan guru.", "Berhenti stabil dan keluar di sisi.", "Nyatakan bentuk atau arah balak, sisi dan depan."], "product": "Satu guling individu dan respons perbandingan.", "criterion": "Mula dan tamat selamat, bantuan dicatat.", "next_step": "Perkemas satu petunjuk tanpa menambah laju.", "example": {"teacher": "Bilakah pasangan boleh masuk?", "pupil": "Selepas saya keluar dan guru memanggilnya."}}, "challenge": {"label": "Pencabar", "support_description": "Murid memperkemas satu perkara dalam kemahiran yang sama.", "task": "Memilih satu pembetulan kecil pada mula atau tamat guling.", "materials": ["Tilam rata"], "teacher": ["Tanya perkara yang hendak diperbaiki, seperti berhenti stabil.", "Jangan beri lompatan, putaran tambahan atau guling bersambung."], "pupil_steps": ["Sebut satu petunjuk pilihan sebelum mula.", "Lakukan satu guling depan yang dibenarkan guru.", "Berhenti dan semak petunjuk itu bersama guru.", "Bezakan balak, sisi dan depan sebelum kembali ke tempat menunggu."], "product": "Percubaan sendiri dengan satu pembetulan yang jelas.", "criterion": "Kawalan bertambah tanpa risiko atau ulangan maksimum.", "next_step": "Kekalkan petunjuk yang sama dalam latihan seterusnya.", "example": {"teacher": "Apakah yang kamu mahu perkemas?", "pupil": "Saya mahu berhenti stabil sebelum berdiri."}}}, "differentiation_delivery": {"common_task": "Murid dapat melakukan guling depan posisi tuck dengan permulaan dan penamat yang terkawal.", "placement": "Bimbingan ini diberikan dalam waktu latihan dan aplikasi. Murid tidak perlu menjalani tiga kumpulan bantuan sebagai aktiviti tambahan.", "teacher_rounds": ["Utamakan Peneroka yang belum mendapat percubaan.", "Semak mula dan tamat Pembina.", "Dengar pembetulan Pencabar selepas guling, bukan ketika hilang kawalan."], "individual_check": "Melakukan satu percubaan guling depan yang selamat apabila bersedia, kemudian berhenti stabil; bantuan direkod.", "flexible_help": "Bantuan diteruskan selagi diperlukan. Murid tidak dipaksa menambah kelajuan, jarak, beban atau ulangan untuk menunjukkan kemajuan."}, "pbd": {"method": "Pemerhatian dekat semasa satu percubaan individu.", "evidence": "Permulaan tuck, guling depan dan penamat stabil setiap murid.", "criterion": "Guling sebenar dilakukan hanya jika bersedia; bantuan dan ansur maju sahaja direkod berasingan.", "recording": "Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP.", "sample_checklist": ["Mula tuck dan tangan: ____", "Guling depan sebenar: ____", "Tamat stabil / bantuan / belum giliran: ____"]}, "pbd_complementary": {"2.7.2": {"method": "Soal jawab individu selepas demonstrasi guru.", "evidence": "Respons perubahan kedudukan badan dalam balak, sisi dan depan.", "criterion": "Ketiga-tiga jenis dikenal melalui bentuk atau arah, dengan kata bantu jika perlu.", "recording": "Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP.", "sample_checklist": ["Balak lurus: ____", "Sisi membulat ke sisi: ____", "Depan membulat ke hadapan: ____"]}, "5.1.3": {"method": "Pemerhatian laluan dan giliran.", "evidence": "Menunggu arahan, berhenti stabil dan keluar di sisi.", "criterion": "Arahan dipatuhi tanpa murid membantu tubuh rakan.", "recording": "Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP.", "sample_checklist": ["Mula selepas arahan: ____", "Keluar selepas stabil: ____", "Bimbingan atau belum diperhatikan: ____"]}}, "intervention": ["Kekalkan tuck duduk dan ayunan kecil bagi murid belum bersedia.", "Rekod giliran tertangguh dan susun latihan dengan guru mahir; tiada latihan guling sendiri di rumah diwajibkan."], "book_pages_text": "34, 35", "sp_focus": "", "sp_display": "1.8.4", "complementary": [{"standard_key": "2.7.2", "sp_code": "2.7.2", "sp_text": "Mengenal pasti perubahan kedudukan badan semasa melakukan guling balak, guling sisi dan guling depan.", "sk_code": "2.7", "sk_text": "Mengaplikasi konsep pergerakan dan prinsip mekanik bagi kemahiran putaran.", "domain": "kognitif", "source_label": ""}, {"standard_key": "5.1.3", "sp_code": "5.1.3", "sp_text": "Mematuhi arahan guru semasa melakukan aktiviti Pendidikan Jasmani.", "sk_code": "5.1", "sk_text": "Mematuhi dan mengamalkan elemen pengurusan dan keselamatan.", "domain": "afektif", "source_label": ""}], "draft_sha256": "a1062c283bddb6938005ed11a7a2fd27952c48a69446d41c16af6465ca87d050"}'::jsonb,'[{"kind": "title", "text": "Minggu 29 Sesi 2 — Guling depan, berhenti dan keluar dengan selamat"}, {"kind": "subtitle", "text": "Pendidikan Jasmani Tahun 1 | Dua sesi seminggu | 30 minit setiap sesi | R1"}, {"kind": "p", "text": "ID: PJ1-2026B-2S-W29-S2"}, {"kind": "h2", "text": "A. Maklumat pengajaran"}, {"kind": "p", "text": "Guru: ____________________ | Kelas: __________ | Tarikh: __________ | Waktu: __________"}, {"kind": "p", "text": "Unit 4: Tunas Gimnas"}, {"kind": "p", "text": "Tajuk buku teks: Guling Tenggiling"}, {"kind": "p", "text": "Aktiviti guru: Guling depan, berhenti dan keluar dengan selamat"}, {"kind": "p", "text": "Rujukan buku teks PJPK Tahun 1, bahagian PJ: muka surat 34, 35."}, {"kind": "p", "text": "Latihan menekankan mula dan tamat yang selamat, bukan jumlah guling. Semua giliran, rehat/minum dan penyejukan termasuk dalam 30 minit."}, {"kind": "h2", "text": "B. Standard dan hasil pembelajaran"}, {"kind": "p", "text": "SK utama 1.8: Melakukan kemahiran putaran."}, {"kind": "p", "text": "SP utama 1.8.4: Melakukan guling depan posisi tuck."}, {"kind": "p", "text": "SK sokongan 2.7: Mengaplikasi konsep pergerakan dan prinsip mekanik bagi kemahiran putaran."}, {"kind": "p", "text": "SP sokongan 2.7.2: Mengenal pasti perubahan kedudukan badan semasa melakukan guling balak, guling sisi dan guling depan."}, {"kind": "p", "text": "SK sokongan 5.1: Mematuhi dan mengamalkan elemen pengurusan dan keselamatan."}, {"kind": "p", "text": "SP sokongan 5.1.3: Mematuhi arahan guru semasa melakukan aktiviti Pendidikan Jasmani."}, {"kind": "p", "text": "Fokus dan bantuan mengikut sesi; jangan menyamakan ansur maju, pemerhatian atau bantuan dengan semua lakuan sumber yang lengkap."}, {"kind": "label", "text": "Objektif"}, {"kind": "p", "text": "Murid dapat melakukan guling depan posisi tuck dengan permulaan dan penamat yang terkawal."}, {"kind": "label", "text": "Kriteria kejayaan"}, {"kind": "p", "text": "1. Melakukan satu percubaan guling depan yang selamat apabila bersedia, kemudian berhenti stabil; bantuan direkod."}, {"kind": "p", "text": "2. Menyatakan perubahan bentuk atau arah bagi guling balak, sisi dan depan."}, {"kind": "p", "text": "Pengetahuan sedia ada: Murid pernah mencuba tuck atau guling dengan guru. Kesediaan disemak semula bagi setiap murid."}, {"kind": "h2", "text": "C. Alatan, persediaan dan keselamatan"}, {"kind": "label", "text": "Tilam gimnastik rata dan stabil"}, {"kind": "p", "text": "Keperluan: Satu lorong tilam bersambung tanpa ruang terbuka; satu tilam latihan bentuk di sisi."}, {"kind": "p", "text": "Kegunaan: Seorang murid berguling di hadapan guru. Tilam sisi hanya untuk posisi tuck duduk, bukan guling tanpa pengawasan."}, {"kind": "label", "text": "Kon"}, {"kind": "p", "text": "Keperluan: Empat kon di luar tepi tilam."}, {"kind": "p", "text": "Kegunaan: Menandakan tempat menunggu dan laluan keluar, bukan halangan di atas tilam."}, {"kind": "label", "text": "Air minuman sendiri dan jam guru"}, {"kind": "p", "text": "Keperluan: Mengikut murid; satu jam guru."}, {"kind": "p", "text": "Kegunaan: Rehat, minum dan pengurusan giliran."}, {"kind": "label", "text": "Persediaan guru"}, {"kind": "p", "text": "1. Periksa lorong tilam rata, rapat dan tidak bergerak. Jangan sediakan cerun atau rintangan tambahan."}, {"kind": "p", "text": "2. Letak empat kon di luar lorong bagi tempat menunggu dan keluar. Seorang sahaja melakukan guling di hadapan guru mahir."}, {"kind": "p", "text": "3. Semak rekod sesi lalu untuk memilih satu petunjuk bantuan setiap murid. Giliran belum diperoleh diberi keutamaan."}, {"kind": "label", "text": "Susunan dan giliran murid"}, {"kind": "p", "text": "1. Guru memanggil seorang murid ke pangkal tilam. Pasangan menunggu di tepi untuk melihat, bukan menyokong badan."}, {"kind": "p", "text": "2. Murid tamat dengan duduk atau mencangkung stabil sebelum berdiri dan berjalan keluar di sisi. Murid berikutnya menunggu arahan guru."}, {"kind": "p", "text": "3. Murid yang belum bersedia kekal pada tuck duduk. Tiada latihan guling bebas ketika guru membantu orang lain."}, {"kind": "label", "text": "Petunjuk pergerakan"}, {"kind": "p", "text": "1. Mula mencangkung stabil. Tangan terbuka di tilam selebar bahu dan jari menghala ke hadapan."}, {"kind": "p", "text": "2. Bulatkan badan dan rapatkan dagu ke dada dengan selesa. Guru mahir membimbing pemindahan berat melalui tangan ke bahu dan belakang atas, bukan ke ubun-ubun atau leher."}, {"kind": "p", "text": "3. Guling perlahan dalam bentuk tuck. Tamat mencangkung atau duduk stabil mengikut kesediaan; jangan paksa berdiri tanpa bantuan."}, {"kind": "p", "text": "4. Guling balak menggunakan bentuk lurus mendatar, guling sisi membulat ke sisi, manakala guling depan membulat ke hadapan. Guru menunjukkan ketiga-tiganya untuk perbandingan pengetahuan."}, {"kind": "label", "text": "BBM"}, {"kind": "p", "text": "1. Tilam gimnastik rata dan stabil — Satu lorong tilam bersambung tanpa ruang terbuka; satu tilam latihan bentuk di sisi."}, {"kind": "p", "text": "2. Kon — Empat kon di luar tepi tilam."}, {"kind": "p", "text": "3. Air minuman sendiri dan jam guru — Mengikut murid; satu jam guru."}, {"kind": "p", "text": "4. Buku teks dan senarai semak pemerhatian guru."}, {"kind": "p", "text": "PAK-21: Murid memerhati pasangan dan memberi satu pesanan lisan seperti tunggu arahan. Hanya guru mahir memberi bantuan tubuh; murid tidak menarik, menolak atau menyokong rakan."}, {"kind": "p", "text": "Nilai: Kerjasama, disiplin dan menjaga keselamatan rakan."}, {"kind": "label", "text": "Keselamatan"}, {"kind": "p", "text": "1. Guru memeriksa pakaian, tali kasut, keadaan murid, permukaan tempat aktiviti dan alatan sebelum bermula."}, {"kind": "p", "text": "2. Murid berhenti dan memberitahu guru jika sakit, pening atau sukar bernafas. Rehat dan minum dibenarkan mengikut keperluan."}, {"kind": "p", "text": "3. Guru memastikan semua murid berada dalam pandangannya. Murid tidak menolak, menarik atau menghalang laluan rakan."}, {"kind": "p", "text": "4. Guling hanya dengan guru mahir di sisi dan tilam sesuai. Murid lain tidak menjadi penyokong tubuh."}, {"kind": "p", "text": "5. Tiada tolak kepala, tarik leher, lompatan masuk ke guling atau guling berulang laju. Jangan bina cerun daripada meja, kerusi atau tilam bertindan."}, {"kind": "p", "text": "6. Jika sakit leher, sakit belakang atau pening, hentikan semua percubaan termasuk ansur maju dan beri perhatian mengikut tatacara sekolah. Murid yang sihat tetapi takut atau belum bersedia boleh memilih posisi tuck duduk sahaja jika selesa; catat guling penuh belum dibuat."}, {"kind": "p", "text": "7. Murid menunggu di luar lorong dan keluar di sisi selepas stabil. Hentikan aktiviti lain jika guru perlu memberi tumpuan penuh."}, {"kind": "p", "text": "Jika cuaca atau ruang tidak sesuai: Jika hujan, kilat, panas melampau atau lantai licin, guru menggunakan ruang berbumbung yang selamat. Jika ruang tidak sesuai, aktiviti berisiko ditangguhkan dan perkara yang belum dilaksanakan dicatat."}, {"kind": "h2", "text": "D. Langkah PdP"}, {"kind": "h3", "text": "Langkah 1: Persediaan murid dan alatan — 2 minit"}, {"kind": "p", "text": "Minit 0 hingga 2."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru memeriksa pakaian, tali kasut, keadaan murid dan alatan."}, {"kind": "p", "text": "2. Guru menerangkan tempat mula, laluan aktiviti dan arahan berhenti."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid memberitahu guru jika tidak sihat."}, {"kind": "p", "text": "2. Murid mengambil tempat yang ditetapkan dan mendengar arahan."}, {"kind": "p", "text": "Semakan: Semua murid tahu tempat menunggu dan boleh berhenti apabila diarahkan."}, {"kind": "p", "text": "Alatan: Tilam gimnastik rata dan stabil Kon Air minuman sendiri dan jam guru"}, {"kind": "h3", "text": "Langkah 2: Pemanasan badan — 4 minit"}, {"kind": "p", "text": "Minit 2 hingga 6."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru memimpin berjalan setempat dan langkah ke sisi selama dua minit."}, {"kind": "p", "text": "2. Guru membimbing gerakan ringan bahu, tangan, buku lali dan lutut selama dua minit."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid bergerak dalam ruang sendiri tanpa bersentuh."}, {"kind": "p", "text": "2. Murid bernafas seperti biasa dan berehat jika perlu."}, {"kind": "p", "text": "Semakan: Murid bersedia untuk aktiviti tanpa terlalu penat."}, {"kind": "p", "text": "Alatan: Ruang lapang Kon penanda"}, {"kind": "h3", "text": "Langkah 3: Perhatikan mula dan tamat — 4 minit"}, {"kind": "p", "text": "Minit 6 hingga 10."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru menunjukkan guling balak, sisi dan depan secara ringkas serta meminta murid menyebut perbezaannya."}, {"kind": "p", "text": "2. Guru menunjukkan satu guling depan dengan mula mencangkung, tangan stabil dan tamat duduk atau mencangkung."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid membandingkan bentuk serta arah ketiga-tiga guling."}, {"kind": "p", "text": "2. Murid melihat cara berhenti dan keluar tanpa menghalang lorong."}, {"kind": "p", "text": "Semakan: Murid mengenal bentuk, arah dan giliran selamat."}, {"kind": "p", "text": "Alatan: Tilam"}, {"kind": "h3", "text": "Langkah 4: Giliran guling terkawal — 9 minit"}, {"kind": "p", "text": "Minit 10 hingga 19."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru memanggil murid yang belum mendapat giliran atau memerlukan bimbingan."}, {"kind": "p", "text": "2. Guru menilai tuck dan tapak tangan sebelum membenarkan satu guling. Jika belum selamat, kembali kepada posisi awal."}, {"kind": "p", "text": "3. Guru memastikan murid tamat stabil sebelum memberi arahan keluar."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid menunggu dipanggil dan membuat posisi awal."}, {"kind": "p", "text": "2. Murid mencuba satu guling dengan bantuan guru jika perlu."}, {"kind": "p", "text": "3. Murid berhenti, berdiri apabila stabil dan keluar melalui sisi."}, {"kind": "p", "text": "Semakan: Rekod satu percubaan yang benar-benar dilihat; jangan tandakan semua murid daripada contoh seorang."}, {"kind": "p", "text": "Alatan: Lorong tilam Kon"}, {"kind": "h3", "text": "Langkah 5: Baiki satu perkara — 7 minit"}, {"kind": "p", "text": "Minit 19 hingga 26."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru menyebut satu pembetulan khusus, seperti tangan lebih stabil atau tunggu sebelum berdiri."}, {"kind": "p", "text": "2. Guru memberi masa rehat/minum dan giliran pendek mengikut kesediaan; hentikan jika pening atau sakit."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid mencuba semula satu bahagian yang dibenarkan, bukan guling berantai."}, {"kind": "p", "text": "2. Murid yang menunggu menyebut perbezaan balak, sisi dan depan kepada guru apabila ditanya."}, {"kind": "p", "text": "3. Murid meninggalkan lorong dengan tenang selepas tamat."}, {"kind": "p", "text": "Semakan: Pembetulan mesti selamat; kurang bantuan bukan syarat wajib kejayaan."}, {"kind": "p", "text": "Alatan: Tilam Air sendiri"}, {"kind": "h3", "text": "Langkah 6: Penyejukan badan dan penutup — 4 minit"}, {"kind": "p", "text": "Minit 26 hingga 30."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru memimpin berjalan perlahan selama satu minit dan regangan lembut tangan serta kaki selama dua minit."}, {"kind": "p", "text": "2. Guru memberi masa minum dan menanyakan satu perkara yang dipelajari."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid meregang mengikut keselesaan tanpa sentapan."}, {"kind": "p", "text": "2. Murid memberitahu guru jika masih tidak selesa dan membantu mengemas alatan ringan selepas arahan."}, {"kind": "p", "text": "Semakan: Tiada latihan kuat selepas penyejukan. Guru mencatat perkara yang perlu disusuli."}, {"kind": "p", "text": "Alatan: Air minuman Ruang rehat"}, {"kind": "p", "text": "Jumlah masa: 30 minit."}, {"kind": "label", "text": "Contoh arahan kelas"}, {"kind": "p", "text": "Guru: Selepas guling, berhenti dahulu. Bila sudah stabil, keluar di tepi tilam."}, {"kind": "p", "text": "Murid: Murid tamat stabil sebelum berjalan ke tempat menunggu."}, {"kind": "p", "text": "Semakan guru: Guru semak murid tidak terus berdiri tergesa-gesa atau melintasi lorong."}, {"kind": "h2", "text": "E. PdP terbeza", "anchor": "pdp-PJ1-2026B-2S-W29-S2"}, {"kind": "p", "text": "Tugasan bersama: Murid dapat melakukan guling depan posisi tuck dengan permulaan dan penamat yang terkawal."}, {"kind": "p", "text": "Bimbingan ini diberikan dalam waktu latihan dan aplikasi. Murid tidak perlu menjalani tiga kumpulan bantuan sebagai aktiviti tambahan."}, {"kind": "label", "text": "Bimbingan guru"}, {"kind": "p", "text": "1. Utamakan Peneroka yang belum mendapat percubaan."}, {"kind": "p", "text": "2. Semak mula dan tamat Pembina."}, {"kind": "p", "text": "3. Dengar pembetulan Pencabar selepas guling, bukan ketika hilang kawalan."}, {"kind": "p", "text": "Semakan individu: Melakukan satu percubaan guling depan yang selamat apabila bersedia, kemudian berhenti stabil; bantuan direkod."}, {"kind": "p", "text": "Bantuan diteruskan selagi diperlukan. Murid tidak dipaksa menambah kelajuan, jarak, beban atau ulangan untuk menunjukkan kemajuan."}, {"kind": "h3", "text": "Peneroka"}, {"kind": "p", "text": "Guru membimbing satu langkah pada satu masa."}, {"kind": "p", "text": "Tugasan: Mengulang posisi awal dan tamat; guling hanya dengan bimbingan dekat apabila bersedia."}, {"kind": "label", "text": "Alatan"}, {"kind": "p", "text": "1. Tilam rata"}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru menunjukkan tangan dan tuck secara berasingan."}, {"kind": "p", "text": "2. Guru membantu sendiri dan mencatat ansur maju jika guling belum dibuat."}, {"kind": "label", "text": "Langkah murid"}, {"kind": "p", "text": "1. Tunjukkan tuck duduk dan tangan di tilam."}, {"kind": "p", "text": "2. Cuba guling depan jika guru menilai selamat."}, {"kind": "p", "text": "3. Tamat duduk stabil sebelum keluar di sisi."}, {"kind": "p", "text": "4. Sebut perbezaan balak, sisi dan depan menggunakan kata bantu."}, {"kind": "p", "text": "Contoh guru: Apa dibuat sebelum berdiri?"}, {"kind": "p", "text": "Contoh respons murid: Berhenti dan pastikan badan stabil."}, {"kind": "p", "text": "Hasil individu: Tahap percubaan sebenar, bantuan dan penerangan tiga jenis."}, {"kind": "p", "text": "Kriteria: Posisi tuck sahaja bukan bukti guling penuh; penamat dibuat selamat."}, {"kind": "p", "text": "Susulan: Ulang langkah yang belum bersedia pada giliran susulan."}, {"kind": "h3", "text": "Pembina"}, {"kind": "p", "text": "Murid berlatih berpasangan dan melakukan sendiri."}, {"kind": "p", "text": "Tugasan: Melakukan satu guling dengan mula dan tamat yang terkawal."}, {"kind": "label", "text": "Alatan"}, {"kind": "p", "text": "1. Tilam"}, {"kind": "p", "text": "2. Kon di luar laluan"}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Semak posisi awal sebelum arahan mula."}, {"kind": "p", "text": "2. Beri satu teguran ringkas selepas tamat."}, {"kind": "label", "text": "Langkah murid"}, {"kind": "p", "text": "1. Mencangkung dan letakkan tangan dengan stabil."}, {"kind": "p", "text": "2. Guling depan dalam bentuk tuck dengan pengawasan guru."}, {"kind": "p", "text": "3. Berhenti stabil dan keluar di sisi."}, {"kind": "p", "text": "4. Nyatakan bentuk atau arah balak, sisi dan depan."}, {"kind": "p", "text": "Contoh guru: Bilakah pasangan boleh masuk?"}, {"kind": "p", "text": "Contoh respons murid: Selepas saya keluar dan guru memanggilnya."}, {"kind": "p", "text": "Hasil individu: Satu guling individu dan respons perbandingan."}, {"kind": "p", "text": "Kriteria: Mula dan tamat selamat, bantuan dicatat."}, {"kind": "p", "text": "Susulan: Perkemas satu petunjuk tanpa menambah laju."}, {"kind": "h3", "text": "Pencabar"}, {"kind": "p", "text": "Murid memperkemas satu perkara dalam kemahiran yang sama."}, {"kind": "p", "text": "Tugasan: Memilih satu pembetulan kecil pada mula atau tamat guling."}, {"kind": "label", "text": "Alatan"}, {"kind": "p", "text": "1. Tilam rata"}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Tanya perkara yang hendak diperbaiki, seperti berhenti stabil."}, {"kind": "p", "text": "2. Jangan beri lompatan, putaran tambahan atau guling bersambung."}, {"kind": "label", "text": "Langkah murid"}, {"kind": "p", "text": "1. Sebut satu petunjuk pilihan sebelum mula."}, {"kind": "p", "text": "2. Lakukan satu guling depan yang dibenarkan guru."}, {"kind": "p", "text": "3. Berhenti dan semak petunjuk itu bersama guru."}, {"kind": "p", "text": "4. Bezakan balak, sisi dan depan sebelum kembali ke tempat menunggu."}, {"kind": "p", "text": "Contoh guru: Apakah yang kamu mahu perkemas?"}, {"kind": "p", "text": "Contoh respons murid: Saya mahu berhenti stabil sebelum berdiri."}, {"kind": "p", "text": "Hasil individu: Percubaan sendiri dengan satu pembetulan yang jelas."}, {"kind": "p", "text": "Kriteria: Kawalan bertambah tanpa risiko atau ulangan maksimum."}, {"kind": "p", "text": "Susulan: Kekalkan petunjuk yang sama dalam latihan seterusnya."}, {"kind": "h2", "text": "F. Pentaksiran Bilik Darjah"}, {"kind": "h3", "text": "PBD utama — SP 1.8.4"}, {"kind": "p", "text": "Kaedah: Pemerhatian dekat semasa satu percubaan individu."}, {"kind": "p", "text": "Bukti: Permulaan tuck, guling depan dan penamat stabil setiap murid."}, {"kind": "p", "text": "Kriteria: Guling sebenar dilakukan hanya jika bersedia; bantuan dan ansur maju sahaja direkod berasingan."}, {"kind": "p", "text": "Rekod: Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP."}, {"kind": "label", "text": "Senarai semak"}, {"kind": "p", "text": "1. Mula tuck dan tangan: ____"}, {"kind": "p", "text": "2. Guling depan sebenar: ____"}, {"kind": "p", "text": "3. Tamat stabil / bantuan / belum giliran: ____"}, {"kind": "h3", "text": "PBD sokongan — SP 2.7.2"}, {"kind": "p", "text": "Kaedah: Soal jawab individu selepas demonstrasi guru."}, {"kind": "p", "text": "Bukti: Respons perubahan kedudukan badan dalam balak, sisi dan depan."}, {"kind": "p", "text": "Kriteria: Ketiga-tiga jenis dikenal melalui bentuk atau arah, dengan kata bantu jika perlu."}, {"kind": "p", "text": "Rekod: Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP."}, {"kind": "label", "text": "Senarai semak"}, {"kind": "p", "text": "1. Balak lurus: ____"}, {"kind": "p", "text": "2. Sisi membulat ke sisi: ____"}, {"kind": "p", "text": "3. Depan membulat ke hadapan: ____"}, {"kind": "h3", "text": "PBD sokongan — SP 5.1.3"}, {"kind": "p", "text": "Kaedah: Pemerhatian laluan dan giliran."}, {"kind": "p", "text": "Bukti: Menunggu arahan, berhenti stabil dan keluar di sisi."}, {"kind": "p", "text": "Kriteria: Arahan dipatuhi tanpa murid membantu tubuh rakan."}, {"kind": "p", "text": "Rekod: Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP."}, {"kind": "label", "text": "Senarai semak"}, {"kind": "p", "text": "1. Mula selepas arahan: ____"}, {"kind": "p", "text": "2. Keluar selepas stabil: ____"}, {"kind": "p", "text": "3. Bimbingan atau belum diperhatikan: ____"}, {"kind": "h2", "text": "G. Refleksi dan intervensi"}, {"kind": "p", "text": "Murid yang telah diperhatikan: ____ daripada ____. Kemahiran yang dikuasai: __________. Murid yang masih memerlukan bimbingan atau belum mendapat giliran: __________."}, {"kind": "label", "text": "Intervensi"}, {"kind": "p", "text": "1. Kekalkan tuck duduk dan ayunan kecil bagi murid belum bersedia."}, {"kind": "p", "text": "2. Rekod giliran tertangguh dan susun latihan dengan guru mahir; tiada latihan guling sendiri di rumah diwajibkan."}]'::jsonb,'{"source_hold": "", "adaptation_note": "Tilam sesuai dan guru mahir disahkan guru. Satu lorong guling diawasi terus; murid bukan penyokong tubuh rakan. Posisi tuck dan ayunan ialah ansur maju, bukan bukti guling penuh. Permukaan rata dipilih; tiada cerun buatan daripada meja. Pengetahuan 2.7.2 merangkumi guling balak, sisi dan depan melalui tunjuk cara guru; amali fokus guling depan.", "source_images_verified": true, "audio_verified": false, "ba_verified": false, "classroom_trial_performed": false}'::jsonb),
  ('PJ1-2026B-2S-W30-S1','pj',1,2026,30,1,30,'2.8.1',array[38,39]::int[],'8bfd079888fba0e2a17c0fa21d012163845487e63a5f3441352d60f3d4d51a66','dd78708bf8416c594ef08a8c45086dbc2eee71955db72b7e0ba0f3632bb4b688','715d2dd93e616381f7de4fb5e317e008bae7007088b12831c3d9d17a2be5d6d7','ACCEPTED_FROM_DOWNLOADED_CATATAN',false,'{"id": "PJ1-2026B-2S-W30-S1", "subject": "Pendidikan Jasmani", "year": 1, "week": 30, "session": 1, "revision": "PJ1-30MIN-REVIEW-R1", "date": "", "teaching_time": "", "minutes": 30, "sessions_per_week": 2, "weekly_minutes": 60, "title": "Awas dan Mari Lakukan", "source_title": "Awas dan Mari Lakukan", "unit": "Unit 5: Mari Berenang", "source_row_id": "PJ1-RPT2026-T10-R3", "source_row_literal": ["30\n\nKump A: 23.08.2026-27.08.2026\n\nKump B: 24.08.2026-28.08.2026\n\n25.8.2026 (Selasa)\nCuti Maulud Nabi", "5: MARI BERENANG\nAWAS DAN MARI LAKUKAN", "1.9 Melakukan kemahiran keyakinan dan keselamatan dalam air. \n2.8 Menggunakan pengetahuan konsep keyakinan dan keselamatan air\n\n5.1 Mematuhi dan mengamalkan elemen pengurusan dan keselamatan.", "1.9.1 Mematuhi peraturan di kolam renang. \n1.9.2 Melakukan kemahiran masuk ke dalam air, berdiri, berjalan, bobbing, mengapung tiarap, meluncur (glide), dan berdiri dalam air dari posisi apungan tiarap.\n\n2.8.1 Mengenal pasti peraturan di kolam renang. \n2.8.2 Mengenal pasti kemahiran bobbing yang betul. \n2.8.3 Mengenal pasti kemahiran apungan tiarap yang betul. \n2.8.4 Mengenal pasti kemahiran luncur yang betul.\n\n5.1.3 Mematuhi arahan guru semasa melakukan aktiviti Pendidikan Jasmani. \n5.1.4 Mengenali dan mematuhi peraturan keselamatan di tempat melakukan aktiviti Pendidikan Jasmani.", "Pemerhatian /\nPentaksiran\n\nBBB/BBM\nBT m/s 37-39"], "rpt_original_page_literal": "37-39", "source_pages": [38, 39], "source_pdf_pages": [46, 47], "rpt_book_pages": "38, 39", "main_standard_key": "2.8.1", "sk_code": "2.8", "sk_text": "Menggunakan pengetahuan konsep dan prinsip mekanik dalam keyakinan dan keselamatan di air.", "sp_code": "2.8.1", "sp_text": "Mengenal pasti peraturan di kolam renang.", "complementary_standards": [{"standard_key": "5.1.3", "sp_code": "5.1.3", "sp_text": "Mematuhi arahan guru semasa melakukan aktiviti Pendidikan Jasmani.", "sk_code": "5.1", "sk_text": "Mematuhi dan mengamalkan elemen pengurusan dan keselamatan.", "domain": "afektif", "source_label": ""}, {"standard_key": "5.1.4", "sp_code": "5.1.4", "sp_text": "Mengenali dan mematuhi peraturan keselamatan di tempat melakukan aktiviti Pendidikan Jasmani.", "sk_code": "5.1", "sk_text": "Mematuhi dan mengamalkan elemen pengurusan dan keselamatan.", "domain": "afektif", "source_label": ""}], "source_task": "Mengenal peraturan kolam melalui latihan selamat di darat", "authoring_focus": "Mengenal peraturan kolam melalui latihan selamat di darat", "source_hold": "Teks RPT, DSKP dan buku dibaca. Semakan imej guling BT35 dan kod DSKP hlm70 terhalang ralat402; OCR dan teks salinan menyokong kod berulang, bukan kelulusan visual. Guru perlu menilai postur, alat dan kesediaan setiap murid.", "practical_required": true, "warmup_required": true, "cooldown_required": true, "facility_replacement": true, "facility_replacement_note": "Penyesuaian di darat sahaja; amali air belum dilaksanakan.", "source_subset_focus": false, "source_subset_note": "", "adaptation_note": "Tiada kolam sesuai. Dua sesi di darat dibenarkan guru. Pengetahuan keselamatan dan bobbing daripada teks diajar, tetapi latihan darat tidak memenuhi amali di kolam SP1.9.1/1.9.2. Apungan tiarap dan luncur hanya pengenalan nama/konsep jika gambar belum disahkan; SP2.8.3/2.8.4 belum lengkap. Tiada kolam sementara, rendaman muka, tahan nafas, luncur di lantai atau menyelamat secara fizikal.", "privacy_adaptation": false, "privacy_note": "", "held_standards": [{"standard_key": "1.9.1", "sp_code": "1.9.1", "sp_text": "Mematuhi peraturan di kolam renang.", "sk_code": "1.9", "sk_text": "Melakukan kemahiran keyakinan dan keselamatan dalam air.", "status": "PENDING_REAL_WATER_PRACTICE", "reason": "Tiada kolam; pengenalan di darat bukan amali air."}, {"standard_key": "1.9.2", "sp_code": "1.9.2", "sp_text": "Melakukan kemahiran masuk ke dalam air, berdiri, berjalan, bobbing, mengapung tiarap, meluncur (glide) dan berdiri dalam air dari posisi apungan tiarap.", "sk_code": "1.9", "sk_text": "Melakukan kemahiran keyakinan dan keselamatan dalam air.", "status": "PENDING_REAL_WATER_PRACTICE", "reason": "Tiada kolam; pengenalan di darat bukan amali air."}, {"standard_key": "2.8.3", "sp_code": "2.8.3", "sp_text": "Mengenal pasti kemahiran apungan tiarap yang betul.", "sk_code": "2.8", "sk_text": "Menggunakan pengetahuan konsep dan prinsip mekanik dalam keyakinan dan keselamatan di air.", "status": "PARTIAL_CONCEPT_ONLY", "reason": "Tiada kolam; pengenalan di darat bukan amali air."}, {"standard_key": "2.8.4", "sp_code": "2.8.4", "sp_text": "Mengenal pasti kemahiran luncur yang betul.", "sk_code": "2.8", "sk_text": "Menggunakan pengetahuan konsep dan prinsip mekanik dalam keyakinan dan keselamatan di air.", "status": "PARTIAL_CONCEPT_ONLY", "reason": "Tiada kolam; pengenalan di darat bukan amali air."}], "source_code_conflict": false, "source_code_note": "", "unperformed_literal_elements": ["1.9.1: Tiada kolam; pengenalan di darat bukan amali air.", "1.9.2: Tiada kolam; pengenalan di darat bukan amali air.", "2.8.3: Tiada kolam; pengenalan di darat bukan amali air.", "2.8.4: Tiada kolam; pengenalan di darat bukan amali air."], "source_mapping_review": "20 RPH, dua sesi30minit seminggu dibenarkan guru. S1/S2 ialah cadangan pecahan RPT mingguan, bukan nombor sesi yang tercetak dalam RPT.", "routine_book_pages": [46, 47], "active": false, "production_write_performed": false, "presentation_review": "PENDING_TEACHER_REVIEW", "safety": ["Guru memeriksa pakaian, tali kasut, keadaan murid, permukaan tempat aktiviti dan alatan sebelum bermula.", "Murid berhenti dan memberitahu guru jika sakit, pening atau sukar bernafas. Rehat dan minum dibenarkan mengikut keperluan.", "Guru memastikan semua murid berada dalam pandangannya. Murid tidak menolak, menarik atau menghalang laluan rakan.", "Latihan di darat sahaja. Tiada rendaman muka, tahan nafas, pertandingan hembusan atau pernafasan laju.", "Jangan membawa murid ke tepi air untuk melengkapkan aktiviti. Tiada kolam sesuai; amali SP1.9.1 dan SP1.9.2 belum dilaksanakan.", "Apungan tiarap dan luncuran disebut sebagai nama kemahiran sahaja apabila gambar tidak disahkan; SP2.8.3 dan SP2.8.4 belum lengkap.", "Jika seseorang berada dalam bahaya di air, panggil orang dewasa atau petugas dari tempat selamat. Murid tidak melompat masuk, menarik mangsa atau berlatih menyelamat."], "weather_plan": "Jika hujan, kilat, panas melampau atau lantai licin, guru menggunakan ruang berbumbung yang selamat. Jika ruang tidak sesuai, aktiviti berisiko ditangguhkan dan perkara yang belum dilaksanakan dicatat.", "reflection": "Murid yang telah diperhatikan: ____ daripada ____. Kemahiran yang dikuasai: __________. Murid yang masih memerlukan bimbingan atau belum mendapat giliran: __________.", "activity_name": "Peraturan kolam melalui latihan berjalan di darat", "objective": "Murid dapat mengenal peraturan keselamatan di kolam renang melalui situasi contoh.", "success_criteria": ["Menyebut dua peraturan kolam yang sesuai berdasarkan cerita guru.", "Melakukan latihan berjalan, berhenti dan menunggu arahan di kawasan kering dengan selamat."], "prior_knowledge": "Murid boleh berjalan dan berhenti apabila diarahkan; pengalaman berenang tidak diandaikan.", "equipment": [{"item": "Kon penanda", "quantity": "Enam kon di luar kawasan berjalan.", "use": "Empat menandakan kawasan larangan rekaan; dua menandakan tempat mula dan tempat berkumpul dengan guru."}, {"item": "Papan dan buku teks BT38–39", "quantity": "Satu paparan guru.", "use": "Menerangkan peraturan kolam dan teks bobbing; bukan menggantikan kemudahan air."}, {"item": "Air minuman sendiri", "quantity": "Satu bekas setiap murid mengikut keperluan.", "use": "Minum ketika rehat; tiada bekas air untuk rendaman muka."}], "preparation": ["Semua aktiviti di tempat kering dan rata, jauh daripada kolam, sungai atau longkang. Kon hanya penanda latihan.", "Tulis tiga pesanan: tunggu arahan guru, berjalan tanpa menolak, maklumkan jika tidak sihat. Peraturan ini contoh guru berpandukan keselamatan, bukan jawapan gambar BT38.", "Jangan menyediakan kolam sementara atau air untuk mencuba bobbing. Tiada lompat masuk, apungan atau luncuran di lantai."], "organisation": ["Murid dibahagi kumpulan kecil. Satu kumpulan berjalan dalam laluan lebar di luar kawasan kon, bukan mengelilingi tepi air sebenar.", "Guru menetapkan giliran ringkas supaya setiap murid mencuba. Kumpulan lain berdiri atau duduk tenang dalam pandangan.", "Pasangan menyebut peraturan bergilir; murid tidak memegang atau menarik rakan untuk berhenti."], "movement_cues": ["Berjalan pandang hadapan, ruang antara murid dan tangan tidak menolak. Berhenti stabil apabila guru menyebut berhenti.", "Tunggu guru dan petugas sebelum masuk ke kolam sebenar. Pakai pakaian sesuai; maklumkan keadaan diri.", "Kawasan kon ialah kawasan larangan rekaan untuk memahami sempadan. Berjalan di darat tidak dikira berjalan di air."], "timing_note": "Simulasi keselamatan, gerakan ringan, rehat dan penyejukan termasuk dalam 30 minit. Tiada amali air dalam sesi ini.", "values": "Kerjasama, disiplin dan menjaga keselamatan rakan.", "classroom_example": {"teacher_says": "Dalam cerita ini, guru belum memberi arahan masuk. Apakah tindakan kamu?", "pupils_do": "Murid berhenti di tempat menunggu dan menyebut tunggu guru.", "teacher_checks": "Guru semak peraturan dikenal pasti, bukan menilai kebolehan berenang."}, "bbm": ["Kon penanda — Enam kon di luar kawasan berjalan.", "Papan dan buku teks BT38–39 — Satu paparan guru.", "Air minuman sendiri — Satu bekas setiap murid mengikut keperluan.", "Buku teks dan senarai semak pemerhatian guru."], "pak21": "Murid berlatih berpasangan atau dalam kumpulan kecil. Setiap murid mendapat giliran sendiri. Rakan memberi teguran ringkas secara sopan tanpa mengambil alih tugasan.", "phases": [{"name": "Persediaan murid dan alatan", "minutes": 2, "teacher": ["Guru memeriksa pakaian, tali kasut, keadaan murid dan alatan.", "Guru menerangkan tempat mula, laluan aktiviti dan arahan berhenti."], "pupils": ["Murid memberitahu guru jika tidak sihat.", "Murid mengambil tempat yang ditetapkan dan mendengar arahan."], "check": "Semua murid tahu tempat menunggu dan boleh berhenti apabila diarahkan.", "resources": ["Kon penanda", "Papan dan buku teks BT38–39", "Air minuman sendiri"]}, {"name": "Pemanasan badan", "minutes": 4, "teacher": ["Guru memimpin berjalan setempat dan langkah ke sisi selama dua minit.", "Guru membimbing gerakan ringan bahu, tangan, buku lali dan lutut selama dua minit."], "pupils": ["Murid bergerak dalam ruang sendiri tanpa bersentuh.", "Murid bernafas seperti biasa dan berehat jika perlu."], "check": "Murid bersedia untuk aktiviti tanpa terlalu penat.", "resources": ["Ruang lapang", "Kon penanda"]}, {"name": "Tunjuk peraturan dan sempadan", "minutes": 4, "teacher": ["Guru merujuk tajuk Awas pada BT38 dan menerangkan tiga pesanan pada papan.", "Guru menunjukkan cara menunggu, berjalan perlahan dan berkumpul di kawasan kering."], "pupils": ["Murid menyebut satu pesanan.", "Murid menunjukkan kawasan yang tidak boleh dimasuki dalam latihan."], "check": "Peraturan daripada contoh guru dilabel, bukan jawapan gambar.", "resources": ["Kon", "Papan", "Buku"]}, {"name": "Berjalan dan tunggu arahan", "minutes": 9, "teacher": ["Guru memberi giliran kumpulan kecil berjalan di luar kawasan larangan.", "Guru menyebut mula dan berhenti dengan nada biasa; bantu murid yang terlepas arahan.", "Guru menanyakan satu peraturan kepada murid yang selesai dan memberi rehat apabila perlu."], "pupils": ["Murid berjalan dengan jarak selamat.", "Murid berhenti stabil dan menunggu arahan berikutnya.", "Murid menyebut peraturan sendiri sebelum kembali ke tempat menunggu."], "check": "Setiap murid bergerak sendiri; tindakan darat tidak menjadi bukti pematuhan di kolam.", "resources": ["Kon", "Air sendiri"]}, {"name": "Pilih tindakan dalam cerita", "minutes": 7, "teacher": ["Guru membaca cerita rakan berlari sambil menolak di kolam dan guru belum hadir di tempat berkumpul.", "Guru meminta pasangan bergilir memberi tindakan selamat sambil mempraktikkan berhenti dan berkumpul.", "Guru menegaskan jangan masuk air untuk membantu sendiri jika ada kecemasan."], "pupils": ["Murid memilih berjalan tanpa menolak dalam cerita pertama.", "Murid memilih menunggu pengawasan dalam cerita kedua.", "Murid menunjukkan cara berkumpul dengan selamat di darat."], "check": "Dua respons individu diperoleh; tiada lakonan jatuh atau masuk air.", "resources": ["Papan", "Kon"]}, {"name": "Penyejukan badan dan penutup", "minutes": 4, "teacher": ["Guru memimpin berjalan perlahan selama satu minit dan regangan lembut tangan serta kaki selama dua minit.", "Guru memberi masa minum dan menanyakan satu perkara yang dipelajari."], "pupils": ["Murid meregang mengikut keselesaan tanpa sentapan.", "Murid memberitahu guru jika masih tidak selesa dan membantu mengemas alatan ringan selepas arahan."], "check": "Tiada latihan kuat selepas penyejukan. Guru mencatat perkara yang perlu disusuli.", "resources": ["Air minuman", "Ruang rehat"]}], "differentiation": {"support": {"label": "Peneroka", "support_description": "Guru membimbing satu langkah pada satu masa.", "task": "Mengenal dua peraturan dengan arahan pendek sambil berjalan di darat.", "materials": ["Kon", "Pesanan papan"], "teacher": ["Guru menunjukkan satu tindakan pada satu masa.", "Beri pilihan tunggu guru atau masuk sendiri tanpa meminta murid melakukannya di air."], "pupil_steps": ["Dengar pesanan dan tunjuk tempat menunggu.", "Berjalan perlahan mengikut laluan kering.", "Berhenti apabila diarahkan dan sebut tidak menolak.", "Pilih menunggu pengawasan bagi cerita guru belum hadir."], "product": "Dua jawapan peraturan serta lakuan darat.", "criterion": "Pengetahuan peraturan betul dengan bantuan; amali air belum dilaksanakan.", "next_step": "Ulang satu arahan yang belum jelas.", "example": {"teacher": "Guru belum hadir. Masuk atau tunggu?", "pupil": "Tunggu guru."}}, "core": {"label": "Pembina", "support_description": "Murid berlatih berpasangan dan melakukan sendiri.", "task": "Mengamalkan arahan darat dan menerangkan dua peraturan kolam.", "materials": ["Kon", "Papan"], "teacher": ["Beri giliran kepada setiap murid.", "Tanya peraturan selepas lakuan, bukan mengganggu laluan."], "pupil_steps": ["Kenal kawasan larangan rekaan.", "Berjalan dan berhenti tanpa menolak.", "Sebut dua peraturan daripada cerita guru.", "Berkumpul semula dan beri giliran pasangan."], "product": "Respons sendiri serta laluan berjalan selamat.", "criterion": "Dua peraturan dikenal; aktiviti darat tidak dikira kemahiran kolam.", "next_step": "Perkemas satu pesanan keselamatan dengan kata sendiri.", "example": {"teacher": "Mengapa tidak menolak di kolam?", "pupil": "Rakan boleh jatuh dan cedera."}}, "challenge": {"label": "Pencabar", "support_description": "Murid memperkemas satu perkara dalam kemahiran yang sama.", "task": "Memilih tindakan selamat apabila arahan belum jelas.", "materials": ["Kon", "Papan"], "teacher": ["Beri cerita mudah tentang tidak mendengar arahan.", "Kekalkan gerakan darat tanpa permainan mengejar."], "pupil_steps": ["Berjalan dalam ruang yang ditetapkan.", "Berhenti dan tunggu arahan.", "Sebut dua peraturan kolam dan satu tindakan meminta penjelasan.", "Kembali ke tempat kumpulan tanpa melintasi kawasan larangan."], "product": "Dua peraturan dan satu cara meminta bantuan.", "criterion": "Murid memilih menunggu atau bertanya, bukan masuk air sendiri.", "next_step": "Kongsi satu pesanan dengan pasangan.", "example": {"teacher": "Jika kamu tidak faham arahan masuk, apa dibuat?", "pupil": "Saya tunggu dan tanya guru."}}}, "differentiation_delivery": {"common_task": "Murid dapat mengenal peraturan keselamatan di kolam renang melalui situasi contoh.", "placement": "Bimbingan ini diberikan dalam waktu latihan dan aplikasi. Murid tidak perlu menjalani tiga kumpulan bantuan sebagai aktiviti tambahan.", "teacher_rounds": ["Guru membimbing Peneroka sebelum giliran.", "Dengar dua peraturan Pembina.", "Semak tindakan bertanya Pencabar tanpa mengubah hold amali air."], "individual_check": "Menyebut dua peraturan kolam yang sesuai berdasarkan cerita guru.", "flexible_help": "Bantuan diteruskan selagi diperlukan. Murid tidak dipaksa menambah kelajuan, jarak, beban atau ulangan untuk menunjukkan kemajuan."}, "pbd": {"method": "Soal jawab dan pemerhatian simulasi di kawasan kering.", "evidence": "Murid menyebut atau memilih peraturan yang sesuai dalam dua cerita guru.", "criterion": "Mengenal peraturan menunggu arahan, tidak menolak dan berjalan berhati-hati. Ini pengetahuan, bukan pematuhan sebenar di kolam.", "recording": "Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP.", "sample_checklist": ["Tunggu guru: ____", "Berjalan tanpa tolak: ____", "Minta bantuan jika tidak selesa: ____", "Bantuan / belum diperiksa: ____"]}, "pbd_complementary": {"5.1.3": {"method": "Pemerhatian semasa berjalan dan berhenti.", "evidence": "Respons terhadap arahan mula, berhenti dan berkumpul.", "criterion": "Murid mematuhi arahan di darat; tidak dianggap kemahiran dalam air.", "recording": "Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP.", "sample_checklist": ["Tunggu arahan: ____", "Berhenti: ____", "Bimbingan: ____"]}, "5.1.4": {"method": "Pemerhatian laluan kering dan soal jawab.", "evidence": "Murid kekal di luar kawasan larangan rekaan dan tidak menolak.", "criterion": "Mengenal sempadan dan peraturan tempat latihan.", "recording": "Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP.", "sample_checklist": ["Sempadan dipatuhi: ____", "Tidak menolak: ____", "Belum diperhatikan: ____"]}}, "intervention": ["Gunakan semula dua pilihan tindakan dalam cerita bagi murid yang keliru.", "Amali air hanya dijadualkan selepas kemudahan serta pengawasan yang sesuai tersedia; tidak disahkan melalui latihan ini."], "book_pages_text": "38, 39", "sp_focus": "", "sp_display": "2.8.1", "complementary": [{"standard_key": "5.1.3", "sp_code": "5.1.3", "sp_text": "Mematuhi arahan guru semasa melakukan aktiviti Pendidikan Jasmani.", "sk_code": "5.1", "sk_text": "Mematuhi dan mengamalkan elemen pengurusan dan keselamatan.", "domain": "afektif", "source_label": ""}, {"standard_key": "5.1.4", "sp_code": "5.1.4", "sp_text": "Mengenali dan mematuhi peraturan keselamatan di tempat melakukan aktiviti Pendidikan Jasmani.", "sk_code": "5.1", "sk_text": "Mematuhi dan mengamalkan elemen pengurusan dan keselamatan.", "domain": "afektif", "source_label": ""}], "draft_sha256": "7b1849eba73683b10e1588f54f11ad36df5efd523de2dd08086063410ecb8c28"}'::jsonb,'[{"kind": "title", "text": "Minggu 30 Sesi 1 — Peraturan kolam melalui latihan berjalan di darat"}, {"kind": "subtitle", "text": "Pendidikan Jasmani Tahun 1 | Dua sesi seminggu | 30 minit setiap sesi | R1"}, {"kind": "p", "text": "ID: PJ1-2026B-2S-W30-S1"}, {"kind": "h2", "text": "A. Maklumat pengajaran"}, {"kind": "p", "text": "Guru: ____________________ | Kelas: __________ | Tarikh: __________ | Waktu: __________"}, {"kind": "p", "text": "Unit 5: Mari Berenang"}, {"kind": "p", "text": "Tajuk buku teks: Awas dan Mari Lakukan"}, {"kind": "p", "text": "Aktiviti guru: Peraturan kolam melalui latihan berjalan di darat"}, {"kind": "p", "text": "Rujukan buku teks PJPK Tahun 1, bahagian PJ: muka surat 38, 39."}, {"kind": "p", "text": "Simulasi keselamatan, gerakan ringan, rehat dan penyejukan termasuk dalam 30 minit. Tiada amali air dalam sesi ini."}, {"kind": "h2", "text": "B. Standard dan hasil pembelajaran"}, {"kind": "p", "text": "SK utama 2.8: Menggunakan pengetahuan konsep dan prinsip mekanik dalam keyakinan dan keselamatan di air."}, {"kind": "p", "text": "SP utama 2.8.1: Mengenal pasti peraturan di kolam renang."}, {"kind": "p", "text": "SK sokongan 5.1: Mematuhi dan mengamalkan elemen pengurusan dan keselamatan."}, {"kind": "p", "text": "SP sokongan 5.1.3: Mematuhi arahan guru semasa melakukan aktiviti Pendidikan Jasmani."}, {"kind": "p", "text": "SK sokongan 5.1: Mematuhi dan mengamalkan elemen pengurusan dan keselamatan."}, {"kind": "p", "text": "SP sokongan 5.1.4: Mengenali dan mematuhi peraturan keselamatan di tempat melakukan aktiviti Pendidikan Jasmani."}, {"kind": "p", "text": "Penyesuaian di darat sahaja; amali air belum dilaksanakan."}, {"kind": "p", "text": "SP sumber yang belum dilaksanakan atau belum lengkap: 1.9.1 — Mematuhi peraturan di kolam renang. Tiada kolam; pengenalan di darat bukan amali air."}, {"kind": "p", "text": "SP sumber yang belum dilaksanakan atau belum lengkap: 1.9.2 — Melakukan kemahiran masuk ke dalam air, berdiri, berjalan, bobbing, mengapung tiarap, meluncur (glide) dan berdiri dalam air dari posisi apungan tiarap. Tiada kolam; pengenalan di darat bukan amali air."}, {"kind": "p", "text": "SP sumber yang belum dilaksanakan atau belum lengkap: 2.8.3 — Mengenal pasti kemahiran apungan tiarap yang betul. Tiada kolam; pengenalan di darat bukan amali air."}, {"kind": "p", "text": "SP sumber yang belum dilaksanakan atau belum lengkap: 2.8.4 — Mengenal pasti kemahiran luncur yang betul. Tiada kolam; pengenalan di darat bukan amali air."}, {"kind": "label", "text": "Objektif"}, {"kind": "p", "text": "Murid dapat mengenal peraturan keselamatan di kolam renang melalui situasi contoh."}, {"kind": "label", "text": "Kriteria kejayaan"}, {"kind": "p", "text": "1. Menyebut dua peraturan kolam yang sesuai berdasarkan cerita guru."}, {"kind": "p", "text": "2. Melakukan latihan berjalan, berhenti dan menunggu arahan di kawasan kering dengan selamat."}, {"kind": "p", "text": "Pengetahuan sedia ada: Murid boleh berjalan dan berhenti apabila diarahkan; pengalaman berenang tidak diandaikan."}, {"kind": "h2", "text": "C. Alatan, persediaan dan keselamatan"}, {"kind": "label", "text": "Kon penanda"}, {"kind": "p", "text": "Keperluan: Enam kon di luar kawasan berjalan."}, {"kind": "p", "text": "Kegunaan: Empat menandakan kawasan larangan rekaan; dua menandakan tempat mula dan tempat berkumpul dengan guru."}, {"kind": "label", "text": "Papan dan buku teks BT38–39"}, {"kind": "p", "text": "Keperluan: Satu paparan guru."}, {"kind": "p", "text": "Kegunaan: Menerangkan peraturan kolam dan teks bobbing; bukan menggantikan kemudahan air."}, {"kind": "label", "text": "Air minuman sendiri"}, {"kind": "p", "text": "Keperluan: Satu bekas setiap murid mengikut keperluan."}, {"kind": "p", "text": "Kegunaan: Minum ketika rehat; tiada bekas air untuk rendaman muka."}, {"kind": "label", "text": "Persediaan guru"}, {"kind": "p", "text": "1. Semua aktiviti di tempat kering dan rata, jauh daripada kolam, sungai atau longkang. Kon hanya penanda latihan."}, {"kind": "p", "text": "2. Tulis tiga pesanan: tunggu arahan guru, berjalan tanpa menolak, maklumkan jika tidak sihat. Peraturan ini contoh guru berpandukan keselamatan, bukan jawapan gambar BT38."}, {"kind": "p", "text": "3. Jangan menyediakan kolam sementara atau air untuk mencuba bobbing. Tiada lompat masuk, apungan atau luncuran di lantai."}, {"kind": "label", "text": "Susunan dan giliran murid"}, {"kind": "p", "text": "1. Murid dibahagi kumpulan kecil. Satu kumpulan berjalan dalam laluan lebar di luar kawasan kon, bukan mengelilingi tepi air sebenar."}, {"kind": "p", "text": "2. Guru menetapkan giliran ringkas supaya setiap murid mencuba. Kumpulan lain berdiri atau duduk tenang dalam pandangan."}, {"kind": "p", "text": "3. Pasangan menyebut peraturan bergilir; murid tidak memegang atau menarik rakan untuk berhenti."}, {"kind": "label", "text": "Petunjuk pergerakan"}, {"kind": "p", "text": "1. Berjalan pandang hadapan, ruang antara murid dan tangan tidak menolak. Berhenti stabil apabila guru menyebut berhenti."}, {"kind": "p", "text": "2. Tunggu guru dan petugas sebelum masuk ke kolam sebenar. Pakai pakaian sesuai; maklumkan keadaan diri."}, {"kind": "p", "text": "3. Kawasan kon ialah kawasan larangan rekaan untuk memahami sempadan. Berjalan di darat tidak dikira berjalan di air."}, {"kind": "label", "text": "BBM"}, {"kind": "p", "text": "1. Kon penanda — Enam kon di luar kawasan berjalan."}, {"kind": "p", "text": "2. Papan dan buku teks BT38–39 — Satu paparan guru."}, {"kind": "p", "text": "3. Air minuman sendiri — Satu bekas setiap murid mengikut keperluan."}, {"kind": "p", "text": "4. Buku teks dan senarai semak pemerhatian guru."}, {"kind": "p", "text": "PAK-21: Murid berlatih berpasangan atau dalam kumpulan kecil. Setiap murid mendapat giliran sendiri. Rakan memberi teguran ringkas secara sopan tanpa mengambil alih tugasan."}, {"kind": "p", "text": "Nilai: Kerjasama, disiplin dan menjaga keselamatan rakan."}, {"kind": "label", "text": "Keselamatan"}, {"kind": "p", "text": "1. Guru memeriksa pakaian, tali kasut, keadaan murid, permukaan tempat aktiviti dan alatan sebelum bermula."}, {"kind": "p", "text": "2. Murid berhenti dan memberitahu guru jika sakit, pening atau sukar bernafas. Rehat dan minum dibenarkan mengikut keperluan."}, {"kind": "p", "text": "3. Guru memastikan semua murid berada dalam pandangannya. Murid tidak menolak, menarik atau menghalang laluan rakan."}, {"kind": "p", "text": "4. Latihan di darat sahaja. Tiada rendaman muka, tahan nafas, pertandingan hembusan atau pernafasan laju."}, {"kind": "p", "text": "5. Jangan membawa murid ke tepi air untuk melengkapkan aktiviti. Tiada kolam sesuai; amali SP1.9.1 dan SP1.9.2 belum dilaksanakan."}, {"kind": "p", "text": "6. Apungan tiarap dan luncuran disebut sebagai nama kemahiran sahaja apabila gambar tidak disahkan; SP2.8.3 dan SP2.8.4 belum lengkap."}, {"kind": "p", "text": "7. Jika seseorang berada dalam bahaya di air, panggil orang dewasa atau petugas dari tempat selamat. Murid tidak melompat masuk, menarik mangsa atau berlatih menyelamat."}, {"kind": "p", "text": "Jika cuaca atau ruang tidak sesuai: Jika hujan, kilat, panas melampau atau lantai licin, guru menggunakan ruang berbumbung yang selamat. Jika ruang tidak sesuai, aktiviti berisiko ditangguhkan dan perkara yang belum dilaksanakan dicatat."}, {"kind": "h2", "text": "D. Langkah PdP"}, {"kind": "h3", "text": "Langkah 1: Persediaan murid dan alatan — 2 minit"}, {"kind": "p", "text": "Minit 0 hingga 2."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru memeriksa pakaian, tali kasut, keadaan murid dan alatan."}, {"kind": "p", "text": "2. Guru menerangkan tempat mula, laluan aktiviti dan arahan berhenti."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid memberitahu guru jika tidak sihat."}, {"kind": "p", "text": "2. Murid mengambil tempat yang ditetapkan dan mendengar arahan."}, {"kind": "p", "text": "Semakan: Semua murid tahu tempat menunggu dan boleh berhenti apabila diarahkan."}, {"kind": "p", "text": "Alatan: Kon penanda Papan dan buku teks BT38–39 Air minuman sendiri"}, {"kind": "h3", "text": "Langkah 2: Pemanasan badan — 4 minit"}, {"kind": "p", "text": "Minit 2 hingga 6."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru memimpin berjalan setempat dan langkah ke sisi selama dua minit."}, {"kind": "p", "text": "2. Guru membimbing gerakan ringan bahu, tangan, buku lali dan lutut selama dua minit."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid bergerak dalam ruang sendiri tanpa bersentuh."}, {"kind": "p", "text": "2. Murid bernafas seperti biasa dan berehat jika perlu."}, {"kind": "p", "text": "Semakan: Murid bersedia untuk aktiviti tanpa terlalu penat."}, {"kind": "p", "text": "Alatan: Ruang lapang Kon penanda"}, {"kind": "h3", "text": "Langkah 3: Tunjuk peraturan dan sempadan — 4 minit"}, {"kind": "p", "text": "Minit 6 hingga 10."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru merujuk tajuk Awas pada BT38 dan menerangkan tiga pesanan pada papan."}, {"kind": "p", "text": "2. Guru menunjukkan cara menunggu, berjalan perlahan dan berkumpul di kawasan kering."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid menyebut satu pesanan."}, {"kind": "p", "text": "2. Murid menunjukkan kawasan yang tidak boleh dimasuki dalam latihan."}, {"kind": "p", "text": "Semakan: Peraturan daripada contoh guru dilabel, bukan jawapan gambar."}, {"kind": "p", "text": "Alatan: Kon Papan Buku"}, {"kind": "h3", "text": "Langkah 4: Berjalan dan tunggu arahan — 9 minit"}, {"kind": "p", "text": "Minit 10 hingga 19."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru memberi giliran kumpulan kecil berjalan di luar kawasan larangan."}, {"kind": "p", "text": "2. Guru menyebut mula dan berhenti dengan nada biasa; bantu murid yang terlepas arahan."}, {"kind": "p", "text": "3. Guru menanyakan satu peraturan kepada murid yang selesai dan memberi rehat apabila perlu."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid berjalan dengan jarak selamat."}, {"kind": "p", "text": "2. Murid berhenti stabil dan menunggu arahan berikutnya."}, {"kind": "p", "text": "3. Murid menyebut peraturan sendiri sebelum kembali ke tempat menunggu."}, {"kind": "p", "text": "Semakan: Setiap murid bergerak sendiri; tindakan darat tidak menjadi bukti pematuhan di kolam."}, {"kind": "p", "text": "Alatan: Kon Air sendiri"}, {"kind": "h3", "text": "Langkah 5: Pilih tindakan dalam cerita — 7 minit"}, {"kind": "p", "text": "Minit 19 hingga 26."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru membaca cerita rakan berlari sambil menolak di kolam dan guru belum hadir di tempat berkumpul."}, {"kind": "p", "text": "2. Guru meminta pasangan bergilir memberi tindakan selamat sambil mempraktikkan berhenti dan berkumpul."}, {"kind": "p", "text": "3. Guru menegaskan jangan masuk air untuk membantu sendiri jika ada kecemasan."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid memilih berjalan tanpa menolak dalam cerita pertama."}, {"kind": "p", "text": "2. Murid memilih menunggu pengawasan dalam cerita kedua."}, {"kind": "p", "text": "3. Murid menunjukkan cara berkumpul dengan selamat di darat."}, {"kind": "p", "text": "Semakan: Dua respons individu diperoleh; tiada lakonan jatuh atau masuk air."}, {"kind": "p", "text": "Alatan: Papan Kon"}, {"kind": "h3", "text": "Langkah 6: Penyejukan badan dan penutup — 4 minit"}, {"kind": "p", "text": "Minit 26 hingga 30."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru memimpin berjalan perlahan selama satu minit dan regangan lembut tangan serta kaki selama dua minit."}, {"kind": "p", "text": "2. Guru memberi masa minum dan menanyakan satu perkara yang dipelajari."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid meregang mengikut keselesaan tanpa sentapan."}, {"kind": "p", "text": "2. Murid memberitahu guru jika masih tidak selesa dan membantu mengemas alatan ringan selepas arahan."}, {"kind": "p", "text": "Semakan: Tiada latihan kuat selepas penyejukan. Guru mencatat perkara yang perlu disusuli."}, {"kind": "p", "text": "Alatan: Air minuman Ruang rehat"}, {"kind": "p", "text": "Jumlah masa: 30 minit."}, {"kind": "label", "text": "Contoh arahan kelas"}, {"kind": "p", "text": "Guru: Dalam cerita ini, guru belum memberi arahan masuk. Apakah tindakan kamu?"}, {"kind": "p", "text": "Murid: Murid berhenti di tempat menunggu dan menyebut tunggu guru."}, {"kind": "p", "text": "Semakan guru: Guru semak peraturan dikenal pasti, bukan menilai kebolehan berenang."}, {"kind": "h2", "text": "E. PdP terbeza", "anchor": "pdp-PJ1-2026B-2S-W30-S1"}, {"kind": "p", "text": "Tugasan bersama: Murid dapat mengenal peraturan keselamatan di kolam renang melalui situasi contoh."}, {"kind": "p", "text": "Bimbingan ini diberikan dalam waktu latihan dan aplikasi. Murid tidak perlu menjalani tiga kumpulan bantuan sebagai aktiviti tambahan."}, {"kind": "label", "text": "Bimbingan guru"}, {"kind": "p", "text": "1. Guru membimbing Peneroka sebelum giliran."}, {"kind": "p", "text": "2. Dengar dua peraturan Pembina."}, {"kind": "p", "text": "3. Semak tindakan bertanya Pencabar tanpa mengubah hold amali air."}, {"kind": "p", "text": "Semakan individu: Menyebut dua peraturan kolam yang sesuai berdasarkan cerita guru."}, {"kind": "p", "text": "Bantuan diteruskan selagi diperlukan. Murid tidak dipaksa menambah kelajuan, jarak, beban atau ulangan untuk menunjukkan kemajuan."}, {"kind": "h3", "text": "Peneroka"}, {"kind": "p", "text": "Guru membimbing satu langkah pada satu masa."}, {"kind": "p", "text": "Tugasan: Mengenal dua peraturan dengan arahan pendek sambil berjalan di darat."}, {"kind": "label", "text": "Alatan"}, {"kind": "p", "text": "1. Kon"}, {"kind": "p", "text": "2. Pesanan papan"}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru menunjukkan satu tindakan pada satu masa."}, {"kind": "p", "text": "2. Beri pilihan tunggu guru atau masuk sendiri tanpa meminta murid melakukannya di air."}, {"kind": "label", "text": "Langkah murid"}, {"kind": "p", "text": "1. Dengar pesanan dan tunjuk tempat menunggu."}, {"kind": "p", "text": "2. Berjalan perlahan mengikut laluan kering."}, {"kind": "p", "text": "3. Berhenti apabila diarahkan dan sebut tidak menolak."}, {"kind": "p", "text": "4. Pilih menunggu pengawasan bagi cerita guru belum hadir."}, {"kind": "p", "text": "Contoh guru: Guru belum hadir. Masuk atau tunggu?"}, {"kind": "p", "text": "Contoh respons murid: Tunggu guru."}, {"kind": "p", "text": "Hasil individu: Dua jawapan peraturan serta lakuan darat."}, {"kind": "p", "text": "Kriteria: Pengetahuan peraturan betul dengan bantuan; amali air belum dilaksanakan."}, {"kind": "p", "text": "Susulan: Ulang satu arahan yang belum jelas."}, {"kind": "h3", "text": "Pembina"}, {"kind": "p", "text": "Murid berlatih berpasangan dan melakukan sendiri."}, {"kind": "p", "text": "Tugasan: Mengamalkan arahan darat dan menerangkan dua peraturan kolam."}, {"kind": "label", "text": "Alatan"}, {"kind": "p", "text": "1. Kon"}, {"kind": "p", "text": "2. Papan"}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Beri giliran kepada setiap murid."}, {"kind": "p", "text": "2. Tanya peraturan selepas lakuan, bukan mengganggu laluan."}, {"kind": "label", "text": "Langkah murid"}, {"kind": "p", "text": "1. Kenal kawasan larangan rekaan."}, {"kind": "p", "text": "2. Berjalan dan berhenti tanpa menolak."}, {"kind": "p", "text": "3. Sebut dua peraturan daripada cerita guru."}, {"kind": "p", "text": "4. Berkumpul semula dan beri giliran pasangan."}, {"kind": "p", "text": "Contoh guru: Mengapa tidak menolak di kolam?"}, {"kind": "p", "text": "Contoh respons murid: Rakan boleh jatuh dan cedera."}, {"kind": "p", "text": "Hasil individu: Respons sendiri serta laluan berjalan selamat."}, {"kind": "p", "text": "Kriteria: Dua peraturan dikenal; aktiviti darat tidak dikira kemahiran kolam."}, {"kind": "p", "text": "Susulan: Perkemas satu pesanan keselamatan dengan kata sendiri."}, {"kind": "h3", "text": "Pencabar"}, {"kind": "p", "text": "Murid memperkemas satu perkara dalam kemahiran yang sama."}, {"kind": "p", "text": "Tugasan: Memilih tindakan selamat apabila arahan belum jelas."}, {"kind": "label", "text": "Alatan"}, {"kind": "p", "text": "1. Kon"}, {"kind": "p", "text": "2. Papan"}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Beri cerita mudah tentang tidak mendengar arahan."}, {"kind": "p", "text": "2. Kekalkan gerakan darat tanpa permainan mengejar."}, {"kind": "label", "text": "Langkah murid"}, {"kind": "p", "text": "1. Berjalan dalam ruang yang ditetapkan."}, {"kind": "p", "text": "2. Berhenti dan tunggu arahan."}, {"kind": "p", "text": "3. Sebut dua peraturan kolam dan satu tindakan meminta penjelasan."}, {"kind": "p", "text": "4. Kembali ke tempat kumpulan tanpa melintasi kawasan larangan."}, {"kind": "p", "text": "Contoh guru: Jika kamu tidak faham arahan masuk, apa dibuat?"}, {"kind": "p", "text": "Contoh respons murid: Saya tunggu dan tanya guru."}, {"kind": "p", "text": "Hasil individu: Dua peraturan dan satu cara meminta bantuan."}, {"kind": "p", "text": "Kriteria: Murid memilih menunggu atau bertanya, bukan masuk air sendiri."}, {"kind": "p", "text": "Susulan: Kongsi satu pesanan dengan pasangan."}, {"kind": "h2", "text": "F. Pentaksiran Bilik Darjah"}, {"kind": "h3", "text": "PBD utama — SP 2.8.1"}, {"kind": "p", "text": "Kaedah: Soal jawab dan pemerhatian simulasi di kawasan kering."}, {"kind": "p", "text": "Bukti: Murid menyebut atau memilih peraturan yang sesuai dalam dua cerita guru."}, {"kind": "p", "text": "Kriteria: Mengenal peraturan menunggu arahan, tidak menolak dan berjalan berhati-hati. Ini pengetahuan, bukan pematuhan sebenar di kolam."}, {"kind": "p", "text": "Rekod: Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP."}, {"kind": "label", "text": "Senarai semak"}, {"kind": "p", "text": "1. Tunggu guru: ____"}, {"kind": "p", "text": "2. Berjalan tanpa tolak: ____"}, {"kind": "p", "text": "3. Minta bantuan jika tidak selesa: ____"}, {"kind": "p", "text": "4. Bantuan / belum diperiksa: ____"}, {"kind": "h3", "text": "PBD sokongan — SP 5.1.3"}, {"kind": "p", "text": "Kaedah: Pemerhatian semasa berjalan dan berhenti."}, {"kind": "p", "text": "Bukti: Respons terhadap arahan mula, berhenti dan berkumpul."}, {"kind": "p", "text": "Kriteria: Murid mematuhi arahan di darat; tidak dianggap kemahiran dalam air."}, {"kind": "p", "text": "Rekod: Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP."}, {"kind": "label", "text": "Senarai semak"}, {"kind": "p", "text": "1. Tunggu arahan: ____"}, {"kind": "p", "text": "2. Berhenti: ____"}, {"kind": "p", "text": "3. Bimbingan: ____"}, {"kind": "h3", "text": "PBD sokongan — SP 5.1.4"}, {"kind": "p", "text": "Kaedah: Pemerhatian laluan kering dan soal jawab."}, {"kind": "p", "text": "Bukti: Murid kekal di luar kawasan larangan rekaan dan tidak menolak."}, {"kind": "p", "text": "Kriteria: Mengenal sempadan dan peraturan tempat latihan."}, {"kind": "p", "text": "Rekod: Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP."}, {"kind": "label", "text": "Senarai semak"}, {"kind": "p", "text": "1. Sempadan dipatuhi: ____"}, {"kind": "p", "text": "2. Tidak menolak: ____"}, {"kind": "p", "text": "3. Belum diperhatikan: ____"}, {"kind": "h2", "text": "G. Refleksi dan intervensi"}, {"kind": "p", "text": "Murid yang telah diperhatikan: ____ daripada ____. Kemahiran yang dikuasai: __________. Murid yang masih memerlukan bimbingan atau belum mendapat giliran: __________."}, {"kind": "label", "text": "Intervensi"}, {"kind": "p", "text": "1. Gunakan semula dua pilihan tindakan dalam cerita bagi murid yang keliru."}, {"kind": "p", "text": "2. Amali air hanya dijadualkan selepas kemudahan serta pengawasan yang sesuai tersedia; tidak disahkan melalui latihan ini."}]'::jsonb,'{"source_hold": "", "adaptation_note": "Tiada kolam sesuai. Dua sesi di darat dibenarkan guru. Pengetahuan keselamatan dan bobbing daripada teks diajar, tetapi latihan darat tidak memenuhi amali di kolam SP1.9.1/1.9.2. Apungan tiarap dan luncur hanya pengenalan nama/konsep jika gambar belum disahkan; SP2.8.3/2.8.4 belum lengkap. Tiada kolam sementara, rendaman muka, tahan nafas, luncur di lantai atau menyelamat secara fizikal.", "source_images_verified": true, "audio_verified": false, "ba_verified": false, "classroom_trial_performed": false}'::jsonb),
  ('PJ1-2026B-2S-W30-S2','pj',1,2026,30,2,30,'2.8.2',array[38,39]::int[],'2f0d9547b78fcf7d4689f227297b2d2be4bf71576a91dc7e2a7d7f3c3c7d4c03','ff5b63036d01b4c5cecc0d86b7e32997e93594d98d266c086f2b5bac75609d72','715d2dd93e616381f7de4fb5e317e008bae7007088b12831c3d9d17a2be5d6d7','ACCEPTED_FROM_DOWNLOADED_CATATAN',false,'{"id": "PJ1-2026B-2S-W30-S2", "subject": "Pendidikan Jasmani", "year": 1, "week": 30, "session": 2, "revision": "PJ1-30MIN-REVIEW-R1", "date": "", "teaching_time": "", "minutes": 30, "sessions_per_week": 2, "weekly_minutes": 60, "title": "Awas dan Mari Lakukan", "source_title": "Awas dan Mari Lakukan", "unit": "Unit 5: Mari Berenang", "source_row_id": "PJ1-RPT2026-T10-R3", "source_row_literal": ["30\n\nKump A: 23.08.2026-27.08.2026\n\nKump B: 24.08.2026-28.08.2026\n\n25.8.2026 (Selasa)\nCuti Maulud Nabi", "5: MARI BERENANG\nAWAS DAN MARI LAKUKAN", "1.9 Melakukan kemahiran keyakinan dan keselamatan dalam air. \n2.8 Menggunakan pengetahuan konsep keyakinan dan keselamatan air\n\n5.1 Mematuhi dan mengamalkan elemen pengurusan dan keselamatan.", "1.9.1 Mematuhi peraturan di kolam renang. \n1.9.2 Melakukan kemahiran masuk ke dalam air, berdiri, berjalan, bobbing, mengapung tiarap, meluncur (glide), dan berdiri dalam air dari posisi apungan tiarap.\n\n2.8.1 Mengenal pasti peraturan di kolam renang. \n2.8.2 Mengenal pasti kemahiran bobbing yang betul. \n2.8.3 Mengenal pasti kemahiran apungan tiarap yang betul. \n2.8.4 Mengenal pasti kemahiran luncur yang betul.\n\n5.1.3 Mematuhi arahan guru semasa melakukan aktiviti Pendidikan Jasmani. \n5.1.4 Mengenali dan mematuhi peraturan keselamatan di tempat melakukan aktiviti Pendidikan Jasmani.", "Pemerhatian /\nPentaksiran\n\nBBB/BBM\nBT m/s 37-39"], "rpt_original_page_literal": "37-39", "source_pages": [38, 39], "source_pdf_pages": [46, 47], "rpt_book_pages": "38, 39", "main_standard_key": "2.8.2", "sk_code": "2.8", "sk_text": "Menggunakan pengetahuan konsep dan prinsip mekanik dalam keyakinan dan keselamatan di air.", "sp_code": "2.8.2", "sp_text": "Mengenal pasti kemahiran bobbing yang betul.", "complementary_standards": [{"standard_key": "2.8.1", "sp_code": "2.8.1", "sp_text": "Mengenal pasti peraturan di kolam renang.", "sk_code": "2.8", "sk_text": "Menggunakan pengetahuan konsep dan prinsip mekanik dalam keyakinan dan keselamatan di air.", "domain": "kognitif", "source_label": ""}, {"standard_key": "5.1.3", "sp_code": "5.1.3", "sp_text": "Mematuhi arahan guru semasa melakukan aktiviti Pendidikan Jasmani.", "sk_code": "5.1", "sk_text": "Mematuhi dan mengamalkan elemen pengurusan dan keselamatan.", "domain": "afektif", "source_label": ""}, {"standard_key": "5.1.4", "sp_code": "5.1.4", "sp_text": "Mengenali dan mematuhi peraturan keselamatan di tempat melakukan aktiviti Pendidikan Jasmani.", "sk_code": "5.1", "sk_text": "Mematuhi dan mengamalkan elemen pengurusan dan keselamatan.", "domain": "afektif", "source_label": ""}], "source_task": "Mengenal bobbing dan had latihan tanpa kolam", "authoring_focus": "Mengenal bobbing dan had latihan tanpa kolam", "source_hold": "Teks RPT, DSKP dan buku dibaca. Semakan imej guling BT35 dan kod DSKP hlm70 terhalang ralat402; OCR dan teks salinan menyokong kod berulang, bukan kelulusan visual. Guru perlu menilai postur, alat dan kesediaan setiap murid.", "practical_required": true, "warmup_required": true, "cooldown_required": true, "facility_replacement": true, "facility_replacement_note": "Penyesuaian di darat sahaja; amali air belum dilaksanakan.", "source_subset_focus": false, "source_subset_note": "", "adaptation_note": "Tiada kolam sesuai. Dua sesi di darat dibenarkan guru. Pengetahuan keselamatan dan bobbing daripada teks diajar, tetapi latihan darat tidak memenuhi amali di kolam SP1.9.1/1.9.2. Apungan tiarap dan luncur hanya pengenalan nama/konsep jika gambar belum disahkan; SP2.8.3/2.8.4 belum lengkap. Tiada kolam sementara, rendaman muka, tahan nafas, luncur di lantai atau menyelamat secara fizikal.", "privacy_adaptation": false, "privacy_note": "", "held_standards": [{"standard_key": "1.9.1", "sp_code": "1.9.1", "sp_text": "Mematuhi peraturan di kolam renang.", "sk_code": "1.9", "sk_text": "Melakukan kemahiran keyakinan dan keselamatan dalam air.", "status": "PENDING_REAL_WATER_PRACTICE", "reason": "Tiada kolam; pengenalan di darat bukan amali air."}, {"standard_key": "1.9.2", "sp_code": "1.9.2", "sp_text": "Melakukan kemahiran masuk ke dalam air, berdiri, berjalan, bobbing, mengapung tiarap, meluncur (glide) dan berdiri dalam air dari posisi apungan tiarap.", "sk_code": "1.9", "sk_text": "Melakukan kemahiran keyakinan dan keselamatan dalam air.", "status": "PENDING_REAL_WATER_PRACTICE", "reason": "Tiada kolam; pengenalan di darat bukan amali air."}, {"standard_key": "2.8.3", "sp_code": "2.8.3", "sp_text": "Mengenal pasti kemahiran apungan tiarap yang betul.", "sk_code": "2.8", "sk_text": "Menggunakan pengetahuan konsep dan prinsip mekanik dalam keyakinan dan keselamatan di air.", "status": "PARTIAL_CONCEPT_ONLY", "reason": "Tiada kolam; pengenalan di darat bukan amali air."}, {"standard_key": "2.8.4", "sp_code": "2.8.4", "sp_text": "Mengenal pasti kemahiran luncur yang betul.", "sk_code": "2.8", "sk_text": "Menggunakan pengetahuan konsep dan prinsip mekanik dalam keyakinan dan keselamatan di air.", "status": "PARTIAL_CONCEPT_ONLY", "reason": "Tiada kolam; pengenalan di darat bukan amali air."}], "source_code_conflict": false, "source_code_note": "", "unperformed_literal_elements": ["1.9.1: Tiada kolam; pengenalan di darat bukan amali air.", "1.9.2: Tiada kolam; pengenalan di darat bukan amali air.", "2.8.3: Tiada kolam; pengenalan di darat bukan amali air.", "2.8.4: Tiada kolam; pengenalan di darat bukan amali air."], "source_mapping_review": "20 RPH, dua sesi30minit seminggu dibenarkan guru. S1/S2 ialah cadangan pecahan RPT mingguan, bukan nombor sesi yang tercetak dalam RPT.", "routine_book_pages": [46, 47], "active": false, "production_write_performed": false, "presentation_review": "PENDING_TEACHER_REVIEW", "safety": ["Guru memeriksa pakaian, tali kasut, keadaan murid, permukaan tempat aktiviti dan alatan sebelum bermula.", "Murid berhenti dan memberitahu guru jika sakit, pening atau sukar bernafas. Rehat dan minum dibenarkan mengikut keperluan.", "Guru memastikan semua murid berada dalam pandangannya. Murid tidak menolak, menarik atau menghalang laluan rakan.", "Latihan di darat sahaja. Tiada rendaman muka, tahan nafas, pertandingan hembusan atau pernafasan laju.", "Jangan membawa murid ke tepi air untuk melengkapkan aktiviti. Tiada kolam sesuai; amali SP1.9.1 dan SP1.9.2 belum dilaksanakan.", "Apungan tiarap dan luncuran disebut sebagai nama kemahiran sahaja apabila gambar tidak disahkan; SP2.8.3 dan SP2.8.4 belum lengkap.", "Jika seseorang berada dalam bahaya di air, panggil orang dewasa atau petugas dari tempat selamat. Murid tidak melompat masuk, menarik mangsa atau berlatih menyelamat."], "weather_plan": "Jika hujan, kilat, panas melampau atau lantai licin, guru menggunakan ruang berbumbung yang selamat. Jika ruang tidak sesuai, aktiviti berisiko ditangguhkan dan perkara yang belum dilaksanakan dicatat.", "reflection": "Murid yang telah diperhatikan: ____ daripada ____. Kemahiran yang dikuasai: __________. Murid yang masih memerlukan bimbingan atau belum mendapat giliran: __________.", "activity_name": "Mengenal bobbing tanpa latihan dalam air", "objective": "Murid dapat mengenal cara pernafasan dalam kemahiran bobbing melalui penerangan guru.", "success_criteria": ["Menyatakan menarik nafas ketika kepala di atas permukaan air dan menghembus ketika di dalam air berdasarkan teks.", "Menyebut satu peraturan pengawasan sebelum melakukan aktiviti air sebenar."], "prior_knowledge": "Murid telah mengenal peraturan menunggu guru dan berjalan tanpa menolak; kemahiran berenang tidak diandaikan.", "equipment": [{"item": "Kon penanda", "quantity": "Enam kon di luar kawasan berjalan.", "use": "Empat menandakan kawasan larangan rekaan; dua menandakan tempat mula dan tempat berkumpul dengan guru."}, {"item": "Papan dan buku teks BT38–39", "quantity": "Satu paparan guru.", "use": "Menerangkan peraturan kolam dan teks bobbing; bukan menggantikan kemudahan air."}, {"item": "Air minuman sendiri", "quantity": "Satu bekas setiap murid mengikut keperluan.", "use": "Minum ketika rehat; tiada bekas air untuk rendaman muka."}], "preparation": ["Semua aktiviti di tempat kering dan rata, jauh daripada kolam, sungai atau longkang. Kon hanya penanda latihan.", "Tulis tiga pesanan: tunggu arahan guru, berjalan tanpa menolak, maklumkan jika tidak sihat. Peraturan ini contoh guru berpandukan keselamatan, bukan jawapan gambar BT38.", "Jangan menyediakan kolam sementara atau air untuk mencuba bobbing. Tiada lompat masuk, apungan atau luncuran di lantai."], "organisation": ["Murid berpasangan di ruang kering. Guru memberi penerangan kepada semua sebelum setiap pasangan bergerak perlahan dalam laluan lebar.", "Pasangan berhenti di tanda kon untuk menjawab, kemudian kembali melalui sisi. Laluan tidak bersilang dan tidak mengelilingi air sebenar.", "Semua pernafasan kekal biasa. Tiada tunduk muka ke bekas air, mencangkung berulang untuk meniru bobbing atau pertandingan menahan nafas."], "movement_cues": ["BT39 menerangkan bobbing sebagai tenggelam timbul di air: menarik nafas ketika kepala di permukaan dan menghembus melalui hidung atau mulut ketika di dalam air.", "Dalam kelas, murid hanya mengenal urutan melalui penerangan. Mereka tidak mencuba pernafasan dalam air.", "Apung tiarap dan luncur ialah nama kemahiran lain pada BT39. Bentuk tekniknya belum disahkan melalui gambar; pengenalan nama bukan penguasaan SP2.8.3 atau SP2.8.4.", "Hanya guru atau pengajar yang sesuai di tempat air selamat boleh membimbing amali sebenar. Latihan darat bukan bukti murid sudah selamat berenang."], "timing_note": "Berjalan ringan, penerangan ketika berhenti, rehat dan penyejukan termasuk dalam 30 minit. Tiada amali air.", "values": "Kerjasama, disiplin dan menjaga keselamatan rakan.", "classroom_example": {"teacher_says": "Menurut teks, bilakah kepala berada di atas air: ketika menarik atau menghembus nafas?", "pupils_do": "Murid menjawab menarik nafas dan terus bernafas seperti biasa di darat.", "teacher_checks": "Guru menilai jawapan, bukan mengira tempoh hembusan atau tahan nafas."}, "bbm": ["Kon penanda — Enam kon di luar kawasan berjalan.", "Papan dan buku teks BT38–39 — Satu paparan guru.", "Air minuman sendiri — Satu bekas setiap murid mengikut keperluan.", "Buku teks dan senarai semak pemerhatian guru."], "pak21": "Murid berlatih berpasangan atau dalam kumpulan kecil. Setiap murid mendapat giliran sendiri. Rakan memberi teguran ringkas secara sopan tanpa mengambil alih tugasan.", "phases": [{"name": "Persediaan murid dan alatan", "minutes": 2, "teacher": ["Guru memeriksa pakaian, tali kasut, keadaan murid dan alatan.", "Guru menerangkan tempat mula, laluan aktiviti dan arahan berhenti."], "pupils": ["Murid memberitahu guru jika tidak sihat.", "Murid mengambil tempat yang ditetapkan dan mendengar arahan."], "check": "Semua murid tahu tempat menunggu dan boleh berhenti apabila diarahkan.", "resources": ["Kon penanda", "Papan dan buku teks BT38–39", "Air minuman sendiri"]}, {"name": "Pemanasan badan", "minutes": 4, "teacher": ["Guru memimpin berjalan setempat dan langkah ke sisi selama dua minit.", "Guru membimbing gerakan ringan bahu, tangan, buku lali dan lutut selama dua minit."], "pupils": ["Murid bergerak dalam ruang sendiri tanpa bersentuh.", "Murid bernafas seperti biasa dan berehat jika perlu."], "check": "Murid bersedia untuk aktiviti tanpa terlalu penat.", "resources": ["Ruang lapang", "Kon penanda"]}, {"name": "Baca penerangan bobbing", "minutes": 4, "teacher": ["Guru membaca maklumat BT39 dengan ayat mudah.", "Guru menggunakan gerak tangan sendiri untuk menunjukkan kepala di atas dan di dalam air, tanpa meminta murid melakukan rendaman.", "Guru mengulang peraturan tunggu pengawasan dan tidak mencuba sendiri."], "pupils": ["Murid mendengar dua keadaan kepala.", "Murid menyebut tarik di atas, hembus di dalam dengan pernafasan biasa."], "check": "Urutan dikenal secara lisan sahaja.", "resources": ["BT39", "Papan"]}, {"name": "Berjalan, berhenti dan jawab", "minutes": 9, "teacher": ["Guru memberi giliran pasangan berjalan pendek ke tanda kon, berhenti dan menjawab satu soalan.", "Guru menyoal kedua-dua murid tentang bila menarik dan menghembus nafas.", "Guru menyusun giliran supaya tiada larian, lorong sesak atau menunggu tanpa pengawasan."], "pupils": ["Murid berjalan tenang dan berhenti sebelum menjawab.", "Setiap murid menyatakan kedua-dua bahagian urutan bobbing.", "Murid kembali ke tempat sendiri melalui sisi dan memberi giliran pasangan lain."], "check": "Pengetahuan individu dinilai; berjalan bukan amali bobbing.", "resources": ["Kon", "Papan"]}, {"name": "Betulkan urutan contoh", "minutes": 7, "teacher": ["Guru menyebut contoh salah: menarik nafas ketika kepala di dalam air.", "Guru meminta setiap pasangan membetulkan contoh, kemudian berjalan perlahan semula dalam ruang sendiri.", "Guru menanyakan peraturan jika pengajar belum bersedia dan memberi rehat/minum."], "pupils": ["Murid membetulkan jawapan kepada menarik di atas permukaan air.", "Murid menyebut menghembus ketika di dalam air mengikut teks.", "Murid memilih menunggu pengajar, bukan mencuba di rumah atau bekas air."], "check": "Dua bahagian bobbing dan satu pesanan pengawasan disebut.", "resources": ["Papan", "Kon", "Air sendiri"]}, {"name": "Penyejukan badan dan penutup", "minutes": 4, "teacher": ["Guru memimpin berjalan perlahan selama satu minit dan regangan lembut tangan serta kaki selama dua minit.", "Guru memberi masa minum dan menanyakan satu perkara yang dipelajari."], "pupils": ["Murid meregang mengikut keselesaan tanpa sentapan.", "Murid memberitahu guru jika masih tidak selesa dan membantu mengemas alatan ringan selepas arahan."], "check": "Tiada latihan kuat selepas penyejukan. Guru mencatat perkara yang perlu disusuli.", "resources": ["Air minuman", "Ruang rehat"]}], "differentiation": {"support": {"label": "Peneroka", "support_description": "Guru membimbing satu langkah pada satu masa.", "task": "Mengenal dua keadaan pernafasan bobbing dengan kata bantu.", "materials": ["BT39", "Papan", "Kon"], "teacher": ["Guru memberi pilihan tarik atau hembus satu soalan pada satu masa.", "Gunakan gerak tangan guru sahaja sebagai bantuan urutan; jangan arah murid tahan nafas."], "pupil_steps": ["Dengar penerangan kepala di atas air.", "Sebut menarik nafas di atas dan menghembus di dalam air.", "Berjalan perlahan dan berhenti sebelum menjawab semula.", "Sebut tunggu guru sebelum sebarang amali air."], "product": "Dua jawapan urutan serta satu peraturan pengawasan.", "criterion": "Jawapan tepat dengan bantuan; tiada lakuan air atau TP akuatik direkod.", "next_step": "Ulang penerangan menggunakan dua kata sahaja.", "example": {"teacher": "Di atas air, tarik atau hembus?", "pupil": "Tarik nafas."}}, "core": {"label": "Pembina", "support_description": "Murid berlatih berpasangan dan melakukan sendiri.", "task": "Menerangkan urutan bobbing sambil mengikuti giliran berjalan selamat.", "materials": ["Papan", "Kon"], "teacher": ["Pastikan murid berhenti sebelum menjawab.", "Tanya kedua-dua keadaan kepada setiap murid, bukan satu kepada seorang."], "pupil_steps": ["Dengar teks dan kenal dua keadaan kepala.", "Jalan ke tanda dan berhenti.", "Terangkan tarik ketika di atas air dan hembus ketika di dalam air.", "Kembali melalui sisi dan sebut tunggu pengawasan."], "product": "Urutan lisan individu dan giliran darat selamat.", "criterion": "Dua bahagian dijawab sendiri; tidak mendakwa boleh bobbing sebenar.", "next_step": "Baiki bahagian yang tertukar sahaja.", "example": {"teacher": "Adakah berjalan ini sudah dikira bobbing?", "pupil": "Tidak, bobbing sebenar dilakukan dalam air dengan bimbingan."}}, "challenge": {"label": "Pencabar", "support_description": "Murid memperkemas satu perkara dalam kemahiran yang sama.", "task": "Membetulkan satu urutan salah dan menerangkan batas latihan.", "materials": ["BT39", "Papan", "Kon"], "teacher": ["Beri satu contoh salah yang pendek.", "Terima jawapan mudah tanpa meminta hembusan panjang atau istilah sukar."], "pupil_steps": ["Berjalan dan berhenti di tempat yang ditanda.", "Betulkan contoh menarik nafas ketika kepala di dalam air.", "Sebut semula dua bahagian urutan bobbing.", "Jelaskan bahawa amali air memerlukan guru dan kolam yang sesuai."], "product": "Urutan betul dan satu pembetulan individu.", "criterion": "Penjelasan mengikut teks dan tidak mendorong latihan sendiri di air.", "next_step": "Kongsi pesanan menunggu pengawasan kepada pasangan.", "example": {"teacher": "Bolehkah mencuba dalam baldi di rumah?", "pupil": "Tidak. Tunggu pengajar di kolam yang sesuai."}}}, "differentiation_delivery": {"common_task": "Murid dapat mengenal cara pernafasan dalam kemahiran bobbing melalui penerangan guru.", "placement": "Bimbingan ini diberikan dalam waktu latihan dan aplikasi. Murid tidak perlu menjalani tiga kumpulan bantuan sebagai aktiviti tambahan.", "teacher_rounds": ["Bacakan kata bantu kepada Peneroka.", "Dengar kedua-dua jawapan Pembina.", "Semak pembetulan Pencabar tanpa menambah latihan pernafasan."], "individual_check": "Menyatakan menarik nafas ketika kepala di atas permukaan air dan menghembus ketika di dalam air berdasarkan teks.", "flexible_help": "Bantuan diteruskan selagi diperlukan. Murid tidak dipaksa menambah kelajuan, jarak, beban atau ulangan untuk menunjukkan kemajuan."}, "pbd": {"method": "Soal jawab individu berdasarkan teks BT39.", "evidence": "Dua jawapan tentang menarik nafas ketika kepala di atas air dan menghembus ketika di dalam air.", "criterion": "Kedua-duanya dikenal dengan betul; bantuan dicatat. Ini pengetahuan sahaja, bukan amali bobbing.", "recording": "Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP.", "sample_checklist": ["Tarik di atas: ____", "Hembus di dalam: ____", "Bantuan / belum disemak: ____"]}, "pbd_complementary": {"2.8.1": {"method": "Soal jawab individu selepas mengenal urutan bobbing dan ketika semua murid berhenti.", "evidence": "Murid menyebut menunggu guru atau pengajar serta pengawasan yang sesuai sebelum sebarang amali air sebenar.", "criterion": "Murid mengenal satu peraturan pengawasan dan tidak mencuba sendiri. Ini pengetahuan peraturan, bukan pematuhan sebenar di kolam.", "recording": "Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP.", "sample_checklist": ["Peraturan pengawasan yang disebut: ____", "Menunggu, bukan mencuba sendiri: ____", "Bantuan / belum disemak: ____"]}, "5.1.3": {"method": "Pemerhatian semasa berjalan dan berhenti.", "evidence": "Respons terhadap arahan mula, berhenti dan berkumpul.", "criterion": "Murid mematuhi arahan di darat; tidak dianggap kemahiran dalam air.", "recording": "Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP.", "sample_checklist": ["Tunggu arahan: ____", "Berhenti: ____", "Bimbingan: ____"]}, "5.1.4": {"method": "Pemerhatian laluan kering dan soal jawab.", "evidence": "Murid kekal di luar kawasan larangan rekaan dan tidak menolak.", "criterion": "Mengenal sempadan dan peraturan tempat latihan.", "recording": "Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP.", "sample_checklist": ["Sempadan dipatuhi: ____", "Tidak menolak: ____", "Belum diperhatikan: ____"]}}, "intervention": ["Ulang urutan melalui kata dan gerak tangan guru.", "Amali air serta teknik apungan/luncur kekal belum dilaksanakan atau belum lengkap sehingga kemudahan dan bukti yang sesuai diperoleh."], "book_pages_text": "38, 39", "sp_focus": "", "sp_display": "2.8.2", "complementary": [{"standard_key": "2.8.1", "sp_code": "2.8.1", "sp_text": "Mengenal pasti peraturan di kolam renang.", "sk_code": "2.8", "sk_text": "Menggunakan pengetahuan konsep dan prinsip mekanik dalam keyakinan dan keselamatan di air.", "domain": "kognitif", "source_label": ""}, {"standard_key": "5.1.3", "sp_code": "5.1.3", "sp_text": "Mematuhi arahan guru semasa melakukan aktiviti Pendidikan Jasmani.", "sk_code": "5.1", "sk_text": "Mematuhi dan mengamalkan elemen pengurusan dan keselamatan.", "domain": "afektif", "source_label": ""}, {"standard_key": "5.1.4", "sp_code": "5.1.4", "sp_text": "Mengenali dan mematuhi peraturan keselamatan di tempat melakukan aktiviti Pendidikan Jasmani.", "sk_code": "5.1", "sk_text": "Mematuhi dan mengamalkan elemen pengurusan dan keselamatan.", "domain": "afektif", "source_label": ""}], "draft_sha256": "428910b16c12f8e4e910eb31e3f765a7737c6c319c658b7f9cf966604e1f443e"}'::jsonb,'[{"kind": "title", "text": "Minggu 30 Sesi 2 — Mengenal bobbing tanpa latihan dalam air"}, {"kind": "subtitle", "text": "Pendidikan Jasmani Tahun 1 | Dua sesi seminggu | 30 minit setiap sesi | R1"}, {"kind": "p", "text": "ID: PJ1-2026B-2S-W30-S2"}, {"kind": "h2", "text": "A. Maklumat pengajaran"}, {"kind": "p", "text": "Guru: ____________________ | Kelas: __________ | Tarikh: __________ | Waktu: __________"}, {"kind": "p", "text": "Unit 5: Mari Berenang"}, {"kind": "p", "text": "Tajuk buku teks: Awas dan Mari Lakukan"}, {"kind": "p", "text": "Aktiviti guru: Mengenal bobbing tanpa latihan dalam air"}, {"kind": "p", "text": "Rujukan buku teks PJPK Tahun 1, bahagian PJ: muka surat 38, 39."}, {"kind": "p", "text": "Berjalan ringan, penerangan ketika berhenti, rehat dan penyejukan termasuk dalam 30 minit. Tiada amali air."}, {"kind": "h2", "text": "B. Standard dan hasil pembelajaran"}, {"kind": "p", "text": "SK utama 2.8: Menggunakan pengetahuan konsep dan prinsip mekanik dalam keyakinan dan keselamatan di air."}, {"kind": "p", "text": "SP utama 2.8.2: Mengenal pasti kemahiran bobbing yang betul."}, {"kind": "p", "text": "SK sokongan 2.8: Menggunakan pengetahuan konsep dan prinsip mekanik dalam keyakinan dan keselamatan di air."}, {"kind": "p", "text": "SP sokongan 2.8.1: Mengenal pasti peraturan di kolam renang."}, {"kind": "p", "text": "SK sokongan 5.1: Mematuhi dan mengamalkan elemen pengurusan dan keselamatan."}, {"kind": "p", "text": "SP sokongan 5.1.3: Mematuhi arahan guru semasa melakukan aktiviti Pendidikan Jasmani."}, {"kind": "p", "text": "SK sokongan 5.1: Mematuhi dan mengamalkan elemen pengurusan dan keselamatan."}, {"kind": "p", "text": "SP sokongan 5.1.4: Mengenali dan mematuhi peraturan keselamatan di tempat melakukan aktiviti Pendidikan Jasmani."}, {"kind": "p", "text": "Penyesuaian di darat sahaja; amali air belum dilaksanakan."}, {"kind": "p", "text": "SP sumber yang belum dilaksanakan atau belum lengkap: 1.9.1 — Mematuhi peraturan di kolam renang. Tiada kolam; pengenalan di darat bukan amali air."}, {"kind": "p", "text": "SP sumber yang belum dilaksanakan atau belum lengkap: 1.9.2 — Melakukan kemahiran masuk ke dalam air, berdiri, berjalan, bobbing, mengapung tiarap, meluncur (glide) dan berdiri dalam air dari posisi apungan tiarap. Tiada kolam; pengenalan di darat bukan amali air."}, {"kind": "p", "text": "SP sumber yang belum dilaksanakan atau belum lengkap: 2.8.3 — Mengenal pasti kemahiran apungan tiarap yang betul. Tiada kolam; pengenalan di darat bukan amali air."}, {"kind": "p", "text": "SP sumber yang belum dilaksanakan atau belum lengkap: 2.8.4 — Mengenal pasti kemahiran luncur yang betul. Tiada kolam; pengenalan di darat bukan amali air."}, {"kind": "label", "text": "Objektif"}, {"kind": "p", "text": "Murid dapat mengenal cara pernafasan dalam kemahiran bobbing melalui penerangan guru."}, {"kind": "label", "text": "Kriteria kejayaan"}, {"kind": "p", "text": "1. Menyatakan menarik nafas ketika kepala di atas permukaan air dan menghembus ketika di dalam air berdasarkan teks."}, {"kind": "p", "text": "2. Menyebut satu peraturan pengawasan sebelum melakukan aktiviti air sebenar."}, {"kind": "p", "text": "Pengetahuan sedia ada: Murid telah mengenal peraturan menunggu guru dan berjalan tanpa menolak; kemahiran berenang tidak diandaikan."}, {"kind": "h2", "text": "C. Alatan, persediaan dan keselamatan"}, {"kind": "label", "text": "Kon penanda"}, {"kind": "p", "text": "Keperluan: Enam kon di luar kawasan berjalan."}, {"kind": "p", "text": "Kegunaan: Empat menandakan kawasan larangan rekaan; dua menandakan tempat mula dan tempat berkumpul dengan guru."}, {"kind": "label", "text": "Papan dan buku teks BT38–39"}, {"kind": "p", "text": "Keperluan: Satu paparan guru."}, {"kind": "p", "text": "Kegunaan: Menerangkan peraturan kolam dan teks bobbing; bukan menggantikan kemudahan air."}, {"kind": "label", "text": "Air minuman sendiri"}, {"kind": "p", "text": "Keperluan: Satu bekas setiap murid mengikut keperluan."}, {"kind": "p", "text": "Kegunaan: Minum ketika rehat; tiada bekas air untuk rendaman muka."}, {"kind": "label", "text": "Persediaan guru"}, {"kind": "p", "text": "1. Semua aktiviti di tempat kering dan rata, jauh daripada kolam, sungai atau longkang. Kon hanya penanda latihan."}, {"kind": "p", "text": "2. Tulis tiga pesanan: tunggu arahan guru, berjalan tanpa menolak, maklumkan jika tidak sihat. Peraturan ini contoh guru berpandukan keselamatan, bukan jawapan gambar BT38."}, {"kind": "p", "text": "3. Jangan menyediakan kolam sementara atau air untuk mencuba bobbing. Tiada lompat masuk, apungan atau luncuran di lantai."}, {"kind": "label", "text": "Susunan dan giliran murid"}, {"kind": "p", "text": "1. Murid berpasangan di ruang kering. Guru memberi penerangan kepada semua sebelum setiap pasangan bergerak perlahan dalam laluan lebar."}, {"kind": "p", "text": "2. Pasangan berhenti di tanda kon untuk menjawab, kemudian kembali melalui sisi. Laluan tidak bersilang dan tidak mengelilingi air sebenar."}, {"kind": "p", "text": "3. Semua pernafasan kekal biasa. Tiada tunduk muka ke bekas air, mencangkung berulang untuk meniru bobbing atau pertandingan menahan nafas."}, {"kind": "label", "text": "Petunjuk pergerakan"}, {"kind": "p", "text": "1. BT39 menerangkan bobbing sebagai tenggelam timbul di air: menarik nafas ketika kepala di permukaan dan menghembus melalui hidung atau mulut ketika di dalam air."}, {"kind": "p", "text": "2. Dalam kelas, murid hanya mengenal urutan melalui penerangan. Mereka tidak mencuba pernafasan dalam air."}, {"kind": "p", "text": "3. Apung tiarap dan luncur ialah nama kemahiran lain pada BT39. Bentuk tekniknya belum disahkan melalui gambar; pengenalan nama bukan penguasaan SP2.8.3 atau SP2.8.4."}, {"kind": "p", "text": "4. Hanya guru atau pengajar yang sesuai di tempat air selamat boleh membimbing amali sebenar. Latihan darat bukan bukti murid sudah selamat berenang."}, {"kind": "label", "text": "BBM"}, {"kind": "p", "text": "1. Kon penanda — Enam kon di luar kawasan berjalan."}, {"kind": "p", "text": "2. Papan dan buku teks BT38–39 — Satu paparan guru."}, {"kind": "p", "text": "3. Air minuman sendiri — Satu bekas setiap murid mengikut keperluan."}, {"kind": "p", "text": "4. Buku teks dan senarai semak pemerhatian guru."}, {"kind": "p", "text": "PAK-21: Murid berlatih berpasangan atau dalam kumpulan kecil. Setiap murid mendapat giliran sendiri. Rakan memberi teguran ringkas secara sopan tanpa mengambil alih tugasan."}, {"kind": "p", "text": "Nilai: Kerjasama, disiplin dan menjaga keselamatan rakan."}, {"kind": "label", "text": "Keselamatan"}, {"kind": "p", "text": "1. Guru memeriksa pakaian, tali kasut, keadaan murid, permukaan tempat aktiviti dan alatan sebelum bermula."}, {"kind": "p", "text": "2. Murid berhenti dan memberitahu guru jika sakit, pening atau sukar bernafas. Rehat dan minum dibenarkan mengikut keperluan."}, {"kind": "p", "text": "3. Guru memastikan semua murid berada dalam pandangannya. Murid tidak menolak, menarik atau menghalang laluan rakan."}, {"kind": "p", "text": "4. Latihan di darat sahaja. Tiada rendaman muka, tahan nafas, pertandingan hembusan atau pernafasan laju."}, {"kind": "p", "text": "5. Jangan membawa murid ke tepi air untuk melengkapkan aktiviti. Tiada kolam sesuai; amali SP1.9.1 dan SP1.9.2 belum dilaksanakan."}, {"kind": "p", "text": "6. Apungan tiarap dan luncuran disebut sebagai nama kemahiran sahaja apabila gambar tidak disahkan; SP2.8.3 dan SP2.8.4 belum lengkap."}, {"kind": "p", "text": "7. Jika seseorang berada dalam bahaya di air, panggil orang dewasa atau petugas dari tempat selamat. Murid tidak melompat masuk, menarik mangsa atau berlatih menyelamat."}, {"kind": "p", "text": "Jika cuaca atau ruang tidak sesuai: Jika hujan, kilat, panas melampau atau lantai licin, guru menggunakan ruang berbumbung yang selamat. Jika ruang tidak sesuai, aktiviti berisiko ditangguhkan dan perkara yang belum dilaksanakan dicatat."}, {"kind": "h2", "text": "D. Langkah PdP"}, {"kind": "h3", "text": "Langkah 1: Persediaan murid dan alatan — 2 minit"}, {"kind": "p", "text": "Minit 0 hingga 2."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru memeriksa pakaian, tali kasut, keadaan murid dan alatan."}, {"kind": "p", "text": "2. Guru menerangkan tempat mula, laluan aktiviti dan arahan berhenti."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid memberitahu guru jika tidak sihat."}, {"kind": "p", "text": "2. Murid mengambil tempat yang ditetapkan dan mendengar arahan."}, {"kind": "p", "text": "Semakan: Semua murid tahu tempat menunggu dan boleh berhenti apabila diarahkan."}, {"kind": "p", "text": "Alatan: Kon penanda Papan dan buku teks BT38–39 Air minuman sendiri"}, {"kind": "h3", "text": "Langkah 2: Pemanasan badan — 4 minit"}, {"kind": "p", "text": "Minit 2 hingga 6."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru memimpin berjalan setempat dan langkah ke sisi selama dua minit."}, {"kind": "p", "text": "2. Guru membimbing gerakan ringan bahu, tangan, buku lali dan lutut selama dua minit."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid bergerak dalam ruang sendiri tanpa bersentuh."}, {"kind": "p", "text": "2. Murid bernafas seperti biasa dan berehat jika perlu."}, {"kind": "p", "text": "Semakan: Murid bersedia untuk aktiviti tanpa terlalu penat."}, {"kind": "p", "text": "Alatan: Ruang lapang Kon penanda"}, {"kind": "h3", "text": "Langkah 3: Baca penerangan bobbing — 4 minit"}, {"kind": "p", "text": "Minit 6 hingga 10."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru membaca maklumat BT39 dengan ayat mudah."}, {"kind": "p", "text": "2. Guru menggunakan gerak tangan sendiri untuk menunjukkan kepala di atas dan di dalam air, tanpa meminta murid melakukan rendaman."}, {"kind": "p", "text": "3. Guru mengulang peraturan tunggu pengawasan dan tidak mencuba sendiri."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid mendengar dua keadaan kepala."}, {"kind": "p", "text": "2. Murid menyebut tarik di atas, hembus di dalam dengan pernafasan biasa."}, {"kind": "p", "text": "Semakan: Urutan dikenal secara lisan sahaja."}, {"kind": "p", "text": "Alatan: BT39 Papan"}, {"kind": "h3", "text": "Langkah 4: Berjalan, berhenti dan jawab — 9 minit"}, {"kind": "p", "text": "Minit 10 hingga 19."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru memberi giliran pasangan berjalan pendek ke tanda kon, berhenti dan menjawab satu soalan."}, {"kind": "p", "text": "2. Guru menyoal kedua-dua murid tentang bila menarik dan menghembus nafas."}, {"kind": "p", "text": "3. Guru menyusun giliran supaya tiada larian, lorong sesak atau menunggu tanpa pengawasan."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid berjalan tenang dan berhenti sebelum menjawab."}, {"kind": "p", "text": "2. Setiap murid menyatakan kedua-dua bahagian urutan bobbing."}, {"kind": "p", "text": "3. Murid kembali ke tempat sendiri melalui sisi dan memberi giliran pasangan lain."}, {"kind": "p", "text": "Semakan: Pengetahuan individu dinilai; berjalan bukan amali bobbing."}, {"kind": "p", "text": "Alatan: Kon Papan"}, {"kind": "h3", "text": "Langkah 5: Betulkan urutan contoh — 7 minit"}, {"kind": "p", "text": "Minit 19 hingga 26."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru menyebut contoh salah: menarik nafas ketika kepala di dalam air."}, {"kind": "p", "text": "2. Guru meminta setiap pasangan membetulkan contoh, kemudian berjalan perlahan semula dalam ruang sendiri."}, {"kind": "p", "text": "3. Guru menanyakan peraturan jika pengajar belum bersedia dan memberi rehat/minum."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid membetulkan jawapan kepada menarik di atas permukaan air."}, {"kind": "p", "text": "2. Murid menyebut menghembus ketika di dalam air mengikut teks."}, {"kind": "p", "text": "3. Murid memilih menunggu pengajar, bukan mencuba di rumah atau bekas air."}, {"kind": "p", "text": "Semakan: Dua bahagian bobbing dan satu pesanan pengawasan disebut."}, {"kind": "p", "text": "Alatan: Papan Kon Air sendiri"}, {"kind": "h3", "text": "Langkah 6: Penyejukan badan dan penutup — 4 minit"}, {"kind": "p", "text": "Minit 26 hingga 30."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru memimpin berjalan perlahan selama satu minit dan regangan lembut tangan serta kaki selama dua minit."}, {"kind": "p", "text": "2. Guru memberi masa minum dan menanyakan satu perkara yang dipelajari."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid meregang mengikut keselesaan tanpa sentapan."}, {"kind": "p", "text": "2. Murid memberitahu guru jika masih tidak selesa dan membantu mengemas alatan ringan selepas arahan."}, {"kind": "p", "text": "Semakan: Tiada latihan kuat selepas penyejukan. Guru mencatat perkara yang perlu disusuli."}, {"kind": "p", "text": "Alatan: Air minuman Ruang rehat"}, {"kind": "p", "text": "Jumlah masa: 30 minit."}, {"kind": "label", "text": "Contoh arahan kelas"}, {"kind": "p", "text": "Guru: Menurut teks, bilakah kepala berada di atas air: ketika menarik atau menghembus nafas?"}, {"kind": "p", "text": "Murid: Murid menjawab menarik nafas dan terus bernafas seperti biasa di darat."}, {"kind": "p", "text": "Semakan guru: Guru menilai jawapan, bukan mengira tempoh hembusan atau tahan nafas."}, {"kind": "h2", "text": "E. PdP terbeza", "anchor": "pdp-PJ1-2026B-2S-W30-S2"}, {"kind": "p", "text": "Tugasan bersama: Murid dapat mengenal cara pernafasan dalam kemahiran bobbing melalui penerangan guru."}, {"kind": "p", "text": "Bimbingan ini diberikan dalam waktu latihan dan aplikasi. Murid tidak perlu menjalani tiga kumpulan bantuan sebagai aktiviti tambahan."}, {"kind": "label", "text": "Bimbingan guru"}, {"kind": "p", "text": "1. Bacakan kata bantu kepada Peneroka."}, {"kind": "p", "text": "2. Dengar kedua-dua jawapan Pembina."}, {"kind": "p", "text": "3. Semak pembetulan Pencabar tanpa menambah latihan pernafasan."}, {"kind": "p", "text": "Semakan individu: Menyatakan menarik nafas ketika kepala di atas permukaan air dan menghembus ketika di dalam air berdasarkan teks."}, {"kind": "p", "text": "Bantuan diteruskan selagi diperlukan. Murid tidak dipaksa menambah kelajuan, jarak, beban atau ulangan untuk menunjukkan kemajuan."}, {"kind": "h3", "text": "Peneroka"}, {"kind": "p", "text": "Guru membimbing satu langkah pada satu masa."}, {"kind": "p", "text": "Tugasan: Mengenal dua keadaan pernafasan bobbing dengan kata bantu."}, {"kind": "label", "text": "Alatan"}, {"kind": "p", "text": "1. BT39"}, {"kind": "p", "text": "2. Papan"}, {"kind": "p", "text": "3. Kon"}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru memberi pilihan tarik atau hembus satu soalan pada satu masa."}, {"kind": "p", "text": "2. Gunakan gerak tangan guru sahaja sebagai bantuan urutan; jangan arah murid tahan nafas."}, {"kind": "label", "text": "Langkah murid"}, {"kind": "p", "text": "1. Dengar penerangan kepala di atas air."}, {"kind": "p", "text": "2. Sebut menarik nafas di atas dan menghembus di dalam air."}, {"kind": "p", "text": "3. Berjalan perlahan dan berhenti sebelum menjawab semula."}, {"kind": "p", "text": "4. Sebut tunggu guru sebelum sebarang amali air."}, {"kind": "p", "text": "Contoh guru: Di atas air, tarik atau hembus?"}, {"kind": "p", "text": "Contoh respons murid: Tarik nafas."}, {"kind": "p", "text": "Hasil individu: Dua jawapan urutan serta satu peraturan pengawasan."}, {"kind": "p", "text": "Kriteria: Jawapan tepat dengan bantuan; tiada lakuan air atau TP akuatik direkod."}, {"kind": "p", "text": "Susulan: Ulang penerangan menggunakan dua kata sahaja."}, {"kind": "h3", "text": "Pembina"}, {"kind": "p", "text": "Murid berlatih berpasangan dan melakukan sendiri."}, {"kind": "p", "text": "Tugasan: Menerangkan urutan bobbing sambil mengikuti giliran berjalan selamat."}, {"kind": "label", "text": "Alatan"}, {"kind": "p", "text": "1. Papan"}, {"kind": "p", "text": "2. Kon"}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Pastikan murid berhenti sebelum menjawab."}, {"kind": "p", "text": "2. Tanya kedua-dua keadaan kepada setiap murid, bukan satu kepada seorang."}, {"kind": "label", "text": "Langkah murid"}, {"kind": "p", "text": "1. Dengar teks dan kenal dua keadaan kepala."}, {"kind": "p", "text": "2. Jalan ke tanda dan berhenti."}, {"kind": "p", "text": "3. Terangkan tarik ketika di atas air dan hembus ketika di dalam air."}, {"kind": "p", "text": "4. Kembali melalui sisi dan sebut tunggu pengawasan."}, {"kind": "p", "text": "Contoh guru: Adakah berjalan ini sudah dikira bobbing?"}, {"kind": "p", "text": "Contoh respons murid: Tidak, bobbing sebenar dilakukan dalam air dengan bimbingan."}, {"kind": "p", "text": "Hasil individu: Urutan lisan individu dan giliran darat selamat."}, {"kind": "p", "text": "Kriteria: Dua bahagian dijawab sendiri; tidak mendakwa boleh bobbing sebenar."}, {"kind": "p", "text": "Susulan: Baiki bahagian yang tertukar sahaja."}, {"kind": "h3", "text": "Pencabar"}, {"kind": "p", "text": "Murid memperkemas satu perkara dalam kemahiran yang sama."}, {"kind": "p", "text": "Tugasan: Membetulkan satu urutan salah dan menerangkan batas latihan."}, {"kind": "label", "text": "Alatan"}, {"kind": "p", "text": "1. BT39"}, {"kind": "p", "text": "2. Papan"}, {"kind": "p", "text": "3. Kon"}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Beri satu contoh salah yang pendek."}, {"kind": "p", "text": "2. Terima jawapan mudah tanpa meminta hembusan panjang atau istilah sukar."}, {"kind": "label", "text": "Langkah murid"}, {"kind": "p", "text": "1. Berjalan dan berhenti di tempat yang ditanda."}, {"kind": "p", "text": "2. Betulkan contoh menarik nafas ketika kepala di dalam air."}, {"kind": "p", "text": "3. Sebut semula dua bahagian urutan bobbing."}, {"kind": "p", "text": "4. Jelaskan bahawa amali air memerlukan guru dan kolam yang sesuai."}, {"kind": "p", "text": "Contoh guru: Bolehkah mencuba dalam baldi di rumah?"}, {"kind": "p", "text": "Contoh respons murid: Tidak. Tunggu pengajar di kolam yang sesuai."}, {"kind": "p", "text": "Hasil individu: Urutan betul dan satu pembetulan individu."}, {"kind": "p", "text": "Kriteria: Penjelasan mengikut teks dan tidak mendorong latihan sendiri di air."}, {"kind": "p", "text": "Susulan: Kongsi pesanan menunggu pengawasan kepada pasangan."}, {"kind": "h2", "text": "F. Pentaksiran Bilik Darjah"}, {"kind": "h3", "text": "PBD utama — SP 2.8.2"}, {"kind": "p", "text": "Kaedah: Soal jawab individu berdasarkan teks BT39."}, {"kind": "p", "text": "Bukti: Dua jawapan tentang menarik nafas ketika kepala di atas air dan menghembus ketika di dalam air."}, {"kind": "p", "text": "Kriteria: Kedua-duanya dikenal dengan betul; bantuan dicatat. Ini pengetahuan sahaja, bukan amali bobbing."}, {"kind": "p", "text": "Rekod: Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP."}, {"kind": "label", "text": "Senarai semak"}, {"kind": "p", "text": "1. Tarik di atas: ____"}, {"kind": "p", "text": "2. Hembus di dalam: ____"}, {"kind": "p", "text": "3. Bantuan / belum disemak: ____"}, {"kind": "h3", "text": "PBD sokongan — SP 2.8.1"}, {"kind": "p", "text": "Kaedah: Soal jawab individu selepas mengenal urutan bobbing dan ketika semua murid berhenti."}, {"kind": "p", "text": "Bukti: Murid menyebut menunggu guru atau pengajar serta pengawasan yang sesuai sebelum sebarang amali air sebenar."}, {"kind": "p", "text": "Kriteria: Murid mengenal satu peraturan pengawasan dan tidak mencuba sendiri. Ini pengetahuan peraturan, bukan pematuhan sebenar di kolam."}, {"kind": "p", "text": "Rekod: Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP."}, {"kind": "label", "text": "Senarai semak"}, {"kind": "p", "text": "1. Peraturan pengawasan yang disebut: ____"}, {"kind": "p", "text": "2. Menunggu, bukan mencuba sendiri: ____"}, {"kind": "p", "text": "3. Bantuan / belum disemak: ____"}, {"kind": "h3", "text": "PBD sokongan — SP 5.1.3"}, {"kind": "p", "text": "Kaedah: Pemerhatian semasa berjalan dan berhenti."}, {"kind": "p", "text": "Bukti: Respons terhadap arahan mula, berhenti dan berkumpul."}, {"kind": "p", "text": "Kriteria: Murid mematuhi arahan di darat; tidak dianggap kemahiran dalam air."}, {"kind": "p", "text": "Rekod: Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP."}, {"kind": "label", "text": "Senarai semak"}, {"kind": "p", "text": "1. Tunggu arahan: ____"}, {"kind": "p", "text": "2. Berhenti: ____"}, {"kind": "p", "text": "3. Bimbingan: ____"}, {"kind": "h3", "text": "PBD sokongan — SP 5.1.4"}, {"kind": "p", "text": "Kaedah: Pemerhatian laluan kering dan soal jawab."}, {"kind": "p", "text": "Bukti: Murid kekal di luar kawasan larangan rekaan dan tidak menolak."}, {"kind": "p", "text": "Kriteria: Mengenal sempadan dan peraturan tempat latihan."}, {"kind": "p", "text": "Rekod: Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP."}, {"kind": "label", "text": "Senarai semak"}, {"kind": "p", "text": "1. Sempadan dipatuhi: ____"}, {"kind": "p", "text": "2. Tidak menolak: ____"}, {"kind": "p", "text": "3. Belum diperhatikan: ____"}, {"kind": "h2", "text": "G. Refleksi dan intervensi"}, {"kind": "p", "text": "Murid yang telah diperhatikan: ____ daripada ____. Kemahiran yang dikuasai: __________. Murid yang masih memerlukan bimbingan atau belum mendapat giliran: __________."}, {"kind": "label", "text": "Intervensi"}, {"kind": "p", "text": "1. Ulang urutan melalui kata dan gerak tangan guru."}, {"kind": "p", "text": "2. Amali air serta teknik apungan/luncur kekal belum dilaksanakan atau belum lengkap sehingga kemudahan dan bukti yang sesuai diperoleh."}]'::jsonb,'{"source_hold": "", "adaptation_note": "Tiada kolam sesuai. Dua sesi di darat dibenarkan guru. Pengetahuan keselamatan dan bobbing daripada teks diajar, tetapi latihan darat tidak memenuhi amali di kolam SP1.9.1/1.9.2. Apungan tiarap dan luncur hanya pengenalan nama/konsep jika gambar belum disahkan; SP2.8.3/2.8.4 belum lengkap. Tiada kolam sementara, rendaman muka, tahan nafas, luncur di lantai atau menyelamat secara fizikal.", "source_images_verified": true, "audio_verified": false, "ba_verified": false, "classroom_trial_performed": false}'::jsonb),
  ('PJ1-2026B-2S-W31-S1','pj',1,2026,31,1,30,'1.10.1',array[42]::int[],'74688c920012c3f4e9802f57882fde1689fde4d932860639644a267b830695c8','4f827f0237877582539b31d7d29426f637ea205c5e69f5db51d04254f6492d42','715d2dd93e616381f7de4fb5e317e008bae7007088b12831c3d9d17a2be5d6d7','ACCEPTED_FROM_DOWNLOADED_CATATAN',false,'{"id": "PJ1-2026B-2S-W31-S1", "subject": "Pendidikan Jasmani", "year": 1, "week": 31, "session": 1, "revision": "PJ1-30MIN-REVIEW-R1", "date": "", "teaching_time": "", "minutes": 30, "sessions_per_week": 2, "weekly_minutes": 60, "title": "Santai Petang", "source_title": "Santai Petang", "unit": "Unit 6: Mari Bersantai", "source_row_id": "PJ1-RPT2026-T10-R5", "source_row_literal": ["31\n\nKump A: 06.09.2026-10.09.2026\n\nKump B:\n07.09.2026-11.09.2026", "6: MARI BERSANTAI\nSANTAI PETANG", "1.10 Melakukan aktiviti rekreasi dan kesenggangan\n2.9 Mengaplikasi strategi dan idea kreatif dalam aktiviti rekreasi dan   kesenggangan\n5.4 Membentuk kumpulan dan bekerjasama dalam kumpulan semasa melakukan aktiviti.", "1.10.1 Menggunakan kemahiran lokomotor dan manipulasi semasa melakukan permainan tradisional seperti Datuk Harimau dan Congkak.\n\n2.9.1 Mengenal pasti cara bermain permainan tradisional.\n\n5.4.1 Mempamerkan aktiviti secara berpasangan. \n5.4.2 Mempamerkan rasa seronok semasa melakukan aktiviti dalam kumpulan.", "Pemerhatian /\nPentaksiran \n\nPERMAINAN:\nCongkak\nDatuk harimau\n\nEMK: \nKreativiti & Inovasi\nBT m/s 41-42"], "rpt_original_page_literal": "41-42", "source_pages": [42], "source_pdf_pages": [50], "rpt_book_pages": "42", "main_standard_key": "1.10.1", "sk_code": "1.10", "sk_text": "Melakukan aktiviti rekreasi dan kesenggangan.", "sp_code": "1.10.1", "sp_text": "Menggunakan kemahiran lokomotor dan manipulasi semasa melakukan permainan tradisional seperti Datuk Harimau dan Congkak.", "complementary_standards": [{"standard_key": "2.9.1", "sp_code": "2.9.1", "sp_text": "Mengenal pasti cara bermain permainan tradisional.", "sk_code": "2.9", "sk_text": "Mengaplikasi strategi dan idea kreatif dalam aktiviti rekreasi dan kesenggangan.", "domain": "kognitif", "source_label": ""}, {"standard_key": "5.4.1", "sp_code": "5.4.1", "sp_text": "Mempamerkan aktiviti secara berpasangan.", "sk_code": "5.4", "sk_text": "Membentuk kumpulan dan bekerjasama dalam kumpulan semasa melakukan aktiviti.", "domain": "afektif", "source_label": ""}, {"standard_key": "5.4.2", "sp_code": "5.4.2", "sp_text": "Mempamerkan rasa seronok semasa melakukan aktiviti dalam kumpulan.", "sk_code": "5.4", "sk_text": "Membentuk kumpulan dan bekerjasama dalam kumpulan semasa melakukan aktiviti.", "domain": "afektif", "source_label": ""}], "source_task": "Datuk Harimau tanpa sentuhan dan asas congkak", "authoring_focus": "Datuk Harimau tanpa sentuhan dan asas congkak", "source_hold": "Teks RPT, DSKP dan buku dibaca. Semakan imej guling BT35 dan kod DSKP hlm70 terhalang ralat402; OCR dan teks salinan menyokong kod berulang, bukan kelulusan visual. Guru perlu menilai postur, alat dan kesediaan setiap murid.", "practical_required": true, "warmup_required": true, "cooldown_required": true, "facility_replacement": false, "facility_replacement_note": "", "source_subset_focus": false, "source_subset_note": "", "adaptation_note": "BT42 menamakan Datuk Harimau dan Congkak tanpa peraturan lengkap dalam teks. Kedua-dua permainan digunakan setiap sesi untuk lokomotor dan manipulasi. Versi mini Datuk Harimau tanpa sentuhan dan congkak tiga buah setiap rumah anak ialah latihan guru, bukan peraturan pertandingan penuh. Papan congkak dan buah sebenar yang selamat digunakan, bukan permainan kad.", "privacy_adaptation": false, "privacy_note": "", "held_standards": [], "source_code_conflict": false, "source_code_note": "", "unperformed_literal_elements": [], "source_mapping_review": "20 RPH, dua sesi30minit seminggu dibenarkan guru. S1/S2 ialah cadangan pecahan RPT mingguan, bukan nombor sesi yang tercetak dalam RPT.", "routine_book_pages": [46, 47], "active": false, "production_write_performed": false, "presentation_review": "PENDING_TEACHER_REVIEW", "safety": ["Guru memeriksa pakaian, tali kasut, keadaan murid, permukaan tempat aktiviti dan alatan sebelum bermula.", "Murid berhenti dan memberitahu guru jika sakit, pening atau sukar bernafas. Rehat dan minum dibenarkan mengikut keperluan.", "Guru memastikan semua murid berada dalam pandangannya. Murid tidak menolak, menarik atau menghalang laluan rakan.", "Datuk Harimau ialah adaptasi guru tanpa sentuhan dan tanpa kejar-mengejar. Guru kekal di belakang kon; tiada menangkap, menolak, menyekat, menyingkir atau memaksa murid berlari.", "Selepas Waktu makan, murid berpusing dengan tenang lalu berjalan pantas dalam lorong sendiri. Murid berhenti stabil di rumah selamat. Jangan mengundur laju atau memotong lorong.", "Hanya satu kumpulan kecil aktif. Kumpulan menunggu berada di luar laluan dan tetap dalam pandangan guru. Hentikan pusingan jika laluan terganggu.", "Buah congkak tidak dimasukkan ke mulut, hidung atau telinga dan tidak dibaling. Tangan berada rendah di atas papan. Buah yang jatuh dikutip selepas semua tangan berhenti.", "Guru memantau risiko tercekik. Jika buah tidak sesuai atau murid masih memasukkan benda ke mulut, tangguhkan amali Congkak murid berkenaan sehingga alat dan pengawasan selamat tersedia; catat bahagian belum dilaksanakan."], "weather_plan": "Jika hujan, kilat, panas melampau atau lantai licin, guru menggunakan ruang berbumbung yang selamat. Jika ruang tidak sesuai, aktiviti berisiko ditangguhkan dan perkara yang belum dilaksanakan dicatat.", "reflection": "Murid yang telah diperhatikan: ____ daripada ____. Kemahiran yang dikuasai: __________. Murid yang masih memerlukan bimbingan atau belum mendapat giliran: __________.", "activity_name": "Kenal rumah selamat dan genggam buah Congkak", "objective": "Murid dapat menggunakan langkah terkawal dalam Datuk Harimau dan menggenggam serta menabur buah Congkak satu demi satu dengan selamat.", "success_criteria": ["Bergerak dan kembali ke rumah selamat dalam Datuk Harimau serta menabur satu genggaman Congkak mengikut arah.", "Menyebut satu cara bermain Datuk Harimau dan satu cara bermain Congkak.", "Mengambil giliran sendiri bersama pasangan dalam kedua-dua permainan."], "prior_knowledge": "Murid pernah berjalan mengikut arahan dan memindahkan benda kecil. Guru menyemak pengalaman bermain tanpa menganggap semua murid sudah tahu peraturan.", "equipment": [{"item": "Kon penanda", "quantity": "15 kon: 12 bagi enam lorong, satu untuk guru dan dua untuk tempat menunggu.", "use": "Menandakan mula, hujung dan ruang menunggu dari sisi laluan; tiada kon di tempat kaki melangkah."}, {"item": "Papan congkak sebenar", "quantity": "Satu papan bagi setiap pasangan; tujuh rumah anak pada setiap sisi dan satu rumah ibu pada setiap hujung.", "use": "Setiap murid menggenggam dan menabur buah pada gilirannya sendiri."}, {"item": "Buah congkak licin bukan kaca dan bekas simpanan", "quantity": "42 buah bagi setiap papan, tiga bagi setiap rumah anak; satu bekas bagi setiap papan.", "use": "Buah sesuai untuk umur murid, boleh digenggam dan tidak tajam; rumah ibu kosong ketika mula."}, {"item": "Air minuman sendiri dan jam guru", "quantity": "Satu botol bagi setiap murid dan satu jam guru.", "use": "Rehat, minum dan mengurus pertukaran kumpulan."}], "preparation": ["Guru menyusun enam lorong selari di permukaan rata yang kering. Dua kon diletakkan di sisi setiap lorong untuk menunjukkan rumah selamat di titik mula dan had hujung.", "Jarak setiap lorong cukup untuk tiga langkah kecil dengan ruang berhenti. Jarak antara murid membolehkan tangan dibuka tanpa menyentuh rakan. Kurangkan bilangan lorong aktif jika ruang sempit.", "Guru berdiri tetap di belakang konnya, jauh di hadapan had hujung murid. Dua kon lain menandakan tempat menunggu di luar laluan dan dalam pandangan guru.", "Papan congkak diletakkan stabil di kawasan teduh di luar lorong. Isi tiga buah pada setiap rumah anak, jumlah 42 buah bagi satu papan. Kosongkan kedua-dua rumah ibu.", "Guru mengira dan memeriksa buah sebelum serta selepas aktiviti. Buah yang terlalu kecil, retak atau tidak sesuai tidak digunakan."], "organisation": ["Kekalkan pasangan. Sehingga tiga pasangan, paling banyak enam murid, bermain Datuk Harimau serentak dalam lorong sendiri. Setiap pasangan berada dalam dua lorong bersebelahan, bukan berpegangan tangan.", "Kumpulan lain duduk tenang di tempat menunggu dan melihat. Guru menamatkan pusingan dahulu sebelum memanggil kumpulan seterusnya. Semua kumpulan mendapat pusingan sebelum sebarang ulangan.", "Semasa Congkak, semua pasangan bermain pada papan masing-masing. Dua atau tiga pasangan duduk berdekatan sebagai kumpulan kecil tanpa berkongsi giliran pemain.", "Guru menetapkan siapa bermula pada setiap papan. Pasangan berselang giliran satu genggaman; setiap murid melakukan sendiri, bukan seorang wakil pasangan.", "Murid boleh berehat atau minum selepas memberitahu guru. Guru merekod bahagian yang belum dicuba dan mengatur susulan, bukan mengisi pencapaian bagi murid yang hanya memerhati."], "movement_cues": ["Datuk Harimau: tanya Pukul berapa, Datuk Harimau? Ambil langkah kecil mengikut jawapan guru antara satu hingga tiga. Berhenti sebelum had hujung.", "Apabila guru menyebut Waktu makan, pusing dahulu. Pandang rumah selamat dan berjalan pantas pulang dalam lorong sendiri. Berhenti tanpa menyentuh rakan.", "Congkak: genggam semua buah daripada sebuah rumah anak berisi pada sisi sendiri. Tapak tangan menadah dan tangan dekat dengan papan.", "Mula menabur di rumah anak seterusnya dari kanan ke kiri pada sisi sendiri. Lepaskan satu buah bagi setiap rumah. Masukkan buah ke rumah ibu sendiri jika dilalui, kemudian teruskan di sisi lawan; langkau rumah ibu lawan.", "Dalam latihan mini ini, selepas buah terakhir dilepaskan, letak tangan di sisi papan dan beri giliran pasangan. Tiada mengambil semula isi rumah terakhir, menangkap buah atau giliran tambahan."], "timing_note": "30 minit merangkumi persediaan, pemanasan, tunjuk cara, Datuk Harimau sembilan minit, Congkak tujuh minit dan penyejukan. Pertukaran, rehat dan minum termasuk dalam masa fasa; ulangan tidak mendahului giliran pertama setiap murid.", "values": "Kerjasama, disiplin dan menjaga keselamatan rakan.", "classroom_example": {"teacher_says": "Dengar Waktu makan sebelum pulang. Di papan, lepaskan satu buah ke satu rumah.", "pupils_do": "Murid berpusing dan pulang mengikut lorong, kemudian menggenggam serta menabur buah Congkak pada giliran sendiri.", "teacher_checks": "Guru menyemak langkah pulang dan pelepasan buah setiap murid, bukan hanya jawapan kumpulan."}, "bbm": ["Kon penanda — 15 kon: 12 bagi enam lorong, satu untuk guru dan dua untuk tempat menunggu.", "Papan congkak sebenar — Satu papan bagi setiap pasangan; tujuh rumah anak pada setiap sisi dan satu rumah ibu pada setiap hujung.", "Buah congkak licin bukan kaca dan bekas simpanan — 42 buah bagi setiap papan, tiga bagi setiap rumah anak; satu bekas bagi setiap papan.", "Air minuman sendiri dan jam guru — Satu botol bagi setiap murid dan satu jam guru.", "Buku teks dan senarai semak pemerhatian guru."], "pak21": "Dalam Datuk Harimau, pasangan bertanya waktu bersama tetapi bergerak dalam lorong berasingan. Dalam Congkak, seorang menabur dan pasangannya melihat arah; kemudian bertukar. Kumpulan kecil memberi pujian ringkas tanpa mengambil alih giliran.", "source_note": "Sumber teks dibaca: RPT PJ1-RPT2026-T10-R5, DSKP PDF72–74 dan BT42/PDF50. BT42 menamakan kedua-dua permainan serta bimbingan guru, bukan peraturan lengkap. Peraturan Congkak DVS halaman dua menyokong arah kanan ke kiri, satu buah setiap rumah serta rumah ibu sendiri. Had satu genggaman, isi tiga buah dan tamat giliran tanpa sambung ialah adaptasi pengenalan guru, bukan peraturan pertandingan penuh. Tiada dakwaan semakan visual dibuat.", "assessment_scope": "PBD merekod langkah Datuk Harimau dan manipulasi Congkak sebenar. Permainan tanpa kejar-mengejar bukan bukti kemahiran mengelak. Congkak mini bukan bukti penguasaan semua peraturan permainan atau penetapan TP secara automatik.", "phases": [{"name": "Persediaan murid dan alatan", "minutes": 2, "teacher": ["Guru memeriksa pakaian, tali kasut, keadaan murid dan alatan.", "Guru menerangkan tempat mula, laluan aktiviti dan arahan berhenti."], "pupils": ["Murid memberitahu guru jika tidak sihat.", "Murid mengambil tempat yang ditetapkan dan mendengar arahan."], "check": "Semua murid tahu tempat menunggu dan boleh berhenti apabila diarahkan.", "resources": ["Kon penanda", "Papan congkak sebenar", "Buah congkak licin bukan kaca dan bekas simpanan", "Air minuman sendiri dan jam guru"]}, {"name": "Pemanasan badan", "minutes": 4, "teacher": ["Guru memimpin berjalan setempat dan langkah ke sisi selama dua minit.", "Guru membimbing gerakan ringan bahu, tangan, buku lali dan lutut selama dua minit."], "pupils": ["Murid bergerak dalam ruang sendiri tanpa bersentuh.", "Murid bernafas seperti biasa dan berehat jika perlu."], "check": "Murid bersedia untuk aktiviti tanpa terlalu penat.", "resources": ["Ruang lapang", "Kon penanda"]}, {"name": "Tunjuk cara kedua-dua permainan", "minutes": 4, "teacher": ["Guru menjelaskan bahawa Datuk Harimau hari ini tidak melibatkan sentuhan atau kejar-mengejar. Guru menunjukkan rumah selamat, satu langkah kecil dan cara berpusing sebelum pulang.", "Guru menunjukkan papan Congkak sebenar: sisi sendiri, tujuh rumah anak dan rumah ibu. Guru menggenggam isi rumah tengah lalu menabur satu demi satu dari kanan ke kiri.", "Guru menunjukkan tempat memasukkan buah ke rumah ibu sendiri dan tempat melangkau rumah ibu lawan. Guru menegaskan bahawa latihan hari ini tamat selepas satu genggaman walau di mana buah terakhir jatuh."], "pupils": ["Murid menunjuk rumah selamat sendiri dan meniru pusingan perlahan di tempat tanpa bersentuh.", "Murid melihat tangan guru, menunjuk sisi papan sendiri dan menyebut Satu buah, satu rumah.", "Pasangan menyebut siapa bermula dan siapa bermain selepas genggaman pertama habis."], "check": "Murid mengenal tempat pulang dan arah taburan; melihat tunjuk cara belum dikira sebagai amali sendiri.", "resources": ["Kon penanda", "Papan congkak sebenar", "Buah congkak"]}, {"name": "Datuk Harimau: pulang dalam lorong sendiri", "minutes": 9, "teacher": ["Guru memanggil kumpulan pertama, paling banyak enam murid. Guru kekal di belakang kon sebagai harimau; setiap murid bermula di rumah selamat sendiri.", "Guru menjawab satu, dua atau tiga selepas soalan Pukul berapa, Datuk Harimau? Satu soalan sahaja bagi satu pusingan. Guru menunggu langkah murid berhenti sebelum menyebut Waktu makan.", "Guru memerhatikan murid berpusing dan berjalan pantas pulang tanpa mengejar sesiapa. Selepas semua berhenti stabil, guru menyebut Berhenti dan membenarkan kumpulan keluar ke sisi yang kosong.", "Guru memanggil kumpulan seterusnya hanya apabila laluan kosong. Guru menyemak setiap nama, memberi satu bantuan jika perlu serta bertanya cara pulang dan perasaan murid. Akhir fasa diperuntukkan untuk minum dan berjalan ke papan."], "pupils": ["Pasangan bertanya waktu bersama. Setiap murid mengambil langkah kecil mengikut bilangan yang disebut guru lalu berhenti dalam lorong sendiri.", "Apabila mendengar Waktu makan, murid berpusing, memandang ke rumah selamat dan berjalan pantas pulang. Murid berhenti tanpa menolak atau memotong rakan.", "Murid menunggu arahan keluar sebelum berjalan ke tempat menunggu. Kumpulan lain duduk tenang dan memberi ruang kepada kumpulan seterusnya.", "Setiap murid menyebut cara pulangnya apabila ditanya. Murid boleh menyatakan rasa seronok atau rasa belum selesa tanpa dipaksa."], "check": "Guru merekod langkah dan kepulangan setiap murid. Semua kumpulan mendapat pusingan dahulu; tiada penyingkiran, perlumbaan atau bukti mengelak direka.", "resources": ["15 kon penanda", "Jam guru", "Air minuman"]}, {"name": "Congkak: genggam dan tabur bergilir", "minutes": 7, "teacher": ["Guru memastikan papan setiap pasangan bermula dengan tiga buah pada setiap rumah anak, 42 buah semuanya dan rumah ibu kosong. Guru menetapkan pemain pertama; semua pasangan boleh berlatih serentak.", "Guru membimbing setiap murid mengambil semua buah dari rumah tengah berisi pada sisi sendiri. Murid menabur bermula di rumah seterusnya, dari kanan ke kiri, satu buah setiap rumah. Jika melalui rumah ibu sendiri, isikan satu; teruskan di sisi lawan dan langkau rumah ibu lawan.", "Guru menetapkan had satu genggaman sahaja. Buah terakhir menamatkan giliran, sama ada jatuh di rumah berisi, rumah kosong atau rumah ibu sendiri. Jangan kutip isi rumah terakhir, menangkap buah atau mendapat giliran tambahan; pasangan bermain selepas itu.", "Jika rumah dipilih kosong, guru meminta murid memilih rumah berisi di sisi sendiri; jangan mengambil genggaman kosong atau buah rakan. Selepas kedua-dua murid selesai, pasangan menyusun semula tiga buah setiap rumah anak dan mengosongkan rumah ibu. Pemain kedua tadi bermula pusingan berikutnya.", "Guru melihat tangan kedua-dua murid pada giliran masing-masing dan menyoal satu cara bermain. Pada akhir masa, jangan mula giliran baharu; habiskan genggaman yang sedang ditabur dengan tenang, kemudian simpan buah dalam bekas. Giliran belum siap dicatat."], "pupils": ["Murid pertama menggenggam isi rumah tengah pada sisi sendiri dengan tapak tangan menadah. Pasangan melihat arah tanpa menyentuh buah pemain.", "Murid menabur satu buah ke satu rumah mengikut arah yang ditunjukkan. Selepas buah terakhir, murid meletakkan tangan di sisi papan dan menyebut Giliran awak.", "Murid kedua melakukan genggaman dan taburan sendiri. Selepas kedua-duanya selesai, pasangan menyusun semula isi papan dan menukar pemain yang bermula.", "Setiap murid menyebut cara menabur dan memberi respons tentang bermain bersama rakan. Buah yang jatuh dikutip hanya selepas kedua-dua tangan berhenti."], "check": "Bukti setiap murid meliputi genggaman, arah dan pelepasan buah, bersama bukti Datuk Harimau tadi. Nama atau pemerhatian terhadap rakan sahaja tidak mencukupi.", "resources": ["Papan congkak bagi setiap pasangan", "42 buah congkak bagi setiap papan", "Bekas simpanan"]}, {"name": "Penyejukan badan dan penutup", "minutes": 4, "teacher": ["Guru memimpin berjalan perlahan selama satu minit dan regangan lembut tangan serta kaki selama dua minit.", "Guru memberi masa minum dan menanyakan satu perkara yang dipelajari."], "pupils": ["Murid meregang mengikut keselesaan tanpa sentapan.", "Murid memberitahu guru jika masih tidak selesa dan membantu mengemas alatan ringan selepas arahan."], "check": "Tiada latihan kuat selepas penyejukan. Guru mencatat perkara yang perlu disusuli.", "resources": ["Air minuman", "Ruang rehat"]}], "differentiation": {"support": {"label": "Peneroka", "support_description": "Guru membimbing satu langkah pada satu masa.", "task": "Pulang dengan bimbingan dalam Datuk Harimau dan menabur Congkak satu demi satu.", "materials": ["Lorong berkon yang sama", "Papan congkak pasangan", "42 buah bagi satu papan"], "teacher": ["Guru menunjukkan arah pulang sebelum pusingan Datuk Harimau. Dari tempat tetapnya, guru menyebut langkah satu demi satu.", "Guru menunjuk rumah tengah dan rumah seterusnya dalam Congkak. Guru memberi masa murid membuka jari sendiri tanpa menabur bagi pihaknya."], "pupil_steps": ["Murid bertanya waktu bersama pasangan dan mengambil langkah kecil dalam lorong Datuk Harimau mengikut sebutan guru.", "Murid berpusing selepas Waktu makan, berjalan pulang dan berhenti di rumah selamat dengan petunjuk guru.", "Murid menggenggam isi rumah tengah Congkak sendiri. Murid menabur satu buah ke rumah yang ditunjuk mengikut arah.", "Murid menyerahkan giliran selepas buah terakhir. Murid menyebut cara pulang dan cara menabur kepada pasangan dengan bantuan soalan guru."], "product": "Lakuan sendiri pulang dalam Datuk Harimau dan satu genggaman Congkak yang ditabur oleh murid; bantuan dicatat.", "criterion": "Murid kembali ke rumah selamat dalam Datuk Harimau dan melepaskan satu buah bagi setiap rumah Congkak dengan bimbingan.", "next_step": "Ulang bahagian yang belum jelas: guru tunjuk arah pulang sebelum pusingan seterusnya dan menunjuk rumah seterusnya ketika giliran Congkak. Bantuan dikekalkan.", "example": {"teacher": "Selepas Waktu makan, ke mana kamu pulang? Selepas buah terakhir, siapa bermain?", "pupil": "Saya pulang ke rumah saya. Selepas buah habis, giliran pasangan saya."}}, "core": {"label": "Pembina", "support_description": "Murid berlatih berpasangan dan melakukan sendiri.", "task": "Bergerak bersama pasangan tanpa bersentuh dalam Datuk Harimau dan mengambil giliran Congkak sendiri.", "materials": ["Dua lorong bersebelahan", "Satu papan congkak bagi pasangan", "42 buah bagi satu papan"], "teacher": ["Guru memberi isyarat suara yang jelas dan menyemak kedua-dua murid berhenti dalam rumah selamat Datuk Harimau.", "Guru memeriksa arah Congkak dan mengingatkan pasangan menunggu sehingga genggaman habis sebelum menyentuh buah."], "pupil_steps": ["Pasangan bertanya waktu Datuk Harimau. Setiap murid melangkah dan berhenti dalam lorong sendiri.", "Murid berpusing dan berjalan pantas pulang selepas Waktu makan. Murid memberi ruang kepada pasangan tanpa menarik tangannya.", "Murid mengambil isi rumah tengah Congkak pada gilirannya dan menabur satu demi satu dari kanan ke kiri.", "Murid memberi giliran pasangan, kemudian membantu menyusun semula papan. Setiap murid menyebut cara bermain kedua-dua permainan dan memberi pujian ringkas."], "product": "Kepulangan Datuk Harimau dalam lorong sendiri dan taburan Congkak bergilir bagi setiap murid.", "criterion": "Setiap murid menunjukkan langkah pulang Datuk Harimau yang terkawal serta taburan Congkak satu buah setiap rumah sebelum bertukar giliran.", "next_step": "Guru membetulkan satu perkara pada langkah pulang dan satu perkara pada taburan jika perlu; pasangan tidak mengambil alih pergerakan atau buah.", "example": {"teacher": "Bagaimana kamu memberi ruang kepada rakan semasa bergerak dan semasa menabur?", "pupil": "Saya guna lorong sendiri. Saya tunggu buah terakhir sebelum mengambil giliran Congkak."}}, "challenge": {"label": "Pencabar", "support_description": "Murid memperkemas satu perkara dalam kemahiran yang sama.", "task": "Memperkemas hentian Datuk Harimau dan pelepasan buah Congkak tanpa menambah kelajuan.", "materials": ["Lorong berkon yang sama", "Papan congkak pasangan", "42 buah bagi satu papan"], "teacher": ["Guru meminta murid memperlahankan langkah akhir ketika pulang dalam Datuk Harimau, bukan berlumba sampai dahulu.", "Guru menunjukkan tangan rendah di atas rumah Congkak supaya buah tidak melantun; bantuan arah tetap boleh diberi."], "pupil_steps": ["Murid mendengar jawapan Datuk Harimau sebelum melangkah dan berhenti dengan kaki stabil.", "Murid berpusing, berjalan pulang dalam lorong sendiri dan memperlahankan langkah akhir di rumah selamat.", "Murid menggenggam isi rumah tengah Congkak dan melepaskan buah rendah di atas setiap rumah tanpa melontarnya.", "Murid menyerahkan giliran selepas genggaman habis. Murid memberitahu pasangan satu perkara yang diperbaik dalam Datuk Harimau dan Congkak."], "product": "Hentian pulang Datuk Harimau yang lebih terkawal dan taburan Congkak yang tidak melantun keluar; bukti individu.", "criterion": "Murid berhenti stabil dalam Datuk Harimau dan menabur Congkak satu demi satu dengan tangan dekat papan.", "next_step": "Kekalkan laluan dan jumlah buah yang sama. Terus bantu cara berpusing atau melepaskan buah jika masih perlu; tiada tambahan jarak atau kelajuan.", "example": {"teacher": "Apa yang kamu buat supaya selamat ketika pulang dan buah tidak terpelanting?", "pupil": "Saya perlahankan langkah akhir. Saya letak tangan dekat rumah Congkak."}}}, "differentiation_delivery": {"common_task": "Murid dapat menggunakan langkah terkawal dalam Datuk Harimau dan menggenggam serta menabur buah Congkak satu demi satu dengan selamat.", "placement": "Bimbingan ini diberikan dalam waktu latihan dan aplikasi. Murid tidak perlu menjalani tiga kumpulan bantuan sebagai aktiviti tambahan.", "teacher_rounds": ["Semasa Datuk Harimau, guru kekal sebagai harimau dan memerhatikan nama dalam setiap kumpulan kecil. Catat selepas semua berhenti.", "Semasa Congkak, guru bergerak dari papan ke papan dan melihat kedua-dua rakan menabur sendiri. Soalan kognitif dan perasaan diselitkan pada giliran mereka."], "individual_check": "Bergerak dan kembali ke rumah selamat dalam Datuk Harimau serta menabur satu genggaman Congkak mengikut arah.", "flexible_help": "Bantuan diteruskan selagi diperlukan. Murid tidak dipaksa menambah kelajuan, jarak, beban atau ulangan untuk menunjukkan kemajuan."}, "pbd": {"method": "Pemerhatian amali setiap murid dalam pusingan Datuk Harimau dan ketika giliran Congkak sendiri.", "evidence": "Catatan bernama tentang langkah, pusingan dan kepulangan Datuk Harimau serta genggaman dan taburan Congkak murid yang sama; bantuan direkod berasingan.", "criterion": "Murid bergerak dan pulang dengan selamat dalam Datuk Harimau serta menggenggam dan melepaskan buah Congkak satu demi satu mengikut arah. Kedua-dua lakuan mesti diperhatikan.", "recording": "Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP.", "sample_checklist": ["Nama murid: ____.", "Datuk Harimau — langkah dan pulang sendiri: ____; bantuan: ____.", "Congkak — genggam, arah dan satu buah setiap rumah: ____; bantuan: ____.", "Bahagian belum dicuba atau belum diperhatikan: ____; susulan: ____."]}, "pbd_complementary": {"2.9.1": {"method": "Soal jawab individu sambil menunjuk laluan Datuk Harimau dan papan Congkak selepas percubaan sendiri.", "evidence": "Jawapan setiap murid tentang pulang apabila Waktu makan dalam Datuk Harimau dan satu buah setiap rumah atau pertukaran giliran Congkak.", "criterion": "Murid menyebut satu cara bermain Datuk Harimau dan satu cara bermain Congkak mini, bukan sekadar menyebut nama permainan.", "recording": "Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP.", "sample_checklist": ["Nama murid: ____.", "Datuk Harimau — cara pulang yang disebut: ____.", "Congkak — cara taburan atau giliran yang disebut: ____.", "Soalan bantu dan bahagian belum jelas: ____."]}, "5.4.1": {"method": "Pemerhatian individu ketika pasangan bertanya dan bergerak dalam Datuk Harimau serta berselang giliran Congkak.", "evidence": "Perbuatan setiap murid memberi ruang kepada pasangan dalam Datuk Harimau dan menjalankan serta menyerahkan giliran sendiri dalam Congkak.", "criterion": "Kedua-dua murid terlibat sendiri secara berpasangan dalam Datuk Harimau dan Congkak; seorang murid tidak mewakili kerja pasangannya.", "recording": "Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP.", "sample_checklist": ["Nama murid: ____; pasangan: ____.", "Datuk Harimau — turut bertanya, bergerak dan memberi ruang: ____.", "Congkak — giliran sendiri dan memberi giliran: ____.", "Bimbingan yang masih diperlukan: ____."]}, "5.4.2": {"method": "Pemerhatian dan pertanyaan mesra kepada setiap murid tentang rasa seronok dalam kumpulan Datuk Harimau serta kumpulan kecil Congkak.", "evidence": "Respons sebenar setiap murid, seperti menyatakan seronok bermain Datuk Harimau bersama rakan atau menunjukkan minat meneruskan giliran Congkak. Catat kedua-dua konteks, bukan senyuman ketua kumpulan.", "criterion": "Murid menunjukkan atau menyatakan keseronokan semasa Datuk Harimau dan Congkak bersama kumpulan. Jika respons belum jelas, catat dan tanya tanpa memaksa senyum atau jawapan positif.", "recording": "Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP.", "sample_checklist": ["Nama murid: ____.", "Datuk Harimau — respons atau tingkah laku sebenar: ____.", "Congkak — respons atau tingkah laku sebenar: ____.", "Keselesaan, rehat atau susulan yang diperlukan: ____."]}}, "intervention": "Jika langkah pulang belum selamat, tunjuk semula arah sebelum kumpulan bergerak. Jika buah terlepas banyak serentak, bimbing jari di atas rumah Congkak tanpa mengambil alih. Semak semula kedua-dua aktiviti bagi murid yang belum mendapat bukti lengkap; tiada pencapaian diandaikan.", "book_pages_text": "42", "sp_focus": "", "sp_display": "1.10.1", "complementary": [{"standard_key": "2.9.1", "sp_code": "2.9.1", "sp_text": "Mengenal pasti cara bermain permainan tradisional.", "sk_code": "2.9", "sk_text": "Mengaplikasi strategi dan idea kreatif dalam aktiviti rekreasi dan kesenggangan.", "domain": "kognitif", "source_label": ""}, {"standard_key": "5.4.1", "sp_code": "5.4.1", "sp_text": "Mempamerkan aktiviti secara berpasangan.", "sk_code": "5.4", "sk_text": "Membentuk kumpulan dan bekerjasama dalam kumpulan semasa melakukan aktiviti.", "domain": "afektif", "source_label": ""}, {"standard_key": "5.4.2", "sp_code": "5.4.2", "sp_text": "Mempamerkan rasa seronok semasa melakukan aktiviti dalam kumpulan.", "sk_code": "5.4", "sk_text": "Membentuk kumpulan dan bekerjasama dalam kumpulan semasa melakukan aktiviti.", "domain": "afektif", "source_label": ""}], "draft_sha256": "4df97fe382052cf8c49133efd164e21c0962c64a7843014bf21afe1c559ff2b5"}'::jsonb,'[{"kind": "title", "text": "Minggu 31 Sesi 1 — Kenal rumah selamat dan genggam buah Congkak"}, {"kind": "subtitle", "text": "Pendidikan Jasmani Tahun 1 | Dua sesi seminggu | 30 minit setiap sesi | R1"}, {"kind": "p", "text": "ID: PJ1-2026B-2S-W31-S1"}, {"kind": "h2", "text": "A. Maklumat pengajaran"}, {"kind": "p", "text": "Guru: ____________________ | Kelas: __________ | Tarikh: __________ | Waktu: __________"}, {"kind": "p", "text": "Unit 6: Mari Bersantai"}, {"kind": "p", "text": "Tajuk buku teks: Santai Petang"}, {"kind": "p", "text": "Aktiviti guru: Kenal rumah selamat dan genggam buah Congkak"}, {"kind": "p", "text": "Rujukan buku teks PJPK Tahun 1, bahagian PJ: muka surat 42."}, {"kind": "p", "text": "30 minit merangkumi persediaan, pemanasan, tunjuk cara, Datuk Harimau sembilan minit, Congkak tujuh minit dan penyejukan. Pertukaran, rehat dan minum termasuk dalam masa fasa; ulangan tidak mendahului giliran pertama setiap murid."}, {"kind": "h2", "text": "B. Standard dan hasil pembelajaran"}, {"kind": "p", "text": "SK utama 1.10: Melakukan aktiviti rekreasi dan kesenggangan."}, {"kind": "p", "text": "SP utama 1.10.1: Menggunakan kemahiran lokomotor dan manipulasi semasa melakukan permainan tradisional seperti Datuk Harimau dan Congkak."}, {"kind": "p", "text": "SK sokongan 2.9: Mengaplikasi strategi dan idea kreatif dalam aktiviti rekreasi dan kesenggangan."}, {"kind": "p", "text": "SP sokongan 2.9.1: Mengenal pasti cara bermain permainan tradisional."}, {"kind": "p", "text": "SK sokongan 5.4: Membentuk kumpulan dan bekerjasama dalam kumpulan semasa melakukan aktiviti."}, {"kind": "p", "text": "SP sokongan 5.4.1: Mempamerkan aktiviti secara berpasangan."}, {"kind": "p", "text": "SK sokongan 5.4: Membentuk kumpulan dan bekerjasama dalam kumpulan semasa melakukan aktiviti."}, {"kind": "p", "text": "SP sokongan 5.4.2: Mempamerkan rasa seronok semasa melakukan aktiviti dalam kumpulan."}, {"kind": "label", "text": "Objektif"}, {"kind": "p", "text": "Murid dapat menggunakan langkah terkawal dalam Datuk Harimau dan menggenggam serta menabur buah Congkak satu demi satu dengan selamat."}, {"kind": "label", "text": "Kriteria kejayaan"}, {"kind": "p", "text": "1. Bergerak dan kembali ke rumah selamat dalam Datuk Harimau serta menabur satu genggaman Congkak mengikut arah."}, {"kind": "p", "text": "2. Menyebut satu cara bermain Datuk Harimau dan satu cara bermain Congkak."}, {"kind": "p", "text": "3. Mengambil giliran sendiri bersama pasangan dalam kedua-dua permainan."}, {"kind": "p", "text": "Pengetahuan sedia ada: Murid pernah berjalan mengikut arahan dan memindahkan benda kecil. Guru menyemak pengalaman bermain tanpa menganggap semua murid sudah tahu peraturan."}, {"kind": "h2", "text": "C. Alatan, persediaan dan keselamatan"}, {"kind": "label", "text": "Kon penanda"}, {"kind": "p", "text": "Keperluan: 15 kon: 12 bagi enam lorong, satu untuk guru dan dua untuk tempat menunggu."}, {"kind": "p", "text": "Kegunaan: Menandakan mula, hujung dan ruang menunggu dari sisi laluan; tiada kon di tempat kaki melangkah."}, {"kind": "label", "text": "Papan congkak sebenar"}, {"kind": "p", "text": "Keperluan: Satu papan bagi setiap pasangan; tujuh rumah anak pada setiap sisi dan satu rumah ibu pada setiap hujung."}, {"kind": "p", "text": "Kegunaan: Setiap murid menggenggam dan menabur buah pada gilirannya sendiri."}, {"kind": "label", "text": "Buah congkak licin bukan kaca dan bekas simpanan"}, {"kind": "p", "text": "Keperluan: 42 buah bagi setiap papan, tiga bagi setiap rumah anak; satu bekas bagi setiap papan."}, {"kind": "p", "text": "Kegunaan: Buah sesuai untuk umur murid, boleh digenggam dan tidak tajam; rumah ibu kosong ketika mula."}, {"kind": "label", "text": "Air minuman sendiri dan jam guru"}, {"kind": "p", "text": "Keperluan: Satu botol bagi setiap murid dan satu jam guru."}, {"kind": "p", "text": "Kegunaan: Rehat, minum dan mengurus pertukaran kumpulan."}, {"kind": "label", "text": "Persediaan guru"}, {"kind": "p", "text": "1. Guru menyusun enam lorong selari di permukaan rata yang kering. Dua kon diletakkan di sisi setiap lorong untuk menunjukkan rumah selamat di titik mula dan had hujung."}, {"kind": "p", "text": "2. Jarak setiap lorong cukup untuk tiga langkah kecil dengan ruang berhenti. Jarak antara murid membolehkan tangan dibuka tanpa menyentuh rakan. Kurangkan bilangan lorong aktif jika ruang sempit."}, {"kind": "p", "text": "3. Guru berdiri tetap di belakang konnya, jauh di hadapan had hujung murid. Dua kon lain menandakan tempat menunggu di luar laluan dan dalam pandangan guru."}, {"kind": "p", "text": "4. Papan congkak diletakkan stabil di kawasan teduh di luar lorong. Isi tiga buah pada setiap rumah anak, jumlah 42 buah bagi satu papan. Kosongkan kedua-dua rumah ibu."}, {"kind": "p", "text": "5. Guru mengira dan memeriksa buah sebelum serta selepas aktiviti. Buah yang terlalu kecil, retak atau tidak sesuai tidak digunakan."}, {"kind": "label", "text": "Susunan dan giliran murid"}, {"kind": "p", "text": "1. Kekalkan pasangan. Sehingga tiga pasangan, paling banyak enam murid, bermain Datuk Harimau serentak dalam lorong sendiri. Setiap pasangan berada dalam dua lorong bersebelahan, bukan berpegangan tangan."}, {"kind": "p", "text": "2. Kumpulan lain duduk tenang di tempat menunggu dan melihat. Guru menamatkan pusingan dahulu sebelum memanggil kumpulan seterusnya. Semua kumpulan mendapat pusingan sebelum sebarang ulangan."}, {"kind": "p", "text": "3. Semasa Congkak, semua pasangan bermain pada papan masing-masing. Dua atau tiga pasangan duduk berdekatan sebagai kumpulan kecil tanpa berkongsi giliran pemain."}, {"kind": "p", "text": "4. Guru menetapkan siapa bermula pada setiap papan. Pasangan berselang giliran satu genggaman; setiap murid melakukan sendiri, bukan seorang wakil pasangan."}, {"kind": "p", "text": "5. Murid boleh berehat atau minum selepas memberitahu guru. Guru merekod bahagian yang belum dicuba dan mengatur susulan, bukan mengisi pencapaian bagi murid yang hanya memerhati."}, {"kind": "label", "text": "Petunjuk pergerakan"}, {"kind": "p", "text": "1. Datuk Harimau: tanya Pukul berapa, Datuk Harimau? Ambil langkah kecil mengikut jawapan guru antara satu hingga tiga. Berhenti sebelum had hujung."}, {"kind": "p", "text": "2. Apabila guru menyebut Waktu makan, pusing dahulu. Pandang rumah selamat dan berjalan pantas pulang dalam lorong sendiri. Berhenti tanpa menyentuh rakan."}, {"kind": "p", "text": "3. Congkak: genggam semua buah daripada sebuah rumah anak berisi pada sisi sendiri. Tapak tangan menadah dan tangan dekat dengan papan."}, {"kind": "p", "text": "4. Mula menabur di rumah anak seterusnya dari kanan ke kiri pada sisi sendiri. Lepaskan satu buah bagi setiap rumah. Masukkan buah ke rumah ibu sendiri jika dilalui, kemudian teruskan di sisi lawan; langkau rumah ibu lawan."}, {"kind": "p", "text": "5. Dalam latihan mini ini, selepas buah terakhir dilepaskan, letak tangan di sisi papan dan beri giliran pasangan. Tiada mengambil semula isi rumah terakhir, menangkap buah atau giliran tambahan."}, {"kind": "label", "text": "BBM"}, {"kind": "p", "text": "1. Kon penanda — 15 kon: 12 bagi enam lorong, satu untuk guru dan dua untuk tempat menunggu."}, {"kind": "p", "text": "2. Papan congkak sebenar — Satu papan bagi setiap pasangan; tujuh rumah anak pada setiap sisi dan satu rumah ibu pada setiap hujung."}, {"kind": "p", "text": "3. Buah congkak licin bukan kaca dan bekas simpanan — 42 buah bagi setiap papan, tiga bagi setiap rumah anak; satu bekas bagi setiap papan."}, {"kind": "p", "text": "4. Air minuman sendiri dan jam guru — Satu botol bagi setiap murid dan satu jam guru."}, {"kind": "p", "text": "5. Buku teks dan senarai semak pemerhatian guru."}, {"kind": "p", "text": "PAK-21: Dalam Datuk Harimau, pasangan bertanya waktu bersama tetapi bergerak dalam lorong berasingan. Dalam Congkak, seorang menabur dan pasangannya melihat arah; kemudian bertukar. Kumpulan kecil memberi pujian ringkas tanpa mengambil alih giliran."}, {"kind": "p", "text": "Nilai: Kerjasama, disiplin dan menjaga keselamatan rakan."}, {"kind": "label", "text": "Keselamatan"}, {"kind": "p", "text": "1. Guru memeriksa pakaian, tali kasut, keadaan murid, permukaan tempat aktiviti dan alatan sebelum bermula."}, {"kind": "p", "text": "2. Murid berhenti dan memberitahu guru jika sakit, pening atau sukar bernafas. Rehat dan minum dibenarkan mengikut keperluan."}, {"kind": "p", "text": "3. Guru memastikan semua murid berada dalam pandangannya. Murid tidak menolak, menarik atau menghalang laluan rakan."}, {"kind": "p", "text": "4. Datuk Harimau ialah adaptasi guru tanpa sentuhan dan tanpa kejar-mengejar. Guru kekal di belakang kon; tiada menangkap, menolak, menyekat, menyingkir atau memaksa murid berlari."}, {"kind": "p", "text": "5. Selepas Waktu makan, murid berpusing dengan tenang lalu berjalan pantas dalam lorong sendiri. Murid berhenti stabil di rumah selamat. Jangan mengundur laju atau memotong lorong."}, {"kind": "p", "text": "6. Hanya satu kumpulan kecil aktif. Kumpulan menunggu berada di luar laluan dan tetap dalam pandangan guru. Hentikan pusingan jika laluan terganggu."}, {"kind": "p", "text": "7. Buah congkak tidak dimasukkan ke mulut, hidung atau telinga dan tidak dibaling. Tangan berada rendah di atas papan. Buah yang jatuh dikutip selepas semua tangan berhenti."}, {"kind": "p", "text": "8. Guru memantau risiko tercekik. Jika buah tidak sesuai atau murid masih memasukkan benda ke mulut, tangguhkan amali Congkak murid berkenaan sehingga alat dan pengawasan selamat tersedia; catat bahagian belum dilaksanakan."}, {"kind": "p", "text": "Jika cuaca atau ruang tidak sesuai: Jika hujan, kilat, panas melampau atau lantai licin, guru menggunakan ruang berbumbung yang selamat. Jika ruang tidak sesuai, aktiviti berisiko ditangguhkan dan perkara yang belum dilaksanakan dicatat."}, {"kind": "h2", "text": "D. Langkah PdP"}, {"kind": "h3", "text": "Langkah 1: Persediaan murid dan alatan — 2 minit"}, {"kind": "p", "text": "Minit 0 hingga 2."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru memeriksa pakaian, tali kasut, keadaan murid dan alatan."}, {"kind": "p", "text": "2. Guru menerangkan tempat mula, laluan aktiviti dan arahan berhenti."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid memberitahu guru jika tidak sihat."}, {"kind": "p", "text": "2. Murid mengambil tempat yang ditetapkan dan mendengar arahan."}, {"kind": "p", "text": "Semakan: Semua murid tahu tempat menunggu dan boleh berhenti apabila diarahkan."}, {"kind": "p", "text": "Alatan: Kon penanda Papan congkak sebenar Buah congkak licin bukan kaca dan bekas simpanan Air minuman sendiri dan jam guru"}, {"kind": "h3", "text": "Langkah 2: Pemanasan badan — 4 minit"}, {"kind": "p", "text": "Minit 2 hingga 6."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru memimpin berjalan setempat dan langkah ke sisi selama dua minit."}, {"kind": "p", "text": "2. Guru membimbing gerakan ringan bahu, tangan, buku lali dan lutut selama dua minit."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid bergerak dalam ruang sendiri tanpa bersentuh."}, {"kind": "p", "text": "2. Murid bernafas seperti biasa dan berehat jika perlu."}, {"kind": "p", "text": "Semakan: Murid bersedia untuk aktiviti tanpa terlalu penat."}, {"kind": "p", "text": "Alatan: Ruang lapang Kon penanda"}, {"kind": "h3", "text": "Langkah 3: Tunjuk cara kedua-dua permainan — 4 minit"}, {"kind": "p", "text": "Minit 6 hingga 10."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru menjelaskan bahawa Datuk Harimau hari ini tidak melibatkan sentuhan atau kejar-mengejar. Guru menunjukkan rumah selamat, satu langkah kecil dan cara berpusing sebelum pulang."}, {"kind": "p", "text": "2. Guru menunjukkan papan Congkak sebenar: sisi sendiri, tujuh rumah anak dan rumah ibu. Guru menggenggam isi rumah tengah lalu menabur satu demi satu dari kanan ke kiri."}, {"kind": "p", "text": "3. Guru menunjukkan tempat memasukkan buah ke rumah ibu sendiri dan tempat melangkau rumah ibu lawan. Guru menegaskan bahawa latihan hari ini tamat selepas satu genggaman walau di mana buah terakhir jatuh."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid menunjuk rumah selamat sendiri dan meniru pusingan perlahan di tempat tanpa bersentuh."}, {"kind": "p", "text": "2. Murid melihat tangan guru, menunjuk sisi papan sendiri dan menyebut Satu buah, satu rumah."}, {"kind": "p", "text": "3. Pasangan menyebut siapa bermula dan siapa bermain selepas genggaman pertama habis."}, {"kind": "p", "text": "Semakan: Murid mengenal tempat pulang dan arah taburan; melihat tunjuk cara belum dikira sebagai amali sendiri."}, {"kind": "p", "text": "Alatan: Kon penanda Papan congkak sebenar Buah congkak"}, {"kind": "h3", "text": "Langkah 4: Datuk Harimau: pulang dalam lorong sendiri — 9 minit"}, {"kind": "p", "text": "Minit 10 hingga 19."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru memanggil kumpulan pertama, paling banyak enam murid. Guru kekal di belakang kon sebagai harimau; setiap murid bermula di rumah selamat sendiri."}, {"kind": "p", "text": "2. Guru menjawab satu, dua atau tiga selepas soalan Pukul berapa, Datuk Harimau? Satu soalan sahaja bagi satu pusingan. Guru menunggu langkah murid berhenti sebelum menyebut Waktu makan."}, {"kind": "p", "text": "3. Guru memerhatikan murid berpusing dan berjalan pantas pulang tanpa mengejar sesiapa. Selepas semua berhenti stabil, guru menyebut Berhenti dan membenarkan kumpulan keluar ke sisi yang kosong."}, {"kind": "p", "text": "4. Guru memanggil kumpulan seterusnya hanya apabila laluan kosong. Guru menyemak setiap nama, memberi satu bantuan jika perlu serta bertanya cara pulang dan perasaan murid. Akhir fasa diperuntukkan untuk minum dan berjalan ke papan."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Pasangan bertanya waktu bersama. Setiap murid mengambil langkah kecil mengikut bilangan yang disebut guru lalu berhenti dalam lorong sendiri."}, {"kind": "p", "text": "2. Apabila mendengar Waktu makan, murid berpusing, memandang ke rumah selamat dan berjalan pantas pulang. Murid berhenti tanpa menolak atau memotong rakan."}, {"kind": "p", "text": "3. Murid menunggu arahan keluar sebelum berjalan ke tempat menunggu. Kumpulan lain duduk tenang dan memberi ruang kepada kumpulan seterusnya."}, {"kind": "p", "text": "4. Setiap murid menyebut cara pulangnya apabila ditanya. Murid boleh menyatakan rasa seronok atau rasa belum selesa tanpa dipaksa."}, {"kind": "p", "text": "Semakan: Guru merekod langkah dan kepulangan setiap murid. Semua kumpulan mendapat pusingan dahulu; tiada penyingkiran, perlumbaan atau bukti mengelak direka."}, {"kind": "p", "text": "Alatan: 15 kon penanda Jam guru Air minuman"}, {"kind": "h3", "text": "Langkah 5: Congkak: genggam dan tabur bergilir — 7 minit"}, {"kind": "p", "text": "Minit 19 hingga 26."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru memastikan papan setiap pasangan bermula dengan tiga buah pada setiap rumah anak, 42 buah semuanya dan rumah ibu kosong. Guru menetapkan pemain pertama; semua pasangan boleh berlatih serentak."}, {"kind": "p", "text": "2. Guru membimbing setiap murid mengambil semua buah dari rumah tengah berisi pada sisi sendiri. Murid menabur bermula di rumah seterusnya, dari kanan ke kiri, satu buah setiap rumah. Jika melalui rumah ibu sendiri, isikan satu; teruskan di sisi lawan dan langkau rumah ibu lawan."}, {"kind": "p", "text": "3. Guru menetapkan had satu genggaman sahaja. Buah terakhir menamatkan giliran, sama ada jatuh di rumah berisi, rumah kosong atau rumah ibu sendiri. Jangan kutip isi rumah terakhir, menangkap buah atau mendapat giliran tambahan; pasangan bermain selepas itu."}, {"kind": "p", "text": "4. Jika rumah dipilih kosong, guru meminta murid memilih rumah berisi di sisi sendiri; jangan mengambil genggaman kosong atau buah rakan. Selepas kedua-dua murid selesai, pasangan menyusun semula tiga buah setiap rumah anak dan mengosongkan rumah ibu. Pemain kedua tadi bermula pusingan berikutnya."}, {"kind": "p", "text": "5. Guru melihat tangan kedua-dua murid pada giliran masing-masing dan menyoal satu cara bermain. Pada akhir masa, jangan mula giliran baharu; habiskan genggaman yang sedang ditabur dengan tenang, kemudian simpan buah dalam bekas. Giliran belum siap dicatat."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid pertama menggenggam isi rumah tengah pada sisi sendiri dengan tapak tangan menadah. Pasangan melihat arah tanpa menyentuh buah pemain."}, {"kind": "p", "text": "2. Murid menabur satu buah ke satu rumah mengikut arah yang ditunjukkan. Selepas buah terakhir, murid meletakkan tangan di sisi papan dan menyebut Giliran awak."}, {"kind": "p", "text": "3. Murid kedua melakukan genggaman dan taburan sendiri. Selepas kedua-duanya selesai, pasangan menyusun semula isi papan dan menukar pemain yang bermula."}, {"kind": "p", "text": "4. Setiap murid menyebut cara menabur dan memberi respons tentang bermain bersama rakan. Buah yang jatuh dikutip hanya selepas kedua-dua tangan berhenti."}, {"kind": "p", "text": "Semakan: Bukti setiap murid meliputi genggaman, arah dan pelepasan buah, bersama bukti Datuk Harimau tadi. Nama atau pemerhatian terhadap rakan sahaja tidak mencukupi."}, {"kind": "p", "text": "Alatan: Papan congkak bagi setiap pasangan 42 buah congkak bagi setiap papan Bekas simpanan"}, {"kind": "h3", "text": "Langkah 6: Penyejukan badan dan penutup — 4 minit"}, {"kind": "p", "text": "Minit 26 hingga 30."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru memimpin berjalan perlahan selama satu minit dan regangan lembut tangan serta kaki selama dua minit."}, {"kind": "p", "text": "2. Guru memberi masa minum dan menanyakan satu perkara yang dipelajari."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid meregang mengikut keselesaan tanpa sentapan."}, {"kind": "p", "text": "2. Murid memberitahu guru jika masih tidak selesa dan membantu mengemas alatan ringan selepas arahan."}, {"kind": "p", "text": "Semakan: Tiada latihan kuat selepas penyejukan. Guru mencatat perkara yang perlu disusuli."}, {"kind": "p", "text": "Alatan: Air minuman Ruang rehat"}, {"kind": "p", "text": "Jumlah masa: 30 minit."}, {"kind": "label", "text": "Contoh arahan kelas"}, {"kind": "p", "text": "Guru: Dengar Waktu makan sebelum pulang. Di papan, lepaskan satu buah ke satu rumah."}, {"kind": "p", "text": "Murid: Murid berpusing dan pulang mengikut lorong, kemudian menggenggam serta menabur buah Congkak pada giliran sendiri."}, {"kind": "p", "text": "Semakan guru: Guru menyemak langkah pulang dan pelepasan buah setiap murid, bukan hanya jawapan kumpulan."}, {"kind": "h2", "text": "E. PdP terbeza", "anchor": "pdp-PJ1-2026B-2S-W31-S1"}, {"kind": "p", "text": "Tugasan bersama: Murid dapat menggunakan langkah terkawal dalam Datuk Harimau dan menggenggam serta menabur buah Congkak satu demi satu dengan selamat."}, {"kind": "p", "text": "Bimbingan ini diberikan dalam waktu latihan dan aplikasi. Murid tidak perlu menjalani tiga kumpulan bantuan sebagai aktiviti tambahan."}, {"kind": "label", "text": "Bimbingan guru"}, {"kind": "p", "text": "1. Semasa Datuk Harimau, guru kekal sebagai harimau dan memerhatikan nama dalam setiap kumpulan kecil. Catat selepas semua berhenti."}, {"kind": "p", "text": "2. Semasa Congkak, guru bergerak dari papan ke papan dan melihat kedua-dua rakan menabur sendiri. Soalan kognitif dan perasaan diselitkan pada giliran mereka."}, {"kind": "p", "text": "Semakan individu: Bergerak dan kembali ke rumah selamat dalam Datuk Harimau serta menabur satu genggaman Congkak mengikut arah."}, {"kind": "p", "text": "Bantuan diteruskan selagi diperlukan. Murid tidak dipaksa menambah kelajuan, jarak, beban atau ulangan untuk menunjukkan kemajuan."}, {"kind": "h3", "text": "Peneroka"}, {"kind": "p", "text": "Guru membimbing satu langkah pada satu masa."}, {"kind": "p", "text": "Tugasan: Pulang dengan bimbingan dalam Datuk Harimau dan menabur Congkak satu demi satu."}, {"kind": "label", "text": "Alatan"}, {"kind": "p", "text": "1. Lorong berkon yang sama"}, {"kind": "p", "text": "2. Papan congkak pasangan"}, {"kind": "p", "text": "3. 42 buah bagi satu papan"}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru menunjukkan arah pulang sebelum pusingan Datuk Harimau. Dari tempat tetapnya, guru menyebut langkah satu demi satu."}, {"kind": "p", "text": "2. Guru menunjuk rumah tengah dan rumah seterusnya dalam Congkak. Guru memberi masa murid membuka jari sendiri tanpa menabur bagi pihaknya."}, {"kind": "label", "text": "Langkah murid"}, {"kind": "p", "text": "1. Murid bertanya waktu bersama pasangan dan mengambil langkah kecil dalam lorong Datuk Harimau mengikut sebutan guru."}, {"kind": "p", "text": "2. Murid berpusing selepas Waktu makan, berjalan pulang dan berhenti di rumah selamat dengan petunjuk guru."}, {"kind": "p", "text": "3. Murid menggenggam isi rumah tengah Congkak sendiri. Murid menabur satu buah ke rumah yang ditunjuk mengikut arah."}, {"kind": "p", "text": "4. Murid menyerahkan giliran selepas buah terakhir. Murid menyebut cara pulang dan cara menabur kepada pasangan dengan bantuan soalan guru."}, {"kind": "p", "text": "Contoh guru: Selepas Waktu makan, ke mana kamu pulang? Selepas buah terakhir, siapa bermain?"}, {"kind": "p", "text": "Contoh respons murid: Saya pulang ke rumah saya. Selepas buah habis, giliran pasangan saya."}, {"kind": "p", "text": "Hasil individu: Lakuan sendiri pulang dalam Datuk Harimau dan satu genggaman Congkak yang ditabur oleh murid; bantuan dicatat."}, {"kind": "p", "text": "Kriteria: Murid kembali ke rumah selamat dalam Datuk Harimau dan melepaskan satu buah bagi setiap rumah Congkak dengan bimbingan."}, {"kind": "p", "text": "Susulan: Ulang bahagian yang belum jelas: guru tunjuk arah pulang sebelum pusingan seterusnya dan menunjuk rumah seterusnya ketika giliran Congkak. Bantuan dikekalkan."}, {"kind": "h3", "text": "Pembina"}, {"kind": "p", "text": "Murid berlatih berpasangan dan melakukan sendiri."}, {"kind": "p", "text": "Tugasan: Bergerak bersama pasangan tanpa bersentuh dalam Datuk Harimau dan mengambil giliran Congkak sendiri."}, {"kind": "label", "text": "Alatan"}, {"kind": "p", "text": "1. Dua lorong bersebelahan"}, {"kind": "p", "text": "2. Satu papan congkak bagi pasangan"}, {"kind": "p", "text": "3. 42 buah bagi satu papan"}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru memberi isyarat suara yang jelas dan menyemak kedua-dua murid berhenti dalam rumah selamat Datuk Harimau."}, {"kind": "p", "text": "2. Guru memeriksa arah Congkak dan mengingatkan pasangan menunggu sehingga genggaman habis sebelum menyentuh buah."}, {"kind": "label", "text": "Langkah murid"}, {"kind": "p", "text": "1. Pasangan bertanya waktu Datuk Harimau. Setiap murid melangkah dan berhenti dalam lorong sendiri."}, {"kind": "p", "text": "2. Murid berpusing dan berjalan pantas pulang selepas Waktu makan. Murid memberi ruang kepada pasangan tanpa menarik tangannya."}, {"kind": "p", "text": "3. Murid mengambil isi rumah tengah Congkak pada gilirannya dan menabur satu demi satu dari kanan ke kiri."}, {"kind": "p", "text": "4. Murid memberi giliran pasangan, kemudian membantu menyusun semula papan. Setiap murid menyebut cara bermain kedua-dua permainan dan memberi pujian ringkas."}, {"kind": "p", "text": "Contoh guru: Bagaimana kamu memberi ruang kepada rakan semasa bergerak dan semasa menabur?"}, {"kind": "p", "text": "Contoh respons murid: Saya guna lorong sendiri. Saya tunggu buah terakhir sebelum mengambil giliran Congkak."}, {"kind": "p", "text": "Hasil individu: Kepulangan Datuk Harimau dalam lorong sendiri dan taburan Congkak bergilir bagi setiap murid."}, {"kind": "p", "text": "Kriteria: Setiap murid menunjukkan langkah pulang Datuk Harimau yang terkawal serta taburan Congkak satu buah setiap rumah sebelum bertukar giliran."}, {"kind": "p", "text": "Susulan: Guru membetulkan satu perkara pada langkah pulang dan satu perkara pada taburan jika perlu; pasangan tidak mengambil alih pergerakan atau buah."}, {"kind": "h3", "text": "Pencabar"}, {"kind": "p", "text": "Murid memperkemas satu perkara dalam kemahiran yang sama."}, {"kind": "p", "text": "Tugasan: Memperkemas hentian Datuk Harimau dan pelepasan buah Congkak tanpa menambah kelajuan."}, {"kind": "label", "text": "Alatan"}, {"kind": "p", "text": "1. Lorong berkon yang sama"}, {"kind": "p", "text": "2. Papan congkak pasangan"}, {"kind": "p", "text": "3. 42 buah bagi satu papan"}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru meminta murid memperlahankan langkah akhir ketika pulang dalam Datuk Harimau, bukan berlumba sampai dahulu."}, {"kind": "p", "text": "2. Guru menunjukkan tangan rendah di atas rumah Congkak supaya buah tidak melantun; bantuan arah tetap boleh diberi."}, {"kind": "label", "text": "Langkah murid"}, {"kind": "p", "text": "1. Murid mendengar jawapan Datuk Harimau sebelum melangkah dan berhenti dengan kaki stabil."}, {"kind": "p", "text": "2. Murid berpusing, berjalan pulang dalam lorong sendiri dan memperlahankan langkah akhir di rumah selamat."}, {"kind": "p", "text": "3. Murid menggenggam isi rumah tengah Congkak dan melepaskan buah rendah di atas setiap rumah tanpa melontarnya."}, {"kind": "p", "text": "4. Murid menyerahkan giliran selepas genggaman habis. Murid memberitahu pasangan satu perkara yang diperbaik dalam Datuk Harimau dan Congkak."}, {"kind": "p", "text": "Contoh guru: Apa yang kamu buat supaya selamat ketika pulang dan buah tidak terpelanting?"}, {"kind": "p", "text": "Contoh respons murid: Saya perlahankan langkah akhir. Saya letak tangan dekat rumah Congkak."}, {"kind": "p", "text": "Hasil individu: Hentian pulang Datuk Harimau yang lebih terkawal dan taburan Congkak yang tidak melantun keluar; bukti individu."}, {"kind": "p", "text": "Kriteria: Murid berhenti stabil dalam Datuk Harimau dan menabur Congkak satu demi satu dengan tangan dekat papan."}, {"kind": "p", "text": "Susulan: Kekalkan laluan dan jumlah buah yang sama. Terus bantu cara berpusing atau melepaskan buah jika masih perlu; tiada tambahan jarak atau kelajuan."}, {"kind": "h2", "text": "F. Pentaksiran Bilik Darjah"}, {"kind": "p", "text": "PBD merekod langkah Datuk Harimau dan manipulasi Congkak sebenar. Permainan tanpa kejar-mengejar bukan bukti kemahiran mengelak. Congkak mini bukan bukti penguasaan semua peraturan permainan atau penetapan TP secara automatik."}, {"kind": "h3", "text": "PBD utama — SP 1.10.1"}, {"kind": "p", "text": "Kaedah: Pemerhatian amali setiap murid dalam pusingan Datuk Harimau dan ketika giliran Congkak sendiri."}, {"kind": "p", "text": "Bukti: Catatan bernama tentang langkah, pusingan dan kepulangan Datuk Harimau serta genggaman dan taburan Congkak murid yang sama; bantuan direkod berasingan."}, {"kind": "p", "text": "Kriteria: Murid bergerak dan pulang dengan selamat dalam Datuk Harimau serta menggenggam dan melepaskan buah Congkak satu demi satu mengikut arah. Kedua-dua lakuan mesti diperhatikan."}, {"kind": "p", "text": "Rekod: Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP."}, {"kind": "label", "text": "Senarai semak"}, {"kind": "p", "text": "1. Nama murid: ____."}, {"kind": "p", "text": "2. Datuk Harimau — langkah dan pulang sendiri: ____; bantuan: ____."}, {"kind": "p", "text": "3. Congkak — genggam, arah dan satu buah setiap rumah: ____; bantuan: ____."}, {"kind": "p", "text": "4. Bahagian belum dicuba atau belum diperhatikan: ____; susulan: ____."}, {"kind": "h3", "text": "PBD sokongan — SP 2.9.1"}, {"kind": "p", "text": "Kaedah: Soal jawab individu sambil menunjuk laluan Datuk Harimau dan papan Congkak selepas percubaan sendiri."}, {"kind": "p", "text": "Bukti: Jawapan setiap murid tentang pulang apabila Waktu makan dalam Datuk Harimau dan satu buah setiap rumah atau pertukaran giliran Congkak."}, {"kind": "p", "text": "Kriteria: Murid menyebut satu cara bermain Datuk Harimau dan satu cara bermain Congkak mini, bukan sekadar menyebut nama permainan."}, {"kind": "p", "text": "Rekod: Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP."}, {"kind": "label", "text": "Senarai semak"}, {"kind": "p", "text": "1. Nama murid: ____."}, {"kind": "p", "text": "2. Datuk Harimau — cara pulang yang disebut: ____."}, {"kind": "p", "text": "3. Congkak — cara taburan atau giliran yang disebut: ____."}, {"kind": "p", "text": "4. Soalan bantu dan bahagian belum jelas: ____."}, {"kind": "h3", "text": "PBD sokongan — SP 5.4.1"}, {"kind": "p", "text": "Kaedah: Pemerhatian individu ketika pasangan bertanya dan bergerak dalam Datuk Harimau serta berselang giliran Congkak."}, {"kind": "p", "text": "Bukti: Perbuatan setiap murid memberi ruang kepada pasangan dalam Datuk Harimau dan menjalankan serta menyerahkan giliran sendiri dalam Congkak."}, {"kind": "p", "text": "Kriteria: Kedua-dua murid terlibat sendiri secara berpasangan dalam Datuk Harimau dan Congkak; seorang murid tidak mewakili kerja pasangannya."}, {"kind": "p", "text": "Rekod: Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP."}, {"kind": "label", "text": "Senarai semak"}, {"kind": "p", "text": "1. Nama murid: ____; pasangan: ____."}, {"kind": "p", "text": "2. Datuk Harimau — turut bertanya, bergerak dan memberi ruang: ____."}, {"kind": "p", "text": "3. Congkak — giliran sendiri dan memberi giliran: ____."}, {"kind": "p", "text": "4. Bimbingan yang masih diperlukan: ____."}, {"kind": "h3", "text": "PBD sokongan — SP 5.4.2"}, {"kind": "p", "text": "Kaedah: Pemerhatian dan pertanyaan mesra kepada setiap murid tentang rasa seronok dalam kumpulan Datuk Harimau serta kumpulan kecil Congkak."}, {"kind": "p", "text": "Bukti: Respons sebenar setiap murid, seperti menyatakan seronok bermain Datuk Harimau bersama rakan atau menunjukkan minat meneruskan giliran Congkak. Catat kedua-dua konteks, bukan senyuman ketua kumpulan."}, {"kind": "p", "text": "Kriteria: Murid menunjukkan atau menyatakan keseronokan semasa Datuk Harimau dan Congkak bersama kumpulan. Jika respons belum jelas, catat dan tanya tanpa memaksa senyum atau jawapan positif."}, {"kind": "p", "text": "Rekod: Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP."}, {"kind": "label", "text": "Senarai semak"}, {"kind": "p", "text": "1. Nama murid: ____."}, {"kind": "p", "text": "2. Datuk Harimau — respons atau tingkah laku sebenar: ____."}, {"kind": "p", "text": "3. Congkak — respons atau tingkah laku sebenar: ____."}, {"kind": "p", "text": "4. Keselesaan, rehat atau susulan yang diperlukan: ____."}, {"kind": "h2", "text": "G. Refleksi dan intervensi"}, {"kind": "p", "text": "Murid yang telah diperhatikan: ____ daripada ____. Kemahiran yang dikuasai: __________. Murid yang masih memerlukan bimbingan atau belum mendapat giliran: __________."}, {"kind": "label", "text": "Intervensi"}, {"kind": "p", "text": "Jika langkah pulang belum selamat, tunjuk semula arah sebelum kumpulan bergerak. Jika buah terlepas banyak serentak, bimbing jari di atas rumah Congkak tanpa mengambil alih. Semak semula kedua-dua aktiviti bagi murid yang belum mendapat bukti lengkap; tiada pencapaian diandaikan."}]'::jsonb,'{"source_hold": "", "adaptation_note": "BT42 menamakan Datuk Harimau dan Congkak tanpa peraturan lengkap dalam teks. Kedua-dua permainan digunakan setiap sesi untuk lokomotor dan manipulasi. Versi mini Datuk Harimau tanpa sentuhan dan congkak tiga buah setiap rumah anak ialah latihan guru, bukan peraturan pertandingan penuh. Papan congkak dan buah sebenar yang selamat digunakan, bukan permainan kad.", "source_images_verified": true, "audio_verified": false, "ba_verified": false, "classroom_trial_performed": false}'::jsonb)
